INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-02-23', '요한복음', '2장 1절 ~ 11절', '참빛으로 사람에게 오신 예수', '3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

2023년 3월1일 요한복음2장 1절~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
4.주제만들기: 참빛으로 사람에게 오신 예수
5.하나님 찾기 (관찰)
-태초부터 계신 하나님
-하나님과 함께하시는 예수님
-모든 만물을 지으신 하나님
-생명이신 하나님
-참빛이신 예수님
-진리를 증언하시는 예수님
6.인간 찾기 (관찰)
-진리에 무감각한 사람들
-진리를 증언하는 침례요한
7.하나님 찾기 (해석) 질문과 대상
-세상이 만물의 주인이신 하나님은 왜 그분을 찾지않고 무지한 사람들을 포기하지 않으시고 찾으시는가?
-사람들을 그분이 만드신 소중한 자녀라고 여기시기 때문에 그럴 것이다. 어느 정상적인 부모가 사랑하는 자녀가 어두움에 있는데 방치할수 있겠는가? 
-그분의 자녀에게 좋은 것을 주시려는 부모의 마음 때문일 것이다. 빛으로 가면 세상에서 줄 수 없는 행복 평강 기쁨을 누릴수 있다. 세상 문화의 재미보다 더욱 주님과 동행하는 살을 살아야겠다 
8.인간 찾기(해석) 질문과 대상
-8절에 보면 요한은 빛이 아니라 빛에 대하여 증언하는 임무를 받았구나! 나도 주의 종으로써 복음을 전하는 도구로써의 임무에 충실함과 동시에 주님의 종 이라는 사실도 간직해야겠다. 주님의 영광을 위해서만 사명 감당해야겠다. 
-하나님은 그때 당시에 권력자인 왕들에게 증언자로 사용하지 않고 일반사람 요한을 선택하셨을까? 묵상하기
침례요한 입장 묵상하기
9. 적용(나)
-빛에 역할에 게으른 죄를 회개합니다 주님 용서하옵소서! 다시 복음의 도구로 잘 사용받기를 원합니다. 
-코로나로 인하여 멈추었던 노방전도를 다시 해야겠다 오를 오후에 거리 전도를 해야겠다
-조만간에 NKFC 임원들과 함께 노방전도 해야겠다. 거룩한 일에 분주해야겠다.    
10. 감동되는 단어 또는 구절 묵상 (영적 터치)
11. 믿음과 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-02-24', '요한복음', '2장 11절 ~ 20절', '은혜와 진리로 오신 임마누엘 하나님', '3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

2023년 3월2일 요한복음 1장 11절~20절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
4.주제만들기: 은혜와 진리로 오신 임마누엘 하나님
5.하나님 찾기 (관찰)
-자기 땅에 오신 하나님
-거부 당하시는 하나님
-자녀와 함께 하시는 하나님
-믿는 자에게 자녀의 권세를 주시는 하나님
-말씀이시며 우리 가운데 거하시는 하나님
-영광의 하나님
-은혜와 진리가 충만하신 예수님
-내 뒤에 오시지만 나보다 앞선 하나님
-은혜 위의 은혜를 충만하게 주시는 하나님
-은혜와 진리로 오신 하나님 
-독생하신 하나님이 우리 앞에 보이심
6.인간 찾기 (관찰)
-백성
-거부하는 자
-영접하는 자
-그 이름을 믿는 자
-하나님의 자녀 
-하나님의 뜻으로 난 자
-우리, 요한, 내가, 나, 우리가, 모세, 본 사람이 없음, 유대인들, 제사장들, 레위인들, 요한, 요한, 요한

7.하나님 찾기 (해석) 질문과 대상
-은혜와 진리가 충만하고 은혜와 진리로 오신 예수님.
-하나님의 말씀이시고, 하나님이신 예수님.
-이 성자 예수님은 은혜와 진리로 충만하시다. 그런데 충만함으로 끝나는 것이 아니라 예수님은 은혜 위에 있는 은혜. 즉, 은혜 자체 이시며, 은혜와 진리로 이 땅에 오셨다. 

8.인간 찾기(해석) 질문과 대상
-인류(유대인, 제사장, 레위인 등)는 이 예수님이 하나님이시라는 것을 믿지 못한다. 태초에 하나님과 가장 완전한 형태로 동행 인간, 아담과 하와가 하나님을 떠나 살기로 작정했기 때문에, 그 이후 인간은 하나님을 잊기로 작정했다.
-하나님은 하나님께 불순종함으로 전적으로 타락한 인간을 너무나 사랑하셔서 예수님을 이 땅에 보내셨고, 이것은 은혜 중의 은혜요, 진리 중의 진리이다.
다시 말해서 하나님의 완전한 사랑, 이것이 은혜 중의 은혜요, 진리 중의 진리이다. 그 사랑을 이루시기 위해 말씀이신 예수님이 성육신하셨다.

-우리는 사랑 자체이신 하나님께 나아가되, 오직 예수를 통해 나아가야 한다.  

9. 적용(나)
-우리 가운데 거하시는 예수님을 누리지 못하고, 
-나를 성전 삼으사 내 안에 거주하시는 성령님을 누리지 못하고,
교만, 불평, 원망, 우월감, 열등감, 분냄, 음란, 시기, 질투 등으로 하루를 살아가는 저를 봅니다.
내 안의 원수와의 싸움에서 늘 패배하고, 천국을 이루길 바라시며 보내신 가정과, 일터에서 늘 악한 생각을 하며 악한 태도로 살아가는 제 모습을 봅니다.

이런 비참한 나를 발견할때마다 하나님께 죄송합니다. 

그러나 이 비참한 나도 사랑하사 용서하신 예수님께 더욱 감사를 드리게 됩니다. 할렐루야!

말씀이신 예수님, 은혜 중의 은혜이신 예수님, 진리 중의 진리이신 예수님을 사랑합니다. 어찌 사랑하지 않을 수가 있겠습니까?

보내주신 모든 곳에서 예수님의 반사체가 되어 예수님을 드러내는 삶을 살아낼 수 있도록, 말씀과 기도로 무장하고 살아가겠습니다.

10. 감동되는 단어 또는 구절 묵상 (영적 터치) 
1장 14절
말씀이 육신이 되어 우리 가운데 거하시매 우리가 그의 영광을 보니 아버지의 독생자의 영광이요 은혜와 진리가 충만하더라

11. 믿음과 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-02-25', '요한복음', '2장 21절 ~ 35절', '예수님의 희생으로 비로소 깨끗해지는 성전', '3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
4.주제만들기 : 예수님의 희생으로 비로소 깨끗해지는 성전

5.하나님 찾기 (관찰) 
 - 유월절 예루살렘 성전 안에 있는 상인들을 쫓으시고 꾸짖으심
 - 예수님의 십자가의 죽음과 의미를 예언하심
 - 인간의 속을 아시고 인간에게 자신의 몸을 의탁하지 않으심

6.인간 찾기 (관찰)
 - 예수님의 표적으로 예수님을 믿는 제자들
 - 예수님의 표적을 보고도 의심하는 유대인들
 - 예수님의 성전 사건으로 예수님을 시기하고 오히려 표적을 보이라고 요구하는 유대인들

7.하나님 찾기 (해석) 
 - 하나님의 성전이 거룩해야 함을 알려주시는 예수님
 - 성전이 거룩해지기 위해선 자신의 희생이 있어야만 함을 알려주시는 예수님
 - 인간의 육신의 정욕, 안목의 정욕, 이생의 자랑에 대해 아시고 시험 당할 일을 만들지 않으시는 예수님

8.인간(해석):
 - 유월절 예루살렘 성전까지 제물을 가지고 오기 어려운 이들에게 편의를 제공한다는 명목으로 성전 안에 상인을 거래를 허락하고 상인들의 아부와 이스라엘 백성들로부터 칭찬을 받아 교만함이 생긴 유대인들은 유월절의 참된 의미와 성전의 의미를 잊고 있다. 
 - 예수님의 올바른 행동이 유대인들의 치부를 드러내자 노골적으로 표적을 요구하며 교만한 모습을 보인다. 
 - 표적을 보고 많은 이들이 예수님을 믿었으나 그들 중엔 안목의 정욕과 이생의 자랑을 충족하려는 이들이 많았을 것이다. 예수님께서는 그들로 인해 시험 받는 백성들이 없도록 그들에게 자신의 몸을 의탁하지 않으시며 자신의 의로움을 드러내셨다.  

9. 적용(나): 
 - 예수님의 성전인 나를 바라본다. 내 안에 있는 죄성이 예수님의 보혈의 피로 깨끗해지길 원한다. 예수님께서 성전을 거룩하게 하셨듯이 그 과정에 타협하고자 하는 수많은 유혹이 있으리라 생각되지만 오직 길이요 진리요 생명이신 주님만 의지하며 거룩한 성전이 되길 소망한다. 마음의 중심을 보시는 주님께 거룩함만이 내 안에 가득하도록 강구한다. 그리고 거룩함이 교만이 되어 죄가 되지 않길 소망한다. 

10. 영적터치(단어/구절)
성전, 속을 아시다.

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-02-26', '요한복음', '3장 1절 ~ 11절', '예수님께 찾아온 바리새인 니고데모', '3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

2023년 3월8일 요한복음3장 1절~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
니고데모: 3절 4절 9절
예수: 2절(3) 3절 5절 10절
하나님의 나라: 3절 5절
성령: 5절 8절
거듭남: 3 5 6 7
육: 6절(2)
영: 6절(2)
지도자: 1절 10절
4.주제만들기: 예수님께 찾아온 바리새인 니고데모
5.하나님 찾기 (관찰)
거듭남을 니고데모에게 가르치시는 예수

6.인간 찾기 (관찰)
밤에 예수를 찾은 니고데모 
표적에 관심있는 니고데모 
거듭남의 진리에 대하여 이해못하는 니고데모 

7.하나님 찾기 (해석) 
그때당시 예수님께 대적하는 세력중 한그룹이 바리새인들 이었다 그럼에도 바리새인 니고데모를 맞이하시는 예수님을 봅니다 조금 부족해도 예수님께 진리를 구하는 사람에게는 주님은 진리를 가르쳐주신다 
니고데모 는 표적을 행하는 능력의예수를 만나기 위해 왔지만 도리어 주님은 거듭남과 하나님나라를 조명해주셨다
즉 세상의 능력보다 영원한천국에 초점을 두신다 영원한 천국에 가기위해서는 주님을 영접함으로 거듭나는것은 필수이다
나도 늘 천국소망하며 살아야겠다
세상욕심을 버려야겠다
니고데모 는 얻기위해왔는데 주님은 우리의구원을 위해 목숨을 버리기위해 오셨다
내가 생활속에서 영적으로 시험들고 세상에서 욕심을 내는것은 내가 갈곳 하나님나라를 잠시잊고 살아서일것이다. 세상 욕심버리고 십자가를 바라보자!!

8.인간(해석):
 니고데모는 밤에 예수님을 만나기위해왔다 밤에 온것은 예수님을 배척하는 다른 바리새인 동료들의 시선을 피해서 왔을것이다 그렇다고 그를 겁쟁이라 말할수없다 왜냐하면 2절에 보니
"우리가 당신은 하나님께로 부터 오신 선생인 줄 아나이다" 라고 말한걸보면 마음은 있으나 다른시선때문에 오지못한 또다른 동료가 있음을 보여준다 그러므로 니고데모는 최소한 용기를가지고 진리를 알기위해 행동한사람이다
나도 주님보시기에 죄인이지만 늘 십자가보혈을 의지하여 회개하며 당당히 성경으로 들어가야겠다

9. 적용(나):
오후에 하나님나라 를 묵상하는 시간을 가져야겄다
 
10. 영적터치(단어/구절)
3절: 하나님나라

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-02-27', '요한복음', '3장 11절 ~ 21절', '그 무엇보다도 세상을 사랑하신 하나님', '3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

 

요한복음3장 11절~21절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
 우리: 11절 2번
 증언: 11절 2번
 하늘: 12절, 13절 2번
 믿는다: 12절, 15절, 16절, 18절 3번
 인자: 13절, 14절
 영생: 15절, 16절
 하나님: 16절, 17절, 18절, 21절
 세상: 16절, 17절 3번, 19절
 심판: 17절, 18절 2번
 빛: 19절 2번, 20절 2번, 21절
 악: 19절, 20절
 행위: 19절, 20절, 21절 2번
4.주제만들기: 그 무엇보다도 세상을 사랑하신 하나님
5.하나님 찾기 (관찰)
 -하늘의 것, 영에 대해 설명하시는 하나님(예수님)
 -세상을 사랑하되 얼마나 사랑하시는지 설명하시는 하나님
 -하나님과 분리된 자들은 이미 심판을 받은 것임을 설명하시는 하나님
 -하나님을 믿는 자들은 이미 천국을 살고 있는 것임을 설명하시는 하나님
6.인간 찾기 (관찰)
 -육의 눈으로는 영의 것을 볼 수 없음.
 -예수님은 영의 것을 말씀하시는데 니고데모를 비롯한 인간들은 육의 것만을 생각함.
 -영에 대해 알지 못하니 당연한 것.
 -거듭난다는 것은 영이 새로 태어난다는 것을 의미함.
 -육의 것만 보고 알던 니고데모가 영의 것, 하늘의 것에 대해 가르침을 받음.
 -하나님이 자신을 얼마나 사랑하시는지 가르침을 받음.
 -예수님을 믿고 따르는 자는 거듭남을 받고 이 땅에서 천국을 누리는 것이라는 것을 가르침 받음.
7.하나님 찾기 (해석) 
 -모세 시대에 이스라엘 백성이 큰 죄를 범했을 때 놋뱀이 들리고 그것을 바라본 자들이 나음을 입었던 것과 같이 우리가 죄 가운데 있을 때 예수님이 십자가에 들리실 것임
 -하나님은 우리를 위해 대신 죽으실 만큼이나 (이처럼) 우리를 사랑하심
 -우리가 죄인일 때에, 먼저 사랑하시고 그 놀라운 사랑을 실천하심으로 사랑을 성취하심.
 -사랑의 성취는 구원의 성취이며, 구원의 성취는 사랑의 성취임.
8.인간(해석):
 -불순종 이후 하나님을 피한 아담과 하와. 이것이 죄.
 -예수님이 오셨으나 인간들은 자신이 죄 속에 거했기 때문에 예수님을 피함. 아담과 하와를 닮음.
 -하나님과 분리된 것이 죄이고, 하나님을 믿지 않는 것이 죄임. 이 죄가 인간에게 가장 불행임.
 -그래서 이미 심판을 받은 것임.
 -믿지 않는 이들은 사탄(어둠)의 행위를 하나님보다 사랑함. 
 -하나님과 분리되어 자기 뜻대로 사는 것을 사랑하기 때문에 하나님을 피할 수밖에 없음.
 -불순종 후 하나님을 피했던 아담과 하와처럼. 
 -이것은 원죄의 유전이며 사탄의 유혹이 계속되기 때문이라고 생각됨.
 -하나님을 믿는 자들을 하나님(빛)께 더 나아감.
 -하나님을 믿는 자들은 하나님께 더 나아가고 동행함으로 이 땅에서 천국을 누리는 것임.
9. 적용(나):
 -어제도 오늘도 내일도 죄인인 나를 먼저 사랑하신 예수님께 늘 감사하며, 그 예수님을 항상  
 바라보도록 노력해야겠다.
 -사탄은 유혹하는 일을 멈추지 않을 것이다. 하나님과 분리되는 행동을 하지 않도록 말씀과  
 기도로 무장해야 한다.
10. 영적터치(단어/구절)
 3절: 사랑하사
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-03-01', '요한복음', '3장 21절 ~ 36절', '자신을 낮추고 예수님의 영광을 증언하는 요한', '2023년 3월10일 요한복음 3장 21절~36절

1.1분기도

2.본문성경 읽기(3번)

3.반복단어 찾기(형광펜 추천)

 - 요한, 세례,하늘, 신랑, 기쁨, 흥, 쇠, 증언, 영생

4.주제만들기 : 자신을 낮추고 예수님의 영광을 증언하는 요한

5.하나님 찾기 (관찰)

- 세례를 베푸시는 예수님

6.인간 찾기 (관찰)

- 예수님의 세례로 인해 많은 사람들이 예수님께 가자 이 사실을 요한에게 말하는 제자들

- 자신의 영광을 생각하지 않고 예수님의 존재를 들어내는 요한

7.하나님 찾기 (해석)

- 인간에게 세례를 베푸심으로 자신을 드러내신 예수님.

8.인간(해석):

- 요한의 곁에서 있던 제자들은 안목의 정욕과 이생의 자랑의 유혹에 흔들렸던 것으로 보인다. 요한에게 세례를 받던 사람들이 예수님께로 가자 그 사실을 요한에게 말하며 걱정한다. 그러나 요한은 자신의 존재를 예수님을 위해 보내심 받은 자이며 자신은 쇠하여야 하는 존재라는 것을 말한다.

9. 적용(나):

- 요한의 겸손함에 자신을 다시 한번 돌이켜 본다. 한 순간 모든 사람의 이목이 예수님께 집중되면 인간적인 마음으론 당연히 섭섭하거나 자존감이 낮아질 것 같지만 요한은 그렇지 않다. 자신의 존재를 인정하며 오히려 예수님의 영광을 드러낸다. 과연 나는 그렇게 할 수 있을까? 나는 NKFC가 더 성장하고 많은 이들이 집중하게 되면 내 자신이 얼마나 교만해질지 두렵다. 우리가 들인 시간과 노력의 대가라고 생각할까봐 두렵다. 예수님의 영광을 생각하는 것이 아니라 예전에 우리 이렇게 고생했었잖아 라고 생각하며 당연한 것이라 생각할까봐 두렵다. 요한처럼 내 역할을 정확히 바라보고 나를 인정하는 사람이 되어야겠다.

10. 영적터치(단어/구절)

- 그는 흥하여야 하겠고 나는 쇠하여야 하리라 하니라

11. 믿음과 회개 및 감사기도로 마무리

12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

