2023년 3월11일 요한복음4장 1절~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
예수: 1절 2절 6절 7절 9절 10절(3)
사마리아여인: 7절 9절(2) 10절(2)
사마리아: 4절 5절
제자들: 1절 2절 8절
물을달라:7절 9절 10절
세례: 1절 2절
주제: 사마리아 여인에게 물을달라 구하는 예수
5.하나님 찾기 (관찰)
사마리아 땅을 통과하시는 예수
피곤을 느끼시는 예수
물을 달라고 요청하는 예수
생명수인 자신을 소개하는 예수
6.인간 찾기 (관찰)
물길으러 우물로 온 사마리아 여인
