먹을것을 사러간 제자들

7.하나님 찾기 (해석) 
1절에 보면 예수는 자신에게 침례를 받는무리가 많아짐을 바리새인들이 들었음을 아신다 즉 자신의 높은 인기를 질투하는 바리새인들의 중심을 보시고 그곳에 떠나신다 떠나신 이유는 바리새인 세력이 부담이 되기때문이 아닌 인기에 안주하려는 것을 기피하신것 같다
예수님은 시종일관 영혹구원 그리고 십자가 보혈 만 생각하시는것 같다  
유대인들에게 왕따당하는 사마리아 여인에게 물을달라고 요청하며 접촉하며 복음을 우회적으로 전하신다 배척민족도 사랑하시는 예수님을 발견한다 소외된 한사람도 아끼시는 예수님의 섬세한 사랑을 느낀다
나도 그러한 주님의 사랑을 닮고싶다! 우리NKFC 회원중에 소외된사람을 잘 찾아봐야겠다!

8.인간(해석):
  6절에보니 유대인들에게 무시당하는 사마리아사람 그중에서도 한 여인이 우물을 얻기위해 우리시간 낮12시에 왔다
중동지역 은 더운 나라인데 정오에 왔다는 것은 사람을 피해왔다는 것을 알수있다

9. 적용(나):
오늘 평상시 접촉이 약한 NKFC 회원들에게 안부 문자메시지를 보내야겠다!
 
