1:감동받는 단어나 구절 찾기(영적터치)

2023년 3월11일 요한복음4장 11절~20절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
예수: 11절(2) 12절 13절 14절(2) 15절 17절 19절
사마리아여인: 11절 15절(2) 17절(2) 18절(2) 19절
물: 11절(2) 12절 13절 14절(3) 15절 
물길을: 11절 15절
목마름: 13절 14절 15절 
남편: 16절 17절(2) 18절(2)
예배: 20절(2)
야곱: 12절(2)
조상: 12절 20절
사마리아: 4절 5절
제자들: 1절 2절 8절
물을달라:7절 9절 10절

주제: 목마르지 않은 샘물이신 예수
5.하나님 찾기 (관찰)
목마른 물과 목마르지않은 물에 대해 말씀 하시는 예수
사마리아 여인의 남편을 부르시는 예수
사마리아 여인의 남편들을 아시는 예수
6.인간 찾기 (관찰)
생수에 대하여 이해못하는 사마리아 여인
예수를 선지자라 생각하는 여인
7.하나님 찾기 (해석) 
사람이 없는 정오에 물길으러 온 여인의 이유가 오늘 본문에 드러난다. 남편이5명이나 있었고 지금도 한 남자와 동거중이다. 외적으로 보수적인 중동문화에서 보면 그때당시 사회적으로 큰 약점이 되는것이다. 내적으로 보면 여인은 삶에 만족감이  없는것이다  그러한 여인의 내외적인 문제를 아시는 주님은 여인에게 근본적인 만족감을 해결할수있는 샘물에 대해 소개하신다  그 샘물은 예수그분이시고 육체가 말씀되신 성경이다  반면에 우리동포 국가인 북한은 진리의성경을 읽을수있는 자유를 금지시켰다 너무 가슴아픈 일이다! 북한에도 주님의 샘물을 누구든지 자유롭게 마실수있는 날이 속히 오기를 바란다!

8.인간(해석):
  예수님은 중요한 영생에 관하여 말씀하시는데 반해 여인은 육적인 우물에 관하여 반문한다 그러한 여인에게 드러내기 싫어하는 전남편들 상황을 말씀하신다. 그제서야 보통사람이 아니라고 생각하고 선지자 정도로 접근한다.
주님이 우리곁에 이미 계심에도 과거의 상처들이 커서 주님을 못볼수도있고 영웅정도로 그분을 축소시킬수도 있구나!
늘 성경을 묵상함으로 크신 하나님! 생명의 주님을 만나야겠다! 늘 만족한 삶을 살자!
9. 적용(나):
오늘 본문내용에 나오는 주님이 주시는 ''영원한샘물'' 에 대하여 깊이묵상해야겠다!
 
