주제: 하나님이 찾으시는 예배자
5.하나님 찾기 (관찰)
하나님은 영이심을 말씀하시는 예수님
영과 진리로 드리는 예배에 대하여 말씀하시는 예수님
자신이 메시야, 곧 그리스도라는 것을 말씀하시는 예수님

6.인간 찾기 (관찰)
메시야가 오시면 하나님과 예배에 대해 알려줄 것이라고 말하는 여자
여자와 이야기하는 예수님을 보며 이상히 여긴 제자들
동네 사람들에게 가서 그리스도를 만났다고 전하는 여자
그리스도를 만나러 동네에서 나온 사람들

7.하나님 찾기 (해석) 
영적으로 갈급함을 느끼지만 그것이 무엇인지 깨닫지 못하는 여인에게 하나님께 영과 진리로 예배드려야 함을 말씀하시는 예수님. 너의 갈증은 남편이 아니라 하나님께 예배드림으로 성령충만으로 해소할 수 있는 것임을 말씀하시는 예수님.
하나님은 영이셔서 예루살렘뿐만 아니라, 세상 모든 곳에 계심을 가르치시는 예수님.
예수님이 보내주실 성령님과 진리이신 예수님으로 예배를 드려야 함을 가르치시는 예수님.
지금 대화하고 있는 내가 바로 너가 찾고 기다리는 메시야임을 드러내시는 예수님.
사마리아 여인을 사랑하시고 긍휼히 여기시고 구원하시길 바라는 예수님.


8.인간(해석):
  하나님께 예배하는 곳이 꼭 예루살렘이여야 하는지 궁금한 사마리아 여인. 하나님께 예배드리는 것의 중요성을 알고 있었던 여인.
  개로 여기던 사마리아인, 그것도 여자와 이야기하는 예수님을 보고 이상히 여긴 제자들. 사마리아 사람들도 구원의 대상임을 깨닫지 못하고, 영적 우월감에 젖어 있는 제자들.
  유다 백성들이 개 취급하는 사마리아인들도 메시아를 간절히 기다리고 있음. 로마의 위협과 민족의 핍박 속에서 메시야를 간절히 기다리고 있던 사마리아인들.

9. 적용(나):
신분의 높고 낮음과 상관 없이 사랑하시고 귀하게 여기시고 구원하시는 예수님을 바라봐야 한다. 오늘 창체 선생님(시간제 계약직)이 아이들이 준비물(가위)을 안 가져 왔으니 나한테 갖다달라고 했을 때 마음 속으로 ‘이건 뭐지? 아이들이 교무실에 가서 빌려오거나 당신이 가야지!’ 라는 생각을 했다. ‘내가 이런 일 하는 사람이 아닌데?’ 물론 친절하게 갖다줬지만. 다녀 오면서 내가 왜 섬기지 못하고 그런 걸 생각하고 있는 걸까 생각하면서 나는 아니라고 하지만 교사라는 신분에 우월감을 갖고 있었음을 깨닫고 회개함.
앞으로 교사도 아닌 목사가 될 것인데 이런 더러운 생각을 지우도록 노력해야겠음.
 
10. 영적터치(단어/구절)
내가 그라 (26절) 

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-03-05', '요한복음', '4장 31절 ~ 40절', '제목 없음', '3331 생명의 큐티
3:하나님, 인간, 나
