1:감동받는 단어나 구절 찾기(영적터치)

2023년 3월 14일 요한복음 4장 31절~40절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
 - 잡수다, 양식, 추수, 뿌리는 자, 거두는 자, 노력, 유하시매
4.주제만들기
 - 예수님이 오신 이유와 제자들이 해야 할 일을 알려주심
5.하나님 찾기 (관찰)
 - 양식에 대해 설명해주시는 예수님
 - 뿌리는 자와 거둘자에 대해 알려주시는 예수님
 - 뿌리는 것과 거두는 것 모두 유익함을 알려주시는 예수님
6.인간 찾기 (관찰)
 - 육의 양식 외 영의 양식을 이해하지 못하는 제자들
 - 사회적 약자로 여겨지던 사마리아인들의 갈급함과 믿음
7.하나님 찾기 (해석) 
 - 예수님께선 육의 양식 외에 영의 양식으로 육이 충만해질 수 있다고 말씀해주시지만 제자들은 깨닫지 못한다. 예수님께선 추수하기 위해 씨앗을 뿌리는 자와 거두는 자 모두 즐거움을 누릴 수 있다고 말하신다. 
8.인간(해석): 예수님과 가장 가까운 곳에 있는 제자들은 예수님의 행동을 이해하지 못한다. 예수님께서 유대인이 아닌 사마리안인을 구원하리라 생각하지 못했거나 예수님의 큰 인기로 교만함이 제자들에게 생겼을지 모른다. 하지만 사마리아인들은 여인의 증언에 예수님을 믿고 예수님을 영접한다.

9. 적용(나): 예수님은 우리에게 먼저 찾아와 주시는 분이다. 제자들이 예수님의 존재에 무감각했던 것처럼 나 또한 예수님과 함께하지만 예수님의 존재에 대해 무감각해져있는 것 같은 생각이 들어 다시 주님의 존재를 인식하고 하루하루 살아가길 소망해본다. 예수님께선 뿌리는 자와 거두는 자가 함께 즐거워하게 하려 함이라라고 사역마다 역할이 있고 뿌리는 자는 거두는 것을 보지 못해도 즐겁고 뿌리지 못하더라도 거두는 자는 즐겁다고 했다. 뿌리는 사역에도 즐거움이 더 생기도록 기도해야겠다.
10. 영적터치(단어/구절)
뿌리는 자와 거두는 자가 함께 즐거워하게 하려 함이라

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-03-06', '요한복음', '4장 41절 ~ 54절', '제목 없음', '3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

2023년 3월15일 요한복음4장 41절~54절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
예수: 41절 42절(2) 43절 44절 45절(2) 46절 47절 48절 49절 50절(2) 53절 54절
왕의신하: 46절 47절 49절 50절 53절
왕의신하아들: 47절 49절 50절 51절 53절
병듬: 46절 47절 
살아남: 50절 51절 53절
표적: 48절 54절
주제: 왕의 신하 아들의 병을 말씀으로 고쳐주시는 예수

5.하나님 찾기 (관찰)
사마리아인들에게 진리를 말씀하시는 예수
고향인 갈릴리 로 가시는 예수
병을 고쳐주시는 예수
표적을 행하시는 예수

6.인간 찾기 (관찰)
예수를 믿는 사마리아인들
예수를 영접하는 갈릴리인들
예수께 병든아들을 고쳐달라고 애원하는 왕의신하
살아난 아들
표적을 보고 믿는 사람들
7.하나님 찾기 (해석) 
 사람들이 예수님자신의 능력 즉 표적이나 기적을 보고 믿는것에 대하여 아쉬워하신다
참다운 믿음은 우리죄를 위하여 죄없으신 주님께서 십자가에서 죽으신 사랑을 인정하는 것이다
그분이 우리 구세주인것을 믿는것이다 독생자 예수는 우리를 구원하기 위하여 희생물 이신 하나님의 선물이다 반면에 본문에 나오는 신하는 자신의 아들을 살리기위해 가버나움에서 예수를 만나기기위해 왔다 하나님은 우리를 위하여 기꺼이 사랑하는 아들을 주시는데 도리어 그 아들이신 예수는 신하의 아들을 살려주신다! 이 얼마나 위대한 사랑인가를 깊이 묵상하게된다.

8.인간(해석):
42절에 보면 "네 말로 인함이 아니니 이는 우리가 친히 듣고 그가 참으로 세상의 구주신줄앎이라"  고 하는것을 보면서 사마리아여인이 복음의 통로임에도 실제로 믿게되는것은 예수를 각자가 만날때 역사되는것을 깨우친다. 우리는  영혼을 예수님께 인도하는 역할인것이지 변화시키시는 주체는 오직 주님이시다. 그런까닭에 3331생명의 큐티를 많은사람들게 알려주어 각자각자 주님을  만나고 영접하기를 바란다
반면에 많은 사람들은 표적을보고 예수님을 믿음에 예수님이 걱정하심을 볼수있다. 예수님의 표적보다는 능력을 행하시는 ''예수'' 오직예수를 붙잡아야겠다.
9. 적용(나):
3331큐티에 대하여 아는 지인1명에게 소개하여야겠다
 
10. 영적터치(단어/구절)
50절: ''예수께서 하신 말씀을 믿고 가더니"

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-03-07', '요한복음', '5장 1절 ~ 10절', '제목 없음', '3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

2023년 3월16일 요한복음 5장 1절~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
유대인: 1절, 10절
예수: 1절, 6절, 8절
예루살렘: 1절, 2절
못: 2절, 4절, 7절 
병자: 3절, 5절, 7절
누워: 3절, 6절
물, 3절, 4절, 7절
낫다: 4절, 6절, 9절
안식일: 9절, 10절
자리: 9절, 10절

주제: 백성을 긍휼히 여기시는 예수님

5.하나님 찾기 (관찰)
명절에 예루살렘에 올라가시는 예수님
병자에게 낫고자 하느냐 물으시는 예수님
병자에게 일어나 네 자리를 들고 걸어가라 명하시는 예수님

6.인간 찾기 (관찰)
베데스다 못에서 물의 움직임을 기다리는 사람들
서른 여덟 해 된 병자
물이 움직일 때 들어가고 싶지만 밀어줄 사람이 없어 다른 사람이 들어간다고 말하는 병자
일어나 자리를 들고 걸어가는 병자
안식일에 자리를 들고 가는 것이 옳지 않다고 말하는 유대인

7.하나님 찾기 (해석) 
서른 여덟 해 된 병자가 누운 것과 그의 상하고 약한 심령을 보시고 긍휼히 여기시는 예수님
네가 낫고자 하느냐 묻는 질문에 자신의 억울함과 타인에 대한 원망을 늘어놓는 병자의 말을 듣고 꾸중하지 않으시고 긍휼히 여기시어 치유하시는 예수님
억울함을 해소하는 것이 아니라 본질적인 것을 해소해 주시는 예수님


8.인간(해석):
병을 치료할 방법이 없어 베데스다 못을 의지하는 사람들
네가 낫고자 하느냐 물드시는 예수님의 질문에 ‘내가 내려가고 싶은 마음은 굴뚝이나 아무도 나를 넣어 주지 않아 다른 사람이 먼저 들어간다.’ 한탄과 원망과 푸념을 늘어놓는 병자.
예수님의 말씀대로 일어나 자리를 들고 걸어가는 병자. 천사가 아니라 예수님이 치료의 근원이심을 알게 된 병자.
그동안의 한탄과 절망과 인간에 대한 불평과 원망이 변하여 세상에서 느낄 수 없는 기쁨, 환희를 느꼈을 병자.
이렇게 놀라운 순간에 안식일인데 자리를 들고 걸어가냐며 정죄하는 유대인
자기가 아는 것만 중요하고 생명을 살리는 일의 중요성은 덜 중요시하는 유대인
바벨론 포로 귀환 이후 회개하고 우리 다시 하나님의 말씀대로 살아보자 결단하고 살아오던 유대인들이 본질(사랑)은 사라지고 율법의 껍데기만 남아 외식하며 정죄하고 있다.

9. 적용(나):
나의 불평과 원망, 괴로움 등 부정적인 마음과 생각과 상관없이 나를 긍휼히 여기시며 나를 사랑하시고 일으키시는 예수님.
문제의 본질을 정확히 꿰뚫어 보시고 그 문제를 해결해 주시는 예수님.
인간의 필요와 마음의 상태를 아시고 인간의 어떤 대답과 생각에도 꾸짖지 않으시며, 인간의 가장 최선의 것을 주시는 예수님.
이런 예수님을 닮아 주위의 어려움에 처한 분들에게, 때로는 불평과 원망을 늘어놓는 분들에게 그리고 그런 상황을 만든 다른 사람들에게 필요한 것이 무엇인지 생각해 보고 필요한 것을 채워주는 사람이 되야겠다.
 
10. 영적터치(단어/구절)
네가 낫고자 하느냐 (6절) 

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-03-08', '요한복음', '5장 11절 ~ 20절', '하나님의 아들 예수', '3331 생명의 큐티

3:하나님, 인간, 나

