4.주제만들기 : 하나님의 아들 예수

5.하나님 찾기 (관찰)

-고침 받은 앉은뱅이를 찾아가신 예수님

-안식일에 일하시는 예수님

-하나님의 아들이심을 말씀하신 예수님

-하나님이심을 알려주시는 예수님

6.인간 찾기 (관찰)

-고침 받은 앉은뱅이는 유대인에게 예수님을 말함

-예수님을 박해하는 유대인

7.하나님 찾기 (해석)

- 인간의 연약함을 아시기에 미리 찾아오셔서 앉은뱅이에게 죄 짓지 않도록 말씀해주신다.

- 유대인들의 잘못된 생각과 행동을 바로잡기 위해 예수님 자신이 하나님의 아들이며 하나님임을 친히 알려주셨다.

8.인간(해석)

- 앉은뱅이는 예수님을 만난 순간 다시 걸을 수 있는 힘을 얻었고 새 삶을 얻었지만 유대인이 두려워서 일지 아니면 자신에게 일어난 기적의 감사를 잃어버려여서 일지 모르지만 유대인에게 자신을 일으켜 세운 사람이 예수님이라고 말해준다. 유대인들은 율법주의에 사로잡혀 진리가 무엇인지 말씀의 참된 의미가 무엇인지 깨닫지도 못하고 예수님을 박해한다.

9. 적용(나)

- 내게 먼저 찾아와 손을 내밀고 값 없는 은혜와 진리와 성령을 깨닫게 하시고 한 없는 축복과 은혜를 주셨음에도 예수님이 마치 내 삶에 없는 것처럼 살아가는 삶을 돌이켜본다. 앉은뱅이가 일어섰던 기적과 같은 일들이 내게 주어졌지만 예수님을 잊고 세상 풍요를 쫓아 어리석은 선택을 하였던 행동을 회개한다. 하지만 그 때에도 예수님은 내게 먼저 찾아오셔서 말씀해주셨을 것이다. 내가 분별하지 못했고 깨어있지 못했을 뿐...

- 예수님의 하나님이시며 하나님의 아들이시고 우리를 사랑하사 십자가의 죽음으로 우리를 구원해주셨다. 어린 자녀들을 사랑으로 양육하여 하나님이 주시는 사랑은 내가 너희를 사랑하는 크기보다 훨씬 크다는 것을 깨닫게 하고 싶다. 자녀를 더 사랑하고 이웃을 더 사랑하고 굶주리고 가난한 영혼들을 더 사랑하며 예수님의 손길을 기다리는 많은 영혼들을 더 사랑하는 내가 되고 싶다.

10. 영적터치(단어/구절)

- 아버지께서 아들을 사랑하사

11. 믿음과 회개 및 감사기도로 마무리

12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-03-09', '요한복음', '5장 21절 ~ 30절', '제목 없음', '3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
