1:감동받는 단어나 구절 찾기(영적터치)

2023년 3월18일 요한복음5장 21절~30절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
하나님:20절 21절 22절 23절 24절 26절 
예수님: 21절 22절 23절(3) 25절 27절 28절 30절(3)
죽은자들: 21절(2) 25절 28절 
살리심: 21절(2) 25절 29절 
심판: 22졀(2) 24절 27절 29절 30절(2)
생명: 24절 26절(2) 29절
진실로: 24절(2) 25절(2)
공경: 23절(4)
같이: 21절 23절
보내신:23절 24절
4. 주제 만들기
주제: 의로운 부활의 심판장이신 예수
5.하나님 찾기 (관찰)
죽은자들을 살리시는 성부(하나님) 성자
(예수)에게 심판권한을 위임하시는 하나님
심판권을 가지신 예수
예수를 보내시는 하나님
하나님의 뜻대로 행하시는 예수
본대로 행하시는 예수
심판을 의롭게하시는 예수
믿는자들에게 영생을 주시는 예수
6.인간 찾기 (관찰)
죽음 이후 심판대에 서는 인간들
선한일을 행한 자는 생명의 부활
악한 일을 행한자는 심판의 부활
믿는자는 영생을 얻음
7.하나님 찾기 (해석) 
한 본체 에 두 인격체를 만나다. 성부 하나님과 성자 예수님의 100% 서로 사랑하고  신뢰하는것을 볼수있다. 하나님은 가장 큰 권력인 심판권을 아들 예수에게 위임하셨다 반면 예수는 하나님뜻 아니면  아무것도 할수없다고 말씀 하신다. 예수님께서 하나님의 행하심을 본것을 따라하신다고 하셨다. 인간사회의 관점에서 보면 가장완벽한 아버지와 자녀 모습일것이다. 그러한 완벽하신  하나님 과 예수님 그리고 성령님으로 우리에게 가장 거룩한 삼위일체로 오셨다. 한개의 본질에 3개의 인격체로 되신것이다. 그 동등된 주님께서 스스로를 낮추시어 우리의 영혼구원을 위하여 십자가에서서 죽으셨다. 십자가에서 외로이 고통속에 바라보셨던 아버지 하나님! 얼마나 마음이 아프셨을까? 세상의 어떤 부모가 다른사람들의 유익을 위하여 사랑하는 자신의 자녀를 희생시킬수 있을까? 하나님은 자신보다 우리를 사랑하시는것 같다.  십자가의 고통을 참으시고 마침내 부활의 승리를 하신 우리 주님께 늘 감사드리며 함께 동행하는 삶을 살아야겠다
  
8.인간(해석):
29절에 "선한 일을 행한 자는 생명의  부활로, 악한 일을 행한 자는 심판의 부활로 나오리라" 기록되어 있다.
 선한일이란 바른 도덕적 윤리적 행위뿐만 아니라 주님을 믿는 것이다. 성부 성자님께서 서로 믿고 사랑하는것처럼 하나님의 자녀된 우리도 주님의 성품에 참여하여  그분을 신뢰하고 주님의 뜻대로 살아야겠다. 
9. 적용(나)
시간을 내어 영생을 주신 주님을 깊이 묵상해야겠다 특별히 감사기도를 드려야겠다
10. 영적터치(단어/구절)
24절: ''사망에서 생명으로 옮겼느라"

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-03-10', '요한복음', '5장 31절 ~ 47절', '제목 없음', '3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

2023년 3월19일 요한복음5장 31절~47절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
하나님:36절 37절 42절 43절 44절
예수님: 31절(2) 32(2) 34절 36절(5) 37절(2) 40절 41절 43절 44절 45절 46절(2)
증언: 31절(2) 32절(3) 34절 36절(2) 37절 39절 
영생:39절 40절 
믿음: 46절(2) 47절(2)
영광: 41절 44절(2)
4. 주제 만들기
주제: 인간들에게 구원을 원하시는 예수
5.하나님 찾기 (관찰)
참 증언자 이신 예수
구원자이신 예수
아들 예수를 보내신 하나님
6.인간 찾기 (관찰)
주님의 음성을 듣지못하는 인간
주님의 형상을 보지못하는 인간
서로 영광을 취하는 인간
믿음이 없는 인간들
7.하나님 찾기 (해석) 
본문 내용을 자세히 보면 예수님의 인간을 향하신 깊은 배려와 사랑을 볼수있다. 34절에 보면 "이 말을 하는것은 너희로 구원을 받게 하려  함이니라" 특별히 주님의 영원구원을 향하신 기다리심을 볼수있다. 하나님은 모세 침례요한  심지어 자신이고 아들이신 예수님까지 총 동원하여 인간들에게 증거와 증언을 보여주시는데도 불구하고 인간들은 관심이 없다. 하나님 편에서 보면 얼마나 통곡할 일이겠는가? 
  
8.인간(해석):
계속 영혼구원을 위하여 찾아오시는 주님의모습과 대비하여 멀리 도망치는 인간의 모습을 본다. 41절에보니 주님께서는 "사람에게서 영광을 취하지 아니하노라" 말씀하신다
당연히 사람들에게 모든영광을 받으셔야 할 메시아 주님께서 다 필요없고 나는 너의들이 구원받기를 원해! 너희가 구원받기만 한다면 어떠한 수치심도 참을수 있어! 그러한 사랑의 마음을 가지신  분이 우리 주님이시다. 반면 우리는 어떠한가
다른사람 보다 우월한 은사로 자신이 영광을 취하려 하지않는가? 어제 잠풍FC 와 축구할때  건우가 다가와서 자신이 골키퍼 를 하고싶다고 했는데 순간 양보를 안했다. 나의 즐거움을 위하여 오랜만에 나온 젊은형제에게 미덕을 못 보였다.
창피하다! 내 육적인 욕심을 버리고 다른 형제를 섬기는 주어종이 되야겠다!
9. 적용(나)
오늘중 시간을 내어 아직 친밀감이 없는 건우 포함한 축구 회원들에게 사랑의 이모티콘을 보내야겠다! 
10. 영적터치(단어/구절)
34절: 너희로 구원을받게 하려 함이니라

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-03-11', '요한복음', '6장 1절 ~ 11절', '제목 없음', '3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

2023년 3월16일 요한복음 6장 1절~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
예수: 1절, 3절, 5절, 8절, 10절
큰 무리(이 많은 사람, 오천 명): 2절, 5절, 9절, 10절
제자: 3절, 8절 
앉다: 3절, 10절

주제: 양들을 푸른 풀밭에 누이시고 쉴 만한 물가로 인도하신 예수님

5.하나님 찾기 (관찰)
디베랴의 갈릴리 바다 건너편으로 가시는 예수님
제자들과 산에 오르사 함께 앉으시는 예수님
눈을 들어 큰 무리가 자기에게로 오는 것을 보시는 예수님
우리가 어디서 떡을 사서 이 사람들을 먹이겠느냐 빌립에게 물으시는 예수님
빌립을 시험하고자 물으신 예수님
여기 한 아이가 있어 보리떡 다섯 개와 물고기 두 마리를 가지고 있나이다 그러나 그것이 이 많은 사람에게 얼마나 되겠사옵나이까 라는 정보와 질문을 동시에 받는 예수님
이 사람들로 앉게 하라 명하시는 예수님

6.인간 찾기 (관찰)
예수님을 따르는 큰 무리
예수님과 함께 산에 오르고 앉는 제자들
어디서 떡을 사서 이 사람들을 먹이겠느냐 질문을 받은 빌립
각 사람으로 조금씩 받게 할지라도 이백 데나리온의 떡이 부족할 것이라고 대답하는 빌립
떡과 물고기를 가져온 아이
여기 한 아이가 있어 보리떡 다섯 개와 물고기 두 마리를 가지고 있나이다 그러나 그것이 이 많은 사람에게 얼마나 되겠사옵나이까 라고 예수님께 묻는 안드레
예수님의 말씀대로 잔디밭에 사람들을 앉히는 제자들
예수님의 말씀대로 잔디밭에 앉은 오천 명의 사람들

7.하나님 찾기 (해석) 
몇 일을 사역하시고 걸어 이동하시고 피곤한 가운데, 자리에 앉으시고 눈을 들어 큰 무리가 자기에게로 오는 것을 보시는 예수님. 자신을 따르는 양 무리를 보시고 너무나 예쁘기도 하고 가슴이 아프기도 하셨을 예수님. 이 어여쁜 자들에게 쉼과 먹을 것을 줄 것을 계획하신 예수님.
우리가 어디서 떡을 사서 이 사람들을 먹이겠느냐 빌립에게, 그리고 우리 인류에게 공통된 질물을 던지시는 예수님. 인간이 해결할 수 없는 문제에 대해 질문을 하시며 그 답은 예수께 있음을 깨닫게 하시는 예수님. 
빌립을 시험하고자 물으신 예수님. 빌립이 인간의 해답을 내놓을 실 것을 알고 물으신 예수님. 빌립(우리 인류)이 아무리 해결하려고 발버둥을 쳐도 해결할 수 없는 일이 있으며, 그 일은 주님이 원하시면 사람을 통해 주님이 이루신다는 것을 깨닫게 하시는 예수님.  
여기 한 아이가 있어 보리떡 다섯 개와 물고기 두 마리를 가지고 있나이다 그러나 그것이 이 많은 사람에게 얼마나 되겠사옵나이까 라고 묻는 안드레의 말을 들으시고 사람들을 앉게 하라 명하시는 예수님. 보리떡 다섯 개와 물고기 두 마리, 자기의 전체 식량을 내게 바친 한 아이를 통해, 그리고 그것을 내게 비록 의문을 품으며 가져온 안드레 너를 통해 내가 이루는 역사를 보아라 말씀하시는 듯한 예수님 
예수께서 이르시되 이 사람들로 앉게 하라 하시니 ‘그 곳에 잔디가 많은지라.’
다윗을 통해 말씀하신 ‘그가 나를 푸른 풀밭에 누이시며 쉴 만한 물가로 인도하시는도다.’를 이루실 예수님. 
이스라엘은 사막화 된 광야이다. 그곳에 있는 산에 잔디가 많았다고 했다. 예수님은 긍휼히 여기시는 백성들을 푸른 풀밭에 누이셨다. 그리고 앞으로의 사역을 통해 성령님을 보내어 생수의 강물이 넘치게 흐르게 하실 것이다. 그 역사하심이 지금 우리와 함께 한다. 할렐루야!

8.인간(해석):
예수님의 능력이 너무 좋아 예수님을 따르는 큰 무리들.
그들에게 먹을 것을 주고 싶어하시는 예수님의 물음에 인간적인 최선의 답을 하는 빌립. 먹을 것이 무리 중에 아무리 많더라도 이백데나리온 즉, 오늘날 수천만원은 필요하다고 대답할 수 밖에 없는 빌립. 예수님의 신성을 알지 못했기에 할 수 있는 최선의 대답을 한 것.
떡과 물고기를 가져온 아이. 어쩌면 자기 가족이 먹을 양식의 전부를 가져온 아이. 이것을 주님께 바치고 싶어서 온 것인지 다른 이유가 있어서 인지는 알지 못하나, 주님이 아이에게 어떤 감동을 주셨을 거라 생각을 해본다. 그 감동에 순종한 아이를 통해 주님이 역사하심을 본다.
떡과 물고기를 받고 예수님께 이것으로 이 많은 무리에게 얼마나 주겠느냐 묻는 안드레. 주님 우리 손에 이것 밖에 없습니다. 제가 뭘 하겠습니까? 현재 상황과 마음의 소원의 괴리를 느끼며 괴로워하는 안드레.

9. 적용(나):
주님 우리 손에 이것 밖에 없습니다. 제가 뭘 하겠습니까? 현재 상황과 마음의 소원의 괴리를 느끼며 괴로워하는 안드레의 모습에서 나를 본다.
예수님의 온유와 겸손함을 배우고자 노력하는데, 발버둥 치는데 되지 않는 내 모습들이 떠오른다.
나를 통해 성령님의 역사하심으로 이루어진 일들이, 내가 한 일들이 되고, 주님의 영광을 취하고 있는 내 모습이 떠오른다. 가슴이 미어진다.
오늘도 나의 비참함을 느끼고 역시나 인간에게는 나에게는 예수님 밖에 없음을 깨닫고 주님만 의지하며 살아야 함을 깨닫는다. 
다른 말씀 없이 “이 사람들로 앉게 하라.” 말씀하신 예수님.
늘 교만 속에서 살아가는 나까지도 사랑하시고 그저 “온유하고 겸손하라.” 말씀하시는 예수님을 떠올려본다.
 
10. 영적터치(단어/구절)
이 사람들로 앉게 하라 (10절) 

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-03-12', '요한복음', '6장 11절 ~ 20절', '제목 없음', '3331 생명의 큐티

3:하나님, 인간, 나

3:관찰, 해석, 적용

3:반복단어찾기, 질문하기, 대상이되어봄(본문)

1:감동받는 단어나 구절 찾기(영적터치)

 

2023년 3월21일 요한복음 6장 11절~20절

1.1분기도

2.본문성경 읽기(3번)

3.반복단어 찾기(형광펜 추천)

떡(11, 13절), 제자들(12, 17, 19절), 주시다(11, 12절), 바다(16, 17절), 두려워(19, 20절)

예수(11, 12, 14, 17, 19, 20절)

4.주제만들기

표적의 다른 해석

5.하나님 찾기 (관찰)

보리떡 5개와 물고기 2마리로 많은 사람들을 먹이심

표적의 의미를 잘못이해한 사람들로부터 자리를 떠나심

바다 위를 걸어 제자들에게 나타나시며 두려워하지 말라고 말씀하심

6.인간 찾기 (관찰)

예수님의 표적으로 배를 채움

예수님의 표적으로 예수님을 임금으로 오실 선지자로 생각함

바다 위를 걸어오신 예수님을 보고 두려워함

7.하나님 찾기 (해석)

인간의 필요를 넉넉히 채우시며 자신을 들어내셨으나 이 땅에 오신 하나님의 뜻을 잘못 이해한 인간으로부터 벗어나 자신을 낮추시고자 자리를 떠나신 예수님.

남은 조각을 12바구니에 채운 것처럼 열두제자들이 예수님과 같이 표적을 행할 것을 보여주신 예수님

가버나움을 향하는 와중에 풍랑을 만나 배가 흔들리는 가운데 제자들에게 나타나 두려워하지 말라고 말씀해주시는 예수님

8.인간(해석):

예수님의 표적으로 배불리 배를 채우자 인간들을 예수님을 자신들을 구원할 이 땅에 왕 임금으로 생각하는 오해를 함.

가버나움으로 이동하는 배 안에서 풍랑을 만나서 배가 흔들렸고 그 와중에 예수님이 나타나심을 보자 두려운 마음을 가짐.

9. 적용(나):

오늘 말씀은 나에게 너무 재밌는 구절이었다. 예수님께선 왜 보리떡 5개로 먹이시고 열두 바구니에 남은 것들을 채우셨을까? 짧은 생각으론 제자들이 해야할 일에 대해 미리 말씀해주시는 것 같았다. ‘지금은 내가 표적을 행하며 많은 사람들을 배불렸지만 앞으로 너희들이 나를 대신해 많은 사람들의 영혼을 채워줄 것이다’라는 말씀처럼 느껴졌다.

예수님을 이 땅에 왕으로 생각한 인간들의 해석은 나도 당시 상황을 고려한다면 같은 생각을 했을 것 같다. 그런데 예수님은 다른 판단으로 사람들에게 알려주셨다. 세상의 왕으로 인기와 명예와 권력을 가지러 이 땅에 오신게 아니라 너희를 위해, 우리를 위해, 나를 위해 십자가에 매달릴 것을 산으로 떠나시는 행동으로 알려주셨다. 그 때라도 깨달았다면 어땠을까...지금이라도 깨달으면 어떨까? 내가 생각하고 계획하는 것과 다른 하나님의 계획을 깨닫고 살아간다면 조금이라도 하나님의 마음을, 뜻을 이해할텐데... 인간의 무지, 즉 나의 무지함이 안타깝다. 하나님의 뜻을 구하고 깨닫는 삶을 살도록 기도해야겠다.

예수님께선 가버나움으로 이동하는 배에 바다를 걸으셔서 제자들에게 나타나셨다. 그것도 풍랑이부는 극한 상황에서... 어느 누구라도 놀랄 수 밖에 없는 상황이다. 그런데 나타나셔서 두려워말라고 말씀하신다. 우리는 왜 극한의 상황에서 주님을 찾지 못할까... 만약 그 순간에 주님을 찾았더라면 그런데 주님께서 나타나셨더라면 적어도 덜 놀라면서 진짜 주님이 우리 앞에 나타나셨구나라는 믿음의 확신이 더 해졌을텐데... 아쉬운 마음이 든다. 그런데 인간은 이렇게 연약한 존재인 것 같다. 극한의 상황에서 예수님을 붙잡기가 어려운 것 같다. 그래도 예수님을 붙잡은 훈련을 의지적으로 해야겠다.

10. 영적터치(단어/구절)

남은 조각이 열두바구니에 찼더라, 두려워하지 말라

11. 믿음과 회개 및 감사기도로 마무리

12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-03-13', '요한복음', '6장 21절 ~ 30절', '제목 없음', '3331 생명의 큐티
3:하나님, 인간, 나
