1:감동받는 단어나 구절 찾기(영적터치)

2023년 3월22일 요한복음6장 21절~30절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
하나님:27절 28절  29절(2)절
예수님: 22절 23절 24절(2) 25절  26절(3) 27절(2) 29절(2) 30절
떡: 23절 26절 
양식: 27절(3)
표적: 26절 30절
하나님의 일: 28절 29절
4. 주제 만들기
주제: 영원한 양식 되신예수
5.하나님 찾기 (관찰)
대답하시는 예수
영원한 썩지않은 양식을 설명하는 예수
6.인간 찾기 (관찰)
예수를 찾는 무리들
하나님의 일에 대하여 묻는 사람들
육의양식을 기대하며 따르는 사람들
7.하나님 찾기 (해석) 
육체적 필요만을 위하여 예수를 찾는 사람들을 향하여 참된 양식을 얻기위함을 설명하시는 예수님.
예수님은 참된 양식을 얻는것 자체가 하나님의 일 이라고 말씀하신다 하나님의 일은 예수그리스도를 믿는것이라 말씀하신다. 영생의 양식을 얻는다는것은 우리의 행함이 아니라 주님안에 거하는것을 의미한다. 우리가 주님을 따르는 궁극적 목적의 우선순위 는 주님과 동행하는 삶이되는것이다.
8. 인간(해석)
26절에 보면 주님께서 예수님자신을찾는 무리들에게 말씀하신다 "너희가 나를 찾는 것은 표적을 본 까닭이 아니요 떡을 먹고 배부른  까닭이로다" 인간의 기본적 욕구를 볼수있다. 처음에는 무리들이 예수님을 찾는 이유가 수많은 병고치는 예수님의능력 즉 표적을 보기위해  따랐다. 하지만 이제는 오병이어의  표적을 통하여 배부르게 떡을 먹은체험을 하는 그들은 표적보다는 그들의 삶의 안주를  위하여 예수님을 찾는다. 본문에서 말하는 진짜 표적  또는 진정한 안주는 예수그리도를 인격적으로 만나는것이라고 일깨움을 주신다.
9. 적용(나)
하나님일(예수믿음)에 분주한 하루를 보내야겠다
10. 영적터치(단어/구절)
29절: 보내신 이를 믿는것이 하나님의 일
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-03-14', '요한복음', '6장 31절 ~ 40절', '제목 없음', '3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

2023년 3월16일 요한복음 6장 31절~40절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
예수: 32절, 35절
떡: 31절, 32절(2), 33절, 34절, 35절
하늘: 31절, 32절(2), 33절, 38절
이르시되: 32절, 35절
진실로: 32절(2)
아버지(하나님): 32절, 33절, 37절, 40절
뜻: 38절(2), 39절, 40절
나를 보내신 이: 38절, 39절


주제: 생명의 떡, 예수님

5.하나님 찾기 (관찰)
아버지께서 참 떡을 주신다고 말씀하시는 예수님
이 떡은 하늘에서 내려 생명을 주는 떡이라고 말씀하시는 예수님
자신이 생명의 떡임을 말씀하시는 예수님
그러나 사람들이 알아보지 못한다고 말씀하시는 예수님
하늘에서 내려온 것은 하나님의 뜻을 이루기 위함이며, 그 뜻은 우리에게 영생을 주는 것이라고 말씀하시는 예수님

6.인간 찾기 (관찰)
조상들이 광야에서 만나를 먹었다고 말하는 무리
생명의 떡을 우리에게 달라고 말하는 무리

7.하나님 찾기 (해석) 
자신이 생명의 떡으로 이 땅에 왔으며, 인간은 이 떡을 먹고 살아야 함을 말씀하시는 예수님. 
자신의 뜻을 이루기 위해 온 것이 아니라 하나님의 뜻을 이루기 위해 왔으며 아버지의 뜻은 예수님을 믿는 자들에게 영생을 주는 것임을 말씀하시는 예수님. 
이 시간 이후 자신의 죽음을 생각하며 이 말씀을 하시는 예수님의 마음이 어떠셨을지 생각해 본다. 
또 떡을 가져 감사 기도 하시고 떼어 그들에게 주시며 이르시되 이것은 너희를 위하여 주는 내 몸이라 너희가 이를 행하여 나를 기념하라. 
사람이 떡으로만 살 것이 아니요 하나님의 입으로부터 나오는 모든 말씀으로 살 것이니라. 
예수님은 자신이 십자가에 달려 죽은 이후 백성들이 떡으로 자신을 기념할 것과 매일 생명의 말씀을 먹기를 바라시는 마음으로 무리들에게 말씀하시지 않았을까 생각해 본다.
우리는 이런 예수님을 바라보고 믿으면 영생을 얻는다.


8.인간(해석):
자신이 생명의 떡이라는 예수님의 말씀을 듣고 그 말을 이해하지 못하는 무리.
하나님의 뜻이 예수님을 보고 믿으면 영생을 얻는 것이라는 말을 이해하지 못하는 무리.

9. 적용(나):
생명의 떡이신 예수님을 바라보고 믿으며 살아가야겠다.
자신의 뜻이 아니라 아버지의 뜻을 이루기 위해 오신 예수님처럼,
나도 내 뜻, 내 의를 위해서가 아니라 하나님의 뜻을 이루기 위해 예수님의 제자된 삶을 살아가야겠다. 이런 삶을 살기 위해 힘써 말씀을 읽고 기도해야겠다. 이 능력은 주님이 주시는 것이기 때문이다.
 
10. 영적터치(단어/구절)
내 아버지의 뜻 (40절) 

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-03-15', '요한복음', '6장 41절 ~ 50절', '제목 없음', '3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

2023년 3월25일 요한복음6장 41절~50절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
하나님:44절 45절(2) 46절(3) 
예수님: 41절(2) 42절 43절 44절(2) 45절 48절 
떡: 41절 48절 49절 50절
수군거려: 41절 43절
영생: 44절 47절 50절
배운사람: 45절(2)
본자: 46절(2)
4. 주제 만들기
주제: "생명의 떡이신 예수"
5.하나님 찾기 (관찰)
마지막날에 그의 자녀를 살리시겠다 하시는 예수
하나님께로부터 오신예수
생명의 떡이신 예수
영생을 주시는 예수
가르치시는 예수
6.인간 찾기 (관찰)
수군거리는 사람들
만나를 먹었어도 죽은 사람들
하나님을 보지못하는 사람들
7.하나님 찾기 (해석) 
 사람들이 주님을 찾고 따르는 이유는 분명하다. 그들의 배를 무료로 채우기 위함이다 예수를 그들의 임금삼아 그저 편안하게 살기를  원하는것이다  그러한 그들의 내면을 아시는 주님은 자신을 향하여 "내가 곧 생명의 떡" 이라 말씀하신다. 즉 희생을 의미하신다. 모세를 통해 얻은 일회용 떡이 아닌 영생을 주시는 예수님 자신을 의미하시는 것이다.
오늘도 영생을 주신 십자가의 사랑을 기억해야겠다!
8. 인간(해석)
하나님은 왜 모세의 무덤을 숨겨놓으셨을까? 오늘 본문을 통해 더욱 해소되었다. 40년동안 떡같은 만나를 공급받았던 이스라엘 백성들의 후손들이 그것을 혹시 그리워하는것은 아닌가? 만나를 40년 동안 주신 하나님보다 공짜로 받은 음식을 더 기다리고 있는 것은 아닐까 생각해본다. 그러한 그들에게 영생의 떡을 선포하는 주님이신데 그 진리를듣고도 수군거리는 사람들의 모습을 볼수있다. 아마 나의 모습이 아닐까 생각한다. 주님은 세상에서 비교할수없는 최고급 하우스를 나를 위하여 준비하셨는데 한강변에 고급 아파트를 보면서 잠시 부러워하는 마음을 가졌다. 더욱 영생을 주시는  주님을 바라며 영혼구혼에 힘을 써야겠다!
9. 적용(나)
목마른 지체들에게 주님관련 이모티콘을 보내고 기도해야겠다
10. 영적터치(단어/구절)
44절: 마지막 날에 다시 살리리라
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-03-16', '요한복음', '6장 51절 ~ 60절', '제목 없음', '3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

2023년 3월26일 요한복음6장 51절~60절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
하나님: 56절 57절(2) 
예수: 51절 52절 53절 54절 56절 57절 59절
인자의 살: 51절 53절 54절 56절 
인자의 피: 53절 54절 55절 56절 
떡: 51절(3) 58절(2) 
살리라: 54절 57절 58절
4. 주제 만들기
주제: 참된 주님의 살 과 피
5.하나님 찾기 (관찰)
하늘에서 내려온 참된떡을 소개하는 예수
참된 떡이 곧 주님의 살 이라고 말씀하시는 예수
주님의 살 과 피를 통하여 영생을 말씀 하시는 예수
6.인간 찾기 (관찰)
주님의 살과 피에 대한 진리의 말씀에 이해못하는 군중과 제자들
7.하나님 찾기(해석)
주님은 사람들에게 살 과 피 에대한  진리를 선포하신다. 자신의 몸과 피 를 먹고 마시라고 하신다. 얼핏 들어보면 어려운 내용 같으나 주님이 이땅에 오신 목적을 이해한다면 금방 이해될 내용이다. 해답은 6장 47절~48절에 기록되어 있다. ''진실로 진실로 너희에게 이르노니 믿는 자는 영생을 가졌나니 내가 곧 생명의 떡이니라'' 고 말씀하신다. 생명의 떡이신 예수님이 말씀하신다 그 떡이 나의 살 이다. 살을 먹으라는 말씀은 문자적 해석으로 그냥 먹는다는 것이 아니라 믿는다는 것을 의미한다 즉 주님과의 연합을 일깨워 주신다는 것이다 주님의 피에 대한 의미도 마찬가지로 연합이다. 십자가 보혈에 우리죄를 씻기고 그분안에서의 참된 연합을 의미한다  
그것을 기념하기위해 교회마다 ''성찬식'' 을 치룬다
결국 주님이 이 땅에 오신 목적은 우리죄를 용서하시고 구원하시기 위해 그분의 몸이 찢기시면서 피를  흘리시는 죽음의 희생물 로 오신것이다. 그런까닭에 오늘도 주님의 십자가 사랑에 감사하며 살아야겠다
8. 인간(해석)
오병이어의 기적을 체험한 많은 유대인들은 계속적으로 주님을 따른다 따르는 이유는 간단하다 능력의 예수를 임금삼으면 먹는것 걱정 안할수 있기때문이다 그러한 그들에게 살 과 피에 대한 진리를 선포하니 그들은 이해하지 못한다 심지어 제자들 조차도 어려워한다
주님을 따른는 사람들의 이유와 주님이 이땅에 오신 목적이 다르기때문에 충돌할수 밖에 없다.
그래서 주님은 아시고 모세를 통해 받았던 한끼 만나 와 영생의 떡 을 비유하신것이다. 나도 주님을 더 알기위해서는 성경을 통하여 주님어 비전을  꼭 붙잡아야겟다.
우리 NKFC를 우리에게 허락하신 이유는 주님의 비전인 영혼구원인것을 늘 상고해야겠다

9. 적용(나)
오늘 축구모임시 형제들에게 보다 친절하게 대하여겠다
10. 영적터치(단어/구절)
56절: 나도 그의 안에 거하나니
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-03-17', '요한복음', '6장 61절 ~ 71절', '제목 없음', '3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

2023년 3월27일 요한복음 6장 61절~71절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
예수: 61절, 64절, 67절, 70절, 71절
제자: 61절, 66절, 67절
영: 63절(2)
믿지 아니하는 자들: 64절(2)
열둘: 67절, 70절, 71절
주: 68절(2), 69절

주제: 영생의 말씀, 예수

5.하나님 찾기 (관찰)
내가 하늘로 올라가는 것을 본다면 어떻게 하겠느냐 물으시는 예수님
내가 이르는 말은 영이요 생명이라고 말씀하시는 예수님
제자 중에 믿지 아니하는 자들이 있음을 아시는 예수님
아버지께서 오게 하시지 아니하시면 누구라도 내게 올 수 없다고 말씀하셨던 것을 상기시키시는 예수님
열두 제자에게 너희도 가려느냐 물으시는 예수님
열두 제자 중 한 사람은 마귀라고 말씀하시는 예수님

6.인간 찾기 (관찰)
예수님의 말씀을 듣고 수군거리는 제자들
예수님을 떠나고 다시는 함께 다니지 아니한 많은 제자들
주여 영생의 말씀이 주께 있사오니 우리가 누구에게 가오리이까 우리가 주는 하나님의 거룩한 자이신줄 믿고 알았사옵나이다 라고 고백하는 베드로
예수님을 팔 가룟 유다

7.하나님 찾기 (해석) 
내가 하늘로 올라가는 것을 본다면 내가 하나님의 아들인 것과 내 말이 영과 생명 됨을 너희들이 믿겠느냐 물으시는 예수님.
많은 제자들이 자신을 하나님의 아들로 믿지 않음을 알고 가슴 아파하시며, 아버지께서 내게 보내지 않으면 누구도 올 수 없음을 말씀하시며 아버지의 뜻을 이루고자 이 땅에 오셨음을 상기시키시는 예수님. 
많은 제자들이 떠난 후 예수님을 믿는 열두 제자에게 너희도 가려느냐 물으시며 믿음을 견고히 다져주시는 예수님

8.인간(해석):
로마의 전복과 육신의 편안 등 육의 것이 아닌 영과 생명을 말씀하시자 떠나가는 많은 제자들
열두 제자 중 열심당원으로서 로마를 무력으로 격파할 생각으로 가득했던 가룟 유다의 실망

9. 적용(나):
늘 죄악 속에서 살며 내 마음대로 살아가던 나를 부르시고 중생케 하신 하나님께 감사를 드릴 뿐이다.
내가 원하는 것을 이루는 것과 생명이신 예수님을 따르는 것 중에서 무엇을 택할 것인가. 날마다 주어지는 선택의 순간에 나는 나의 중심성 때문에, 내가 원하는 것을 이루는 것이 좋고 편하기 때문에, 내가 원하는 것을 이루고자 생각할 것이다.
이것을 막기 위해서는 베드로의 고백처럼 영생의 말씀이 주께 있음을 정확히 알고 그 말씀에 순종해야 한다. 
그러기 위해서는 베드로가 예수님과 늘 함께하며 예수님의 말씀에 귀 기울였던 것처럼 나도 늘 성령님과 동행하며 그 능력으로 믿음의 고백과 믿음의 행동을 하며 살아야 한다. 
해민아 너도 가려느냐 묻는 주님의 말씀에 감사하며 반응해야 한다.  
큐티를 서로 나누는 것이 예수님과 동행하는 한 가지 장치가 되어 주니 감사할 따름이다.
 
10. 영적터치(단어/구절)
너희도 가려느냐(67절)

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-03-18', '요한복음', '7장 1절 ~ 10절', '하나님의 때를 순종하는 예수님', '2023년 3월28일 요한복음 7장 1절~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
- 다니심(1절), 명절(2, 8, 10절), 나타내다(4절), 때(6,8절), 올라가다(8, 10절), 세상(7절)
4.주제만들기 : 하나님의 때를 순종하는 예수님
5.하나님 찾기 (관찰)
- 예수님께서 갈릴리를 다니심
- 예수님의 때는 이르지 않았다고 하시며 유대인의 때는 늘 준비되었다고 말씀하심
- 예수님께서 세상이 악하다고 증언하사 세상이 예수님을 미워함
- 자신의 때가 아니기에 갈릴리에 머무심
- 형제들이 올라간 후에 은밀히 올라가심
6.인간 찾기 (관찰)
- 유대인들은 예수님을 죽이려함
- 예수님께 당신이 행하는 일을 제자들도 보게 여기를 떠나 유대로 가라고 함
- 예수님께 스스로 나타나기를 구하면서 묻혀서 일하는 사람이 없나니 이 일을 행하려 하거든 자신을 세상에 나타내라고 함
- 예수님의 형제들까지 예수님을 믿지 않음
7.하나님 찾기 (해석) 
- 유대인의 계획을 아시고 갈릴리를 다니시며 자신의 때를 기다리심. 초막절에 예수님께서 바로 나타나셨다면 세상 권세와 인기가 집중 되었테지만 자신의 때를 기다리셨다 초막절 중간 성전으로 올라가심. 그럼에도 인간들의 때는 늘 준비되어 있다고 말씀하심
8.인간(해석):
- 예수님을 믿지 않기 때문에 형제들은 세상에 알려지기 바라면 이 곳에 있지 말고 자신을 드러내라고 말함.
9. 적용(나): 
- 예수님의 존재가 백성들에게 알려지면서 예수님을 기대하는 사람들이 늘어나고 있지만 여전히 예수님을 믿지 않은 사람들도 존재했다. 특히 예수님의 형제들은 예수님의 표적을 보았을테지만 세상 인기를 얻고자하면 세상에 드러내라고 말하며 예수님을 비꼬았다. 같은 것을 보아도 믿지 않으려는 마음이 있다면 달리 보이는 점은 참 무서웠다. 사이비 종교와 이단과 같이 가려진 눈에 사로잡힌 사람들을 위해 기도해야겠다.
- 예수님께선 초막절 중반쯤 조용히 성전에 가신다. 하나님의 때가 아니기에 초막절이 시작될 때 집중될 이목을 피하고자 하셨다. 세상이 바라는 구원자와 하나님이 계획한 구원자가 다른데 무엇이 우리에게 유익한지 따져본다면 당연히 예수님과 같은 구원자를 고를 것이다. 그런데 당시에 유대인들은 자신만의 기준으로 자신들을 이끌어줄 왕 같은 구원자를 원했다. 누구를 위한 기준일까? 왕 같은 구원자가 오면 가장 많은 혜택을 볼 사람들은 왕의 측근  뿐이다. 모든 사람들에게 평등하게 주어지는 구원은 예수님의 십자가 사랑이 유일함을 다시 깨닫게 된다. 
- 사이비 종교와 이단에 노출될뻔한 일들이 많았음에도 진리를 알 수 있도록 상황과 환경을 지켜주신 주님께 감사드린다. 예수님의 사랑은 세상 기준과 다르다는 것을 다시 깨닫는다. 그분의 계획은 우리의 계획과 다르다는 것을 신뢰한다. 가장 좋은 것을 우리에게 주시는 주님의 사랑에 감사드린다. 
10. 영적터치(단어/구절)
자기도 올라가시되 나타내지 않고 은밀히 가시니라
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-03-19', '요한복음', '7장 11절 ~ 20절', '제목 없음', '3331 생명의 큐티
3:하나님, 인간, 나
