2023년 3월29일 요한복음7장 11절~20절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
하나님: 17절(2)
예수: 11절 12절 13절 14절 15절  16절(3) 17절 19절 20절
수군거리는: 12절(2) 20절
영광: 18절(2)
교훈: 16절 17절
4. 주제 만들기
주제: 하나님의 영광만 구하는 예수
5.하나님 찾기 (관찰)
조용히 명절중인 유대로 오신 예수
성전에서 가르치시는 예수
하나님의 영광을 설명하시는 예수 
6.인간 찾기 (관찰)
예수님을 향하여 수군거리는 사람들
예수님에 대하여 무시하는 사람들
유대인들을 두려워하는 사람들
7.하나님 찾기(해석)
명절의 중간에 예수님은 성전에서 말씀을 가르치신다 명절초 나 말 보다 중간이면 사람들이 가장 많이 붐비는 때를 선택하신것 같다 유대인드로부터 신상에 위협을 느끼시면서도 한명이라도 천국복음듣고 진리속에 살기를 원하시는 주님의 사랑과 지혜를 볼수있다. 오늘 본문내용을 보면 이단에 쉽게 빠짐을 예방할수 있는 내용을 담고있다. 15절에 보면 예수님께 유대인들이 "이 사람은 배우지 아니하였거늘 어떻게 글을  아느냐 하니" 라고 말한다. 요즘 무학인 사이비 교주들이 자주 사용하는 구절이다. 그때당시에 사람들도 충분히 예수를 사이비 교주 정도로 생각했을것이다. 거기에 대해 예수님은 명확하게 시비거는 유대인들에게 말씀하신다. 17절에보니 예수님 자신도 하나님의 뜻을 행하려 오셨다고 말씀하신다 그증표로는 하나님 영광을 구하고 그결과로 성령의 열매를 맺는것이다. 그에 따라오는것은 불의가 없다는 것이다 반면에 요즘 사이비교주들을 보면 하나님 이름을 이용하여 자신들의 영광을 드러낸다 그리고 끝은 항상 불의가 나타난다. 어런 어리석은 이단들과 달리 주님은 하나님의 영광을 위하여 움직이시다.
8. 인간(해석)
거룩하신 예수님께 유대이들은 큰 신상모덕을 서슴치 않는다. 예수님을 향하여 ''무리를 미혹한다'' 고 말한다. 심지어는 귀신들렸다고 까지 말한다 이 얼마나 큰 죄악적인 발언인가? 스스로 똑똑하다고 아브라함의 후손이라고 종교적으로우월감을 가진 유대인들은 정작  메시아를 알아보지 못한다. 모를뿐만 아니라 주님의길을 방해하는 일을 한다. 영적으로 무지하면 누구나 저지를수있는 행동이라본다. 

9. 적용(나)
깊은말씀묵상 그리고 기도 를 통하여 하나님의 뜻을 듣고 또한 행하는 참된종이 되야겠다.
오후에 Chat GPT 를 공부하여 선교에 어떻게 사용할지 고민하는 시간을 가져아겠다
10. 영적터치(단어/구절)
18절: "그 속에 불의가 없느니라"
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

