2023년 3월30일 요한복음 7장 21절~30절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
예수: 21절, 28절, 30절
너희: 21절, 22절(2), 23절, 28절(2)
모세: 22절(2), 23절
할례: 22절(3), 23절
안식일: 22절, 23절(2)
판단: 24절(2)
사람: 25절(3), 26절, 27절
그리스도: 26절, 27절

주제: 하나님이 보내신 예수

5.하나님 찾기 (관찰)
외모가 아니라 공의롭게 판단하라 말씀하시는 예수님
나는 너희가 생각하는 것처럼 사람이 아니라 하나님의 보내신 하나님의 아들이심을 말씀하시는 예수님

6.인간 찾기 (관찰)
안식일에 사람을 살리신 예수님을 정죄하는 사람들
예수님이 예루살렘에 나타났으나 잡아가지 않는 것을 보고 의문을 품는 사람들
예수님은 인간이고 어디서 왔는지 안다고 생각하는 사람들.
예수님은 그리스도가 아니라고 말하는 사람들 

7.하나님 찾기 (해석) 
구약성경에서 모세보다 큰 선지자가 나타난다고 말씀하셨고 그 큰 이가 여기 있는데 알아보지 못하는 사람들을 보며, 너희가 따르는 모세가 명한 할례는 안식일에 하면서 그보다 큰 이인 내가 사람을 살리는 것이 문제가 되느냐 물으심. 
사람이 안식일을 위해 있는 것이 아니라 안식일이 사람을 위해 있기 때문에 안식일에 사람을 살리는 일은 당연한 것이라 말씀하시는 예수님.
너희는 나를 안다고 생각하지만 너희 생각과 달리 나는 너희가 안다고 생각하는 사람이 아니라 하나님이 보내신 하나님의 아들임을 말씀하심.

8.인간(해석):
모세보다 더 큰 이가 나타났으나 알아보지 못하는 사람들.
예수님이 어디서 왔는지 알고 있다고 착각하는 사람들.
예수님의 말씀이 신성모독이라고 생각하고 예수님을 잡으려는 사람들.  

9. 적용(나):
내 생각과 하나님의 생각은 다르고, 나의 계획과 하나님의 계획은 다르며,
내 길과 하나님의 길은 차원이 다르다.
성령님을 보내주신 하나님께 감사하며, 예수님이 그리스도이심을 깨닫게 하신 성령님께 감사하며, 예수님의 사람살리는 사역에 감사하며, 나 또한 사람을 살리는 일에 더 관심을 갖아야겠다.
가정과 일터와 교회에 죽어가는 영혼은 없는 바라보고 먹이고 양육하고 전도해야겠다. 

10. 영적터치(단어/구절)
외모로 판단하지 말고 공의롭게 판단하라(24절)

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-03-21', '요한복음', '7장 31절 ~ 40절', '십자가 지실 것을 예비하시고 더 큰 목소리로 사역하시는 예수님', '[요7:31-40]
31 무리 중의 많은 사람이 예수를 믿고 말하되 그리스도께서 오실지라도 그 행하실 표적이 이 사람이 행한 것보다 더 많으랴 하니
32 예수에 대하여 무리가 수군거리는 것이 바리새인들에게 들린지라 대제사장들과 바리새인들이 그를 잡으려고 아랫사람들을 보내니
33 예수께서 이르시되 내가 너희와 함께 조금 더 있다가 나를 보내신 이에게로 돌아가겠노라
34 너희가 나를 찾아도 만나지 못할 터이요 나 있는 곳에 오지도 못하리라 하시니
35 이에 유대인들이 서로 묻되 이 사람이 어디로 가기에 우리가 그를 만나지 못하리요 헬라인 중에 흩어져 사는 자들에게로 가서 헬라인을 가르칠 터인가
36 나를 찾아도 만나지 못할 터이요 나 있는 곳에 오지도 못하리라 한 이 말이 무슨 말이냐 하니라
37 명절 끝날 곧 큰 날에 예수께서 서서 외쳐 이르시되 누구든지 목마르거든 내게로 와서 마시라
38 나를 믿는 자는 성경에 이름과 같이 그 배에서 생수의 강이 흘러나오리라 하시니
39 이는 그를 믿는 자들이 받을 성령을 가리켜 말씀하신 것이라 (예수께서 아직 영광을 받지 않으셨으므로 성령이 아직 그들에게 계시지 아니하시더라)
40 이 말씀을 들은 무리 중에서 어떤 사람은 이 사람이 참으로 그 선지자라 하며

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

2023년 3월31일 요한복음 7장 31절~40절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
-행하다(31절), 만나지 못하다(34,36절), 오지도 못하리라(34,36절), 찾다(34,36절), 헬라인(35절), 믿다(38,39절), 성령(39절), 무리(31,32,40절)
4.주제만들기 : 십자가 지실 것을 예비하시고 더 큰 목소리로 사역하시는 예수님
5.하나님 찾기 (관찰)
-찾아도 만나지 못하고 오지도 못하는 하나님께로 돌아가실 것을 말씀하신 예수님
-서서 외치시며 누구든지 목마르거든 내게로 와서 마시라고 말씀하신 예수님
-예수님을 믿으면 성경에서 말씀하신 것 같이 생수의 강이 흘러나오리라 말씀하신 예수님
-믿는 자들이 받을 성령에 대해 말씀하신 예수님
6.인간 찾기 (관찰)
-그리스도가 오실지라도 예수님이 하신 표적보다 많을까라고 말하는 무리
-이 말을 들은 바리새인, 대제사장은 예수님을 잡으려고 아랫사람을 보냄
-예수님께서 말씀하신 뜻을 모르고 헬라인에게로 간다고 생각한 무리
-성령을 모르는 무리
-참으로 선지자라 말하는 무리
7.하나님 찾기 (해석) 
-예수님께서는 십자가 지실 것을 사람들에게 말씀하셨다. 바리새인과 대제사장들이 호시탐탐 예수님을 노리고 있음에도 불구하고 오히려 서서 외치시며 사람들에게 말씀을 전하신다. 예수님은 자신의 때가 다가옴을 알고 계셨고 자신의 사명을 감당하기 위해 담대히 말씀을 전하셨다. 위협이 언제 닥칠지 모르지만 예수님의 결단과 용기가 대단하다고 느껴진다. 우리를 향한 사랑. 그 사랑이 자신의 목숨보다 더 크셨던 것 같다. 
-자신은 십자가를 지시면서 성령을 주실 것을 예비하신다. 자신을 박해하던 사람이라도 예수님을 영접하면 누구나 생수와 같은 성령을 받는다. 예수님의 사랑의 깊이와 넓이는 우리가 헤아릴 수 없다. 나의 생각과 기준으로 도저히 용서되지 않을 사람들인데 사랑으로 품으신다.
8.인간(해석): 
-여전히 예수님의 존재를 인정하지 않거나 모르고 있다. 그리스도께서 오시더라도 표적을 더하지 못한 것이라는 말들을 하며 예수님의 존재를 인정하지 않는다. 바리새인과 대제사장들은 예수님의 존재가 거슬렸을 것이다. 그러나 자신들이 나서지 않는다. 험하고 악한 일은 아랫사람을 시키면 되기 때문에 자신들은 대중의 시선에서 보호받는다. 
-예수님께서 십자가 이후 부활을 말씀하셨는데 그 뜻을 이해하지 못하고 다른 곳으로 갈거라 생각한다. 예수님께서 이 땅에 오신 목적을 모르니 당연히 십자가와 부활을 생각하지 못했을 것이다. 
9. 적용(나): 
-예수님의 사랑을 10000분의 1이라도 행할 수 있다면 얼마나 좋을까, 나는 나에게 유익하지 않은 사람들을 너무 쉽게 배척한다. 하지만 예수님께선 그런 사람들까지 사랑하라고 말씀하신다. 그리고 예수님을 전하라고 하신다. 나에게 쉽지 않는 일들이지만 예수님께서 서서 외쳐 말씀하시는 상황들을 보면 그 분의 사랑을 아는 내가 그 사랑을 전해야함은 당연하다. 
-오늘 나를 힘들게하는 한 사람(그 사람에겐 내가 그런 존재일지 모르지만...)을 떠올려 연락하고자 한다. 가식이 아닌 진심으로...
10. 영적터치(단어/구절)
“서서, 외쳐”
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-03-22', '요한복음', '7장 41절 ~ 40절', '제목 없음', '41. 어떤 사람은 그리스도라 하며 어떤 이들은 그리스도가 어찌 갈릴리에서 나오겠느냐

42. 성경에 이르기를 그리스도는 다윗의 씨로 또 다윗이 살던 마을 베들레헴에서 나오리라 하지 아니하였느냐 하며

43. 예수로 말미암아 무리 중에서 쟁론이 되니

44. 그 중에는 그를 잡고자 하는 자들도 있으나 손을 대는 자가 없었더라

45.  아랫사람들이 대제사장들과 바리새인들에게로 오니 그들이 묻되 어찌하여 잡아오지 아니하였느냐

46. 아랫사람들이 대답하되 그 사람이 말하는 것처럼 말한 사람은 이 때까지 없었나이다 하니

47. 바리새인들이 대답하되 너희도 미혹되었느냐

48. 당국자들이나 바리새인 중에 그를 믿는 자가 있느냐

49. 율법을 알지 못하는 이 무리는 저주를 받은 자로다

50. 그 중의 한 사람 곧 전에 예수께 왔던 니고데모가 그들에게 말하되

51. 우리 율법은 사람의 말을 듣고 그 행한 것을 알기 전에 심판하느냐

52. 그들이 대답하여 이르되 너도 갈릴리에서 왔느냐 찾아 보라 갈릴리에서는 선지자가 나지 못하느니라 하였더라

53.  [다 각각 집으로 돌아가고

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

2023년 4월01일 요한복음7장 41절~53절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
예수: 41절(2) 42절 43절 44절 46절(2) 48절 50절
성경: 42절 49절
갈릴리:41절 52절(2)
나지못함:41절 52절
대답하되:46절 47절 52절
잡고자: 44절 45절
4. 주제 만들기
주제: 예수를 받아들이는자와 부정하는자
5.하나님 찾기 (관찰)
베들레헴 에서 나신 예수
6.인간 찾기 (관찰)
예수님을 선지자로 여기는 사람들
예수님을 의심하는 사람들
예수를 잡으려는 사람들
예수께 손을 못대는 사람들
예수를 잡아오라고 지시하는 바리새인 
잡아오지못한 부하들에게 책망하는 바리새인 
이에 반문하는 부하들
예수에 대하여 변호하는 니고데모
7.하나님 찾기(해석)
오늘 본문 내용중에 예수님이 직접 모습을 드러내시지는 않으셨지만 예수님의 말씀의 능력을 충분히 짐작할수 있다. 예수를 잡기위해 파견된 바리새인 의 부하들이 도리어 예수를 변호하는 모습을 보인다 뿐만아니라 요한복음 3장에 등장한 바리새인 중 니고데모가 다시 등장하여 예수를 죽이려하는 동료 바리새인들에게 예수는 참된 분이시라고 변론한다 
예수님은 사람을 변하시키는 참된 능력자이시다.
8. 인간(해석)
바리새인들은 보다 낮은 사람들을 선동하여 주님의 일을  방해하는 경우가 많았다 침례요한이 한참 유명해지고 침례받는 사람들이 많을때 사람들을 보내어 알아보고 질투하였었다 마찬가지로 인기가 높아진 예수를 시기질투하여 바리새인들은 하수인들을 시켜 잡아오라고 시키지만 결과는 그들이 원하는데로 되지않았다 무엇이 문제인가? 그때당시 대부분의 바리새인들은 자신들이 하나님의 말씀을 잘알고 가르치는 우월감에 넘쳐있었다. 그러한 그들에게 침례요한이나 예수 는 그들의 영역을 침범하는 침입자 정도로 본것 같다 사실 바리새인들은 예수님의 출생지도 정확하게 모르고있고 영적으로도 진짜메시아를 인정하지 않을정도로 이기심과 무지함이 가득차있었다. 그들은 늘 영적스승으로 대접받고 사니 오실 메시아에 대하여 관심도 없고 당연히 영생에 대하여 사모함도 없는것이다 예수님을 만난 사람들의 공통점은 영혼의 목마름과 영생에 대한 관심을 가진자들이다 바리새인 중 니고데모,예수님을 잡으러갔다 변화받은 부하들 이들 모두가 영생에 관심 있었다는 것을 알수있다. 

9. 적용(나)
잠시 머므는 이땅에서 안주하지말고  복음전하는 일에 최선을 다해야겠다. 오후에 노방전도를 가야겠다!
10. 영적터치(단어/구절)
50절: 예수께 왔던 니고데모가 그들에게 말하되
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

