INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-03-24', '요한복음', '8장 1절 ~ 10절', '제목 없음', '3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

2023년 4월01일 요한복음8장 1절~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
예수:1절 4절 5절 6절(2) 9절 10절 
음행중에 잡힌 여자:3절 4절 5절 9절 10절
돌로 치라: 5절 7절 
백성들: 2절(2) 9절
서기관들과바리새인들: 3절 6절 7절 9절
고발: 6절 10절
4. 주제 만들기
주제: 음행죄를 지은 여인을 서기관과 바리새인들로부터 변호하는 예수
5.하나님 찾기 (관찰)
감람 산으로 가시는 예수
성전으로 들어오시는 예수
가르치시는 예수
여인을 보호하는 예수
6.인간 찾기 (관찰)
예수께 나아오는 백성들
예수를 시험하는 서기관들과 바리새인들
백성들 가운데 서있는 고발당한 여인
양심의 가책을 느끼는 사람들
현장에서 떠나는 사람들
7.하나님 찾기(해석)
군중안에서 조금후면 성난군중들 로 돌에맞아 죽을 위기에 놓인 간음죄로 끌려운 한 비참한 여인을  주님께서는 슬기롭게 대처하신다 우선 서기관들과 바리새인들은 가장 큰 걸림돌로 여겨지던 예수를 시험에 빠뜨리기 위해 올무를 가지고 왔다 간음한 여인을 예수가 용서해준다면 모세의 율법을 어기는 죄가 되고, 만약 돌로 치라고  하면 예수는 기존에 가르쳤던 사랑의 모습이 사라지게 되는것이다  이를 다 알고 계시는 주님은 그 올무를 지혜의 칼로 끊으셨다 "죄 없는 자가 먼저 돌로 치라" 말씀하신다 인간을 창조하신 주님께서 누구보다더 인간의 속성  죄성을 아신것이다 이말을 들은 모든 사람들이 양심에 가책을 받고 떠난다  이 얼마나 멋진 대응 방법이신가? 뿐만 아니라 그여인을 죄로 부터 풀어주신다 자비로우신 주님 사랑합니다
8. 인간(해석)
누가 진정한 죄인 인가를 생각해볼수 있는 내용이다 늘 정의롭고 의인이라 생각하는 서가관들과 바리새인들은 간음한여인의 판결을 예수께 물음으로 스스로가 진짜 존경받아야할 영적 지도자라 생각했다 그러나 예수의 핵펀치 말씀 한마디 "죄 없는자가 먼저 돌로 치라" 말씀에 순간 그들또한 죄인 임을 깨우친것이다 반면 10절에 죄가 밖으로 드러난 여인은 자신을 감싸주시는 예수께 ''주여'' 라고 외친다 주님보시기에는 어쩌면 가장큰 죄인은 교만한 죄를 지은 사람일것이다 스스로를 의인으로 포장한 죄보다 큰 죄는 없을것이다
차라리 자신이 죄인인것을 깨우치고 주께 매달리는  자세가 나아보인다
9. 적용(나)
내가 의인으로써 주님께 쓰임받는것이 아니라 죄인임에도 사용받는 피조물이라는 사실을 늘 마음에 각인하며 감사하며 살아야겠다 오늘 중으로 십자가사랑 관계되는 내용을 찾아 읽어야겠다
10. 영적터치(단어/구절)
10절: "여자여 너를 고발하던 그들이 어디 있느냐"
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-03-25', '요한복음', '8장 11절 ~ 20절', '제목 없음', '11 대답하되 주여 없나이다 예수께서 이르시되 나도 너를 정죄하지 아니하노니 가서 다시는 죄를 범하지 말라 하시니라)
12 예수께서 또 말씀하여 이르시되 나는 세상의 빛이니 나를 따르는 자는 어둠에 다니지 아니하고 생명의 빛을 얻으리라
13 바리새인들이 이르되 네가 너를 위하여 증언하니 네 증언은 참되지 아니하도다
14 예수께서 대답하여 이르시되 내가 나를 위하여 증언하여도 내 증언이 참되니 나는 내가 어디서 오며 어디로 가는 것을 알거니와 너희는 내가 어디서 오며 어디로 가는 것을 알지 못하느니라
15 너희는 육체를 따라 판단하나 나는 아무도 판단하지 아니하노라
16 만일 내가 판단하여도 내 판단이 참되니 이는 내가 혼자 있는 것이 아니요 나를 보내신 이가 나와 함께 계심이라
17 너희 율법에도 두 사람의 증언이 참되다 기록되었으니
18 내가 나를 위하여 증언하는 자가 되고 나를 보내신 아버지도 나를 위하여 증언하시느니라
19 이에 그들이 묻되 네 아버지가 어디 있느냐 예수께서 대답하시되 너희는 나를 알지 못하고 내 아버지도 알지 못하는도다 나를 알았더라면 내 아버지도 알았으리라
20 이 말씀은 성전에서 가르치실 때에 헌금함 앞에서 하셨으나 잡는 사람이 없으니 이는 그의 때가 아직 이르지 아니하였음이러라

