2023년 4월3일 요한복음 8장 11절~20절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
예수: 11절, 12절, 13절, 19절
말씀: 12절, 20절
빛: 12절(2)
증언: 12절(2), 14절(2), 17절
내가 어디서 오며 어디로 가는 것을: 14절(2)
판단: 15절(2), 16절(2)
나를 보내신:16절, 18절
나를 위하여: 18절(2)
아버지: 18절, 19절(3)

주제: 예수님을 시기하는 바리새인

5.하나님 찾기 (관찰)
나도 너를 정죄하지 아니하노니 가서 다시는 죄를 범하지 말라 말씀하시는 예수님
나는 세상의 빛이니 나를 따르는 자는 어둠에 다니지 아니하고 생명의 빛을 얻으리라 말씀하시는 예수님
나를 보내신 아버지가 참되다 증언하시니 내 증언이 참되다 말씀하시는 예수님
바리새인들은 아버지도 예수님도 모른다고 말씀하시는 예수님

6.인간 찾기 (관찰)
예수님께 사람 대접을 받고 정죄 받는 삶에서 해방된 여인
네가 증언하니 네 증언은 참되지 않다고 말하는 바리새인
네 아버지가 어디 있느냐 묻는 바리새인

7.하나님 찾기 (해석) 
간음한 여인을 사랑으로 용서하시고 사람다운 삶을 허락하신 예수님
어둠이 지배한 세상에서 자신이 생명으로 가는 빛임을 말씀하시는 예수님. 주의 말씀은 내 발의 등이요 내 길의 빛이니이다 라는 시편 기자의 고백을 떠오르게 하는 주님의 말씀. 
너희는 나를 부정하나 나를 보내신 하나님 아버지께서 나를 참되다 증언하신다고 말씀하시며 자신의 신성을 밝히 이르시는 예수님.
바리새인이 예수님의 신성을 부인하자 너희는 하나님도 나도 모른다고 말씀하시는 예수님. 

8.인간(해석):
예수님의 놀라운 기적들과 놀라운 지혜를 소문으로도 듣고, 직접 눈으로 보고 들으며 확인하여도 예수님의 신성을 거부하고 인정하지 않는 바리새인들.

9. 적용(나):
자신의 지식과 가치관과 철학, 그리고 권력을 고수하느라 진리를 거부하는 바리새인들.
내 속에도 내 죄를 모른채 하며 거부하는 모습이 있었던 것을 기억한다. 
지금도 내 속에는 내 죄성과 죄악들을 죄가 아니라고 외면하고 있는 것들이 분명히 있을 것이다.
내 죄를 하나씩 하나씩 깨닫게 하시는 성령님을 통해 나의 교만과 죄성이 깨지길 바랄뿐이다.  

10. 영적터치(단어/구절)
나를 따르는 자는 어둠에 다니지 아니하고 생명의 빛을 얻으리라(12절)

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-03-26', '요한복음', '8장 21절 ~ 30절', '제목 없음', '요8:21-30]
21 다시 이르시되 내가 가리니 너희가 나를 찾다가 너희 죄 가운데서 죽겠고 내가 가는 곳에는 너희가 오지 못하리라
22 유대인들이 이르되 그가 말하기를 내가 가는 곳에는 너희가 오지 못하리라 하니 그가 자결하려는가
23 예수께서 이르시되 너희는 아래에서 났고 나는 위에서 났으며 너희는 이 세상에 속하였고 나는 이 세상에 속하지 아니하였느니라
24 그러므로 내가 너희에게 말하기를 너희가 너희 죄 가운데서 죽으리라 하였노라 너희가 만일 내가 그인 줄 믿지 아니하면 너희 죄 가운데서 죽으리라
25 그들이 말하되 네가 누구냐 예수께서 이르시되 나는 처음부터 너희에게 말하여 온 자니라
26 내가 너희에게 대하여 말하고 판단할 것이 많으나 나를 보내신 이가 참되시매 내가 그에게 들은 그것을 세상에 말하노라 하시되
27 그들은 아버지를 가리켜 말씀하신 줄을 깨닫지 못하더라
28 이에 예수께서 이르시되 너희가 인자를 든 후에 내가 그인 줄을 알고 또 내가 스스로 아무 것도 하지 아니하고 오직 아버지께서 가르치신 대로 이런 것을 말하는 줄도 알리라
29 나를 보내신 이가 나와 함께 하시도다 나는 항상 그가 기뻐하시는 일을 행하므로 나를 혼자 두지 아니하셨느니라
30 이 말씀을 하시매 많은 사람이 믿더라

