2023년 4월4 요한복음 8장 21절~30절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
4.주제만들기
-가다(21절,22절), 죄(21,24절), 죽다(21,24절) 못하다(21,22절), 세상에 속하다(23절), 믿다(24,30절)
5.하나님 찾기 (관찰)
-예수님의 죽음과 부활을 말씀하시며 그 땐 나를 찾다가 죄 가운데서 죽을 것이라고 말씀하심
-예수님께서 가시는 곳에 오지 못할거라 말하심
-예수님께서는 위에서 났고 세상에 속하지 않으셨으나 너희는 아래에서 났으며 세상에 속하였다고 말하심
-예수님을 믿지 않는다면 죄 가운데에서 죽을거라 말씀하심
-예수님께선 처음부터 너희에게 말하여 왔고 너희에 대해 판단할 것이 많지만 하나님께서 참되시기 때문에 하나님에게 들은 것들을 세상에 말한다고 말씀하심
-예수님께서 십자가를 지신 후에야 그인 줄 알고 스스로 하는 것이 아니라 아버지께서 가르친대로 말하는 것을 알게 되리라 말씀하심
-나를 보내신 이가 함께 하시며 항상 그가 기뻐하시는 일을 행하므로 혼자 두지 아니하셨다라고 말씀하심
6.인간 찾기 (관찰)
-예수님의 말씀의 뜻을 여전히 이해하지 못하는 사람들
-말씀을 듣고도 예수님의 존재를 부정하며 다시 묻는 사람들
-예수님의 말씀을 듣고많은 사람들이 예수님을 믿음
7.하나님 찾기 (해석) 
-예수님께선 하나님의 분명한 뜻을 사람들에게 전하셨다. 
 시간이 얼마남지 않으셨는지 내가 떠나면 너희는 죄 가운데에서 죽을 수 밖에 없다고 힘주어 말씀하셨다. 즉, 예수님을 믿지 않으면 죄사함을 받을 수 없다는 분명한 메시지를 전해주신 것이다. 하나님께서 함께하신다는건 그분의 뜻을 확신있게 행할 수 있고 어떠한 환경에도 흔들리지 않으며 하나님의 뜻이 아니라면 과감히 판단하지 않는 행동을 어렵지 않게 할 수 있는 것 같다. 
- 하나님과 동행한다는 것, 그 분의 뜻을 알고 행한다는 것이 어떤 느낌일지, 얼마나 재미있을지 궁금하다. 여러 사역지에서 애쓰시는 사역자 분들이 드러나지 않는 사역을 죽을 때까지 하는 것과 드러나지 않음에도 오랜 기간 해낼 수 있는 원동력이 이 말씀에 있지 않나 생각해본다.
8.인간(해석):
- 여전히 예수님을 의심한다. 어쩌면 자신들이 원하는 대답을 듣고자 했을지도 모른다. 우리의 왕이 될거라고... 하지만 예수님의 말씀을 듣고 예수님을 믿는 많은 사람들도 생겨났다. 그들의 믿음이 참 믿음인지 궁금해진다. 
9. 적용(나): 
- 예수님과 동행하는 기쁨을 누리는 하루를 살아가고 싶다.
10. 영적터치(단어/구절)
그가 기뻐하시는 일을 행하므로 나를 혼자 두지 아니하셨느니라
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-03-27', '요한복음', '8장 31절 ~ 40절', '제목 없음', '(요한복음8장31절~40절)
31.  그러므로 예수께서 자기를 믿은 유대인들에게 이르시되 너희가 내 말에 거하면 참으로 내 제자가 되고
32. 진리를 알지니 진리가 너희를 자유롭게 하리라
33. 그들이 대답하되 우리가 아브라함의 자손이라 남의 종이 된 적이 없거늘 어찌하여 우리가 자유롭게 되리라 하느냐
34. 예수께서 대답하시되 진실로 진실로 너희에게 이르노니 죄를 범하는 자마다 죄의 종이라
35. 종은 영원히 집에 거하지 못하되 아들은 영원히 거하나니
36. 그러므로 아들이 너희를 자유롭게 하면 너희가 참으로 자유로우리라
37. 나도 너희가 아브라함의 자손인 줄 아노라 그러나 내 말이 너희 안에 있을 곳이 없으므로 나를 죽이려 하는도다
38. 나는 내 아버지에게서 본 것을 말하고 너희는 너희 아비에게서 들은 것을 행하느니라
39. 대답하여 이르되 우리 아버지는 아브라함이라 하니 예수께서 이르시되 너희가 아브라함의 자손이면 아브라함이 행한 일들을 할 것이거늘
40. 지금 하나님께 들은 진리를 너희에게 말한 사람인나를 죽이려 하는도다 아브라함은 이렇게 하지 아니하였느니라

