4. 주제 만들기
주제: 죄된 종의신분에서 참된 자유의 아들로
5.하나님 찾기 (관찰)
참 진리를 가르치는 예수
아버지로부터 본것을 말하는 예수
진정한 자유를 말씀하시는 예수
6.인간 찾기 (관찰)
아브라함의 자손이라 주장하는 유대인들
죄의 조민 사람들
예수를 죽이려 하는 사람들
7.하나님 찾기(해석)
아브라함 의 자손으로 자부심에  있는 유대인들을 향하여 참 다운 진리와 자유를 가르치신다 아브라함을 통해서 자유를 얻는것이 아니라 주님의말씀 안에 거할때 참 자유를 얻는것이다 우리가 완벽해서 의인이 되는것이 아니라 여전히 약한존재이고 죄성이 있지만 주님께 늘 회개하고 의지하며 겸손하게 살면 비로서 죄의 종이 아닌 우리를 아들로 삼아주신다
8. 인간(해석)
유대인들은 아브라함을 그들의 위대한 조상 믿음의 조상으로 삼고 살고있었다 그때당시 로마의 식민지안에서 자유를 속박당한 상태로 살고 있었지만 그들은 나름대로 누구의 종이 되어본적이 없다고 정신승리 를 가지고 살고있었다 31절에 보면 "우리가 아브라함의 자손이라 남의 종이 된 적이 없거늘" 이라고 말하고 있다. 사실 아브라함도 하나님의 하나의  피조물으로써 구원의 능력 참자유를 줄수없음을 주님은 그들에게 선포하신다. 진정한 참자유는 주님을 믿을때만 가능한것이다. 사람을 의지하는 죄의 근성에서 벗어나 주님을 의지하는 참자유인들을 하나님께서 원하신다
9. 적용(나)
나어게 좋은 영향력을 주었던 사람들은 고마음의 대상이지 참 자유까지 주지는 못한다. 진리의말씀 성경말씀을 더욱사랑하고 곁에두고 늘 묵상해야겠다 저녁시간에 깊은말씀 묵상을하므로 아들로써어 자유를 느끼는 시간을 가져야겠다
10. 영적터치(단어/구절)
32절: "진리를 알지니 진리가 너희를 자유롭게 하리라"
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-03-28', '요한복음', '8장41~50절', '제목 없음', '(요한복음 8장)
41 너희는 너희 아비가 행한 일들을 하는도다 대답하되 우리가 음란한 데서 나지 아니하였고 아버지는 한 분뿐이시니 곧 하나님이시로다
42 예수께서 이르시되 하나님이 너희 아버지였으면 너희가 나를 사랑하였으리니 이는 내가 하나님께로부터 나와서 왔음이라 나는 스스로 온 것이 아니요 아버지께서 나를 보내신 것이니라
43 어찌하여 내 말을 깨닫지 못하느냐 이는 내 말을 들을 줄 알지 못함이로다
44 너희는 너희 아비 마귀에게서 났으니 너희 아비의 욕심대로 너희도 행하고자 하느니라 그는 처음부터 살인한 자요 진리가 그 속에 없으므로 진리에 서지 못하고 거짓을 말할 때마다 제 것으로 말하나니 이는 그가 거짓말쟁이요 거짓의 아비가 되었음이라
45 내가 진리를 말하므로 너희가 나를 믿지 아니하는도다
46 너희 중에 누가 나를 죄로 책잡겠느냐 내가 진리를 말하는데도 어찌하여 나를 믿지 아니하느냐
47 하나님께 속한 자는 하나님의 말씀을 듣나니 너희가 듣지 아니함은 하나님께 속하지 아니하였음이로다
48 유대인들이 대답하여 이르되 우리가 너를 사마리아 사람이라 또는 귀신이 들렸다 하는 말이 옳지 아니하냐
49 예수께서 대답하시되 나는 귀신 들린 것이 아니라 오직 내 아버지를 공경함이거늘 너희가 나를 무시하는도다
50 나는 내 영광을 구하지 아니하나 구하고 판단하시는 이가 계시니라

