7.하나님 찾기 (해석) 
유대인에게 마귀의 생각으로 가득하기 때문에 나의 말을 알아듣지 못한다고 말씀하시는 예수님 
하나님께 속한 자는 자기의 말을 듣고 깨달았을 것임을 말씀하시는 예수님
유대인이 예수님이 누구신지, 그리고 죄를 깨닫지 못하는 원리에 대해 말씀하시는 예수님

8.인간(해석)
마음속에 마귀의 생각, 욕심이 가득하기 때문에 예수님의 말씀을 알아들을 수가 없는 유대인들

9. 적용(나):
몇 년 전 ‘네가 믿는 예수가 하나님이 맞느냐?’ 라고 물어온 마귀가 생각난다.
마귀는 늘 거짓으로 우리를 쓰러뜨려 하나님으로부터 분리시키고자 노력한다.
내 존재 자체를 뿌리까지 흔들게 한 마귀의 시험에서, 
내가 감당하지 못할 시험을 당할 그때에 피할 길을 내 주신 하나님을 찬양한다.
그러나 내 속에는 여전히 내 최대의 원수인 죄성이 있고, 마귀는 몇 년 전 큰 시험 이후에도 나를 호시탐탐 노리고 있는 것을 안다.
입체적으로 공격하는 마귀의 공격에 대적하기 위해 하나님께 복종하고 예수님의 말씀대로 사랑하며 살아가는 것을 잊지 말아야겠다.
성령님의 능력을 의지하여 말씀과 기도로 무장하고(하나님이 입혀주신 전신갑주를 입고) 한 걸음씩 한 걸음씩 주어진 길을 걸어가야겠다.

