영생을 얻는 방법은 믿음으로 주님의 말씀을 지키는 것이라 설명하신다 

8. 인간(해석)
무지한 유대인들은 진리를 선포하시는 예수를 말과 행동으로 핍박한다 특히 그들은 그들의 자부심으로 생각하는 조상 아브라함을 내세운다 아브라함의 조상이기때문에 무조건 복받는 민족으로 착각하는듯 하다 아브라함의 후손들로써 자연스럽게 하나님에 대하여 아는것처럼 여기며 사는 그들에게 주님은 도리어 하나님에 대하여 모른다고 말씀하신다 54절 하단부에 보면 "너희가 너희 하나님이라 칭하는 그이시라" 하는것을 보면 유대인들이 하나님을 진정 모름을 알수있다

9. 적용(나)
그시대에 살았으면 나 역시 유대인들 처럼 하나님을 그냥 안다고 하지 않았을까? 반면 훨씬 전에 살았던 아브라함은 한참후에 오실 예수님에 대하여 기뻐했다고 기록된것을 보면 아브라함은 역시 믿음의 조상임을 알수있다 예수님을 안다는것 또한 믿는다는것은 시대를 초월하여 온전히 하나님을 신뢰할때 인격적으로 주님은 나를 만나주신다! 아멘~~ 
믿음관련 구절을 오늘 더욱 묵상해야겠다 

