INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-04-02', '요한복음', '9장 31절 ~ 41절', '보지 못하는 자를 보게 하고 보는 자들을 맹인이 되게 하시는 심판자 예수님', '[요9:31-41]
