2023년 4월11일 요한복음 9장 31절~41절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
4.주제만들기 : 보지 못하는 자를 보게 하고 보는 자들을 맹인이 되게 하시는 심판자 예수님
5.하나님 찾기 (관찰)
 - 맹인이었던 자를 찾아가 인자를 믿는지 물어보심
 - 세상을 심판하러 오심. 
 - 못보는 사람은 보게하고 보는 사람은 못보게 하려 하심
 - 눈 먼 사람이었다면 죄가 없었을테지만 보는 사람이라 하니 죄가 그대로 남아있을 것이라고 말씀 하심
6.인간 찾기 (관찰)
 - 맹인 : 예수님께서 행하신 표적을 믿고 바리새인과 담대히 대화함. 창세 이후 누구라도 눈먼 사람의 눈을 뜨게 했다는 말을 들은적이 없다고 말함. 찾아오신 예수님께 예수님을 믿는다는 고백을 함.
 - 바리새인 : 맹인이었던 자에게 태어나서부터 죄인이었던 자가 자신들을 가르치려고 하느냐며 쫓아냄. 예수님을 만나 대화하여도 자신의 무지를 알지 못하고 예수님의 말씀에 자신들은 맹인인 것으로 착각함. 
7.하나님 찾기 (해석) 
- 맹인이었던 자의 담대한 대화를 알고 계시는 주님께선 바리새인으로부터 핍박을 받은 그를 다시 찾아가 인자를 믿느냐고 위로해주셨다. 그리고 입술의 고백이 나오도록 인자가 누구신지 친히 알려주셨다. 반면 바리새인들에겐 강하게 말씀하셨다. 심판자이신 예수님께서 보지 못하는 자에게는 보게 하시고 보는 자에게는 맹인이 되게 하려 하신다는 말씀으로 바리새인들의 교만함을 훈계해주셨다.
8.인간(해석):
- 맹인과 같이 약자도 무엇이 진리인지 분별할 수 있었다. 그것은 아주 단순했다. 창세 이후부터 맹인으로 난 자의 눈을 뜨게 한 일은 들은 적이 없다고 말하며 하나님서 보낸자라고 믿는다. 하지만 정확히 누구이며 어떤 존재인지 알지는 못한다. 예수님께서 찾아오셨을 때 예수님을 입으로 시인하고 믿음의 고백을 한다. 예수님을 영접하는 것, 지식의 크고 적음, 지위의 높고 낮음이 중요하지 않다. 진실하고 순수한 마음. 그 마음이 중요한 것 같다.
- 바리새인들은 여전히 자신들의 관점에서 상황을 바라본다. 담대히 말하는 맹인이었던 자에게 오히려 핍박하며 입막으려 한다. 메시아라면 자신들의 편에 서야한다는 오만함 때문에 예수님의 옳은 말씀과 행동들이 많이 거슬렸을 것이다. 예수님의 말씀에 자신들은 바른쪽에 속한다는 교만함 지속된다. 죄는 올바름을 판단하지 못하도록 눈을 가린다. 
9. 적용(나): 
- 맹인이었던 자를 찾아가 예수님을 알게 해주신 것처럼 예수님을 제대로 알지 못하는 자들이 많은데 나도 예수님처럼 찾아가 예수님을 전하고 싶다. 그러기 위해선 내 행동이 중요할 것 같다. 예수님을 바라보며 겸손히 나아가면 나는 점점 사라지고 예수님이 드러날 것을 믿는다. 40살 가까이 되어가는데 어찌 이렇게 더딜까... 초조하지만 예수님만 의지하며 나아가고 싶다.
- 보는 자들은 맹인이 되게 하려 함이니... 이 말이 너무 무섭지만 중요한건 예수님이 보실 땐 보는 자들이 아무도 없기 때문에 모두가 맹인이었다. 예수님의 사랑을 다시 깨닫는다. 자신을 대적하는 사람들은 이렇게까지 사랑하시다니...
10. 영적터치(단어/구절)
보지 못하는 자들은 보게하고 보는 자들은 맹인이 되게 하려 함이니
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-04-03', '요한복음', '10장 1절 ~ 10절', '제목 없음', '(요한복음 10장1절~10절)
1.  내가 진실로 진실로 너희에게 이르노니 문을 통하여 양의 우리에 들어가지 아니하고 다른 데로 넘어가는 자는 절도며 강도요
2. 문으로 들어가는 이는 양의 목자라
3. 문지기는 그를 위하여 문을 열고 양은 그의 음성을 듣나니 그가 자기 양의 이름을 각각 불러 인도하여 내느니라
4. 자기 양을 다 내놓은 후에 앞서 가면 양들이 그의 음성을 아는 고로 따라오되
5. 타인의 음성은 알지 못하는 고로 타인을 따르지 아니하고 도리어 도망하느니라
6. 예수께서 이 비유로 그들에게 말씀하셨으나 그들은 그가 하신 말씀이 무엇인지 알지 못하니라
7.  그러므로 예수께서 다시 이르시되 내가 진실로 진실로 너희에게 말하노니 나는 양의 문이라
8. 나보다 먼저 온 자는 다 절도요 강도니 양들이 듣지 아니하였느니라
9. 내가 문이니 누구든지 나로 말미암아 들어가면 구원을 받고 또는 들어가며 나오며 꼴을 얻으리라
10. 도둑이 오는 것은 도둑질하고 죽이고 멸망시키려는 것뿐이요 내가 온 것은 양으로 생명을 얻게 하고 더 풍성히 얻게 하려는 것이라

