INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-04-04', '요한복음', '10장 11절 ~ 20절', '제목 없음', '(요한복음 10장)
11 나는 선한 목자라 선한 목자는 양들을 위하여 목숨을 버리거니와
12 삯꾼은 목자가 아니요 양도 제 양이 아니라 이리가 오는 것을 보면 양을 버리고 달아나나니 이리가 양을 물어 가고 또 헤치느니라
13 달아나는 것은 그가 삯꾼인 까닭에 양을 돌보지 아니함이나
14 나는 선한 목자라 나는 내 양을 알고 양도 나를 아는 것이
15 아버지께서 나를 아시고 내가 아버지를 아는 것 같으니 나는 양을 위하여 목숨을 버리노라
16 또 이 우리에 들지 아니한 다른 양들이 내게 있어 내가 인도하여야 할 터이니 그들도 내 음성을 듣고 한 무리가 되어 한 목자에게 있으리라
17 내가 내 목숨을 버리는 것은 그것을 내가 다시 얻기 위함이니 이로 말미암아 아버지께서 나를 사랑하시느니라
18 이를 내게서 빼앗는 자가 있는 것이 아니라 내가 스스로 버리노라 나는 버릴 권세도 있고 다시 얻을 권세도 있으니 이 계명은 내 아버지에게서 받았노라 하시니라
19 이 말씀으로 말미암아 유대인 중에 다시 분쟁이 일어나니
20 그 중에 많은 사람이 말하되 그가 귀신 들려 미쳤거늘 어찌하여 그 말을 듣느냐 하며

선한목자: 11절(2), 14절
양: 11절, 12절(4), 13절, 14절(2), 15절, 16절
목숨: 11절, 15절
삯꾼: 12절, 13절 
아버지: 15절(2), 17절, 18절
목자: 12절, 16절
권세: 18절(2)
4. 주제 만들기
주제: 우리에 들지 아니한 다른 양들도 인도하기 원하시는 예수님

5.하나님 찾기 (관찰)
선한 목자이신 예수님
양들을 위해 목숨을 버리는 예수님
우리에 들지 아니한 다른 양들을 인도하시는 예수님
나는 내 양을 알고 양도 나를 아는 것이 아버지께서 나를 아시고 내가 아버지를 아는 것 같다고 말씀하시는 예수님
양들을 사랑하기에 스스로 목숨을 버리시는 예수님
버릴 권세도 있고 다시 얻을 권세도 있는 예수님. 이것을 하나님께 받았음을 말씀하시는 예수님.

6.인간 찾기 (관찰)
예수님의 말씀을 듣고 다시 분쟁하는 유대인들
예수님이 귀신들려 미쳤다고 말하는 많은 유대인들

7.하나님 찾기(해석)
선한 목자이신 예수님이 양들인 우리를 위하여 목숨을 버리실 것을 말씀해 주심.
우리에 들지 아니한 양들. 즉, 예수님을 사랑하지 않는 이들까지 구원하시고자 목숨을 버리시겠다고 하심. 우리가 아직 죄인 되었을 때에 그리스도께서 우리를 위하여 죽으심으로 하나님께서 우리에 대한 자기의 사랑을 확증하셨느니라. 
예수님을 따르지 않고 자기 뜻대로 사는 사람들을 우리에서 나간 양으로 비유하심으로 그들이 양처럼 목자가 없어서 우리 밖에서 헤매는 것이고 자신이 선한 목자이기에 그들을 긍휼히 여기고 한없이 사랑하여 자기 품으로 안겠다고 말씀하심.  
내가 죽을 것인데 이것은 인간에 의해 죽는 것이 아니라, 자기의 권세로 죽는 것이라 말씀하심. 그리고 이것은 하나님께 받은 계명이라 말씀하심으로 자기 뜻대로 하는 것이 아니라 하나님의 뜻대로 하는 것임을 말씀하심. 

8. 인간(해석)
예수님의 말씀이 무엇을 뜻하는지 알 수가 없는 유대인들.

9. 적용(나)
우리 밖에 있던 나를 우리 안으로 인도해 주신 선한 목자 예수님께 감사를 드린다. 선한 목자되시는 예수님을 바라보고 예수님의 품에서 평생 사랑을 누리며 그것을 즐기며 살아가고 싶다. 
하나님과 예수님이 서로 아는 것과 같이 예수님과 내가 서로를 알 수 있을까 생각해 본다.
내가 예수님만큼 예수님을 알고 사랑하는 것이 가능한 것인가. 예수님께 그렇게 할 수 있게 도와주시길 간구할 뿐이다.  

10. 영적터치(단어/구절)
15절: 아버지께서 나를 아시고 내가 아버지를 아는 것 같으니

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-04-05', '요한복음', '10장 21절 ~ 30절', '제목 없음', '(요한복음 10장 21절~30절)
21. 어떤 사람은 말하되 이 말은 귀신 들린 자의 말이 아니라 귀신이 맹인의 눈을 뜨게 할 수 있느냐 하더라
22.  예루살렘에 수전절이 이르니 때는 겨울이라
23. 예수께서 성전 안 솔로몬 행각에서 거니시니
24. 유대인들이 에워싸고 이르되 당신이 언제까지나 우리 마음을 의혹하게 하려 하나이까 그리스도이면 밝히 말씀하소서 하니
25. 예수께서 대답하시되 내가 너희에게 말하였으되 믿지 아니하는도다 내가 내 아버지의 이름으로 행하는 일들이 나를 증거하는 것이거늘
26. 너희가 내 양이 아니므로 믿지 아니하는도다
27. 내 양은 내 음성을 들으며 나는 그들을 알며 그들은 나를 따르느니라
28. 내가 그들에게 영생을 주노니 영원히 멸망하지 아니할 것이요 또 그들을 내 손에서 빼앗을 자가 없느니라
29. 그들을 주신 내 아버지는 만물보다 크시매 아무도 아버지 손에서 빼앗을 수 없느니라
30. 나와 아버지는 하나이니라 하신대

