2023년 4월14일 요한복음10장 21절~30절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
예수: 23절 24절(2) 25절(2) 28절 30절
하나님: 25절 29절 30절
믿지않음: 25절 26절
빼앗을 자가 없느니라: 28절 29절
4. 주제 만들기
주제: 양을 끝까지 지키시는 예수
5.하나님 찾기 (관찰)
솔로몬 행각에 거니시는 예수
대답하시는 예수
양을 이끄시는 예수
양들을 지키시는 예수
양들을 지키시는 하나님
6.인간 찾기 (관찰)
예수님께 귀신들렸다고 신성모독하는 유대인
예수님을 에워싸는 유대인들
예수를 믿지 않는 유대인들 
7.하나님 찾기(해석)
참 목자이신 예수님은 그분의 양들을 포기하지 않으시고 끝까지 지키신다. 뿐만 아니라 어떠한 사악하고 강력한 세력도 주님의 손에서 빼앗지 못한다. 얼마나 감사한 일인가? 사랑의 본체이신 주님은 최고의 힘도 지니고 계신다.
8. 인간(해석)
육의 몸을 지니신 예수를 알아보지못하고 신성모덕을 하는 유대인들을 본다. 그렇게 주님을 가까운데서 만날수있는 특권을 잡지못한체 의심하는 유대인들. 반면에 주님을 믿는 양들은 잠시 울타리 밖으로 일탈하더라도 주님께서 찾으시고 보호하시는 것을 볼수있다. 주님 가까이 있더라도 중심에 예수가 마음에 목자로 자리잡고 있지않는다면 주님을 따르는사람이 아닌것이다.
9. 적용(나)
마음의 중심으로 온전히 주님을 나의 참 목자로 더욱 섬기는 착한 양이되야겠다. 오늘 온라인 찬양예배배를통해 더욱 은혜를 사모해야겠다
10. 영적터치(단어/구절)
28절: 내 손에서 빼앗을 자가 없느니라
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-04-06', '요한복음', '10장 31절 ~ 42절', '제목 없음', '(요한복음 10장31절~42절)
31. 유대인들이 다시 돌을 들어 치려 하거늘
32. 예수께서 대답하시되 내가 아버지로 말미암아 여러 가지 선한 일로 너희에게 보였거늘 그 중에 어떤 일로 나를 돌로 치려 하느냐
33. 유대인들이 대답하되 선한 일로 말미암아 우리가 너를 돌로 치려는 것이 아니라 신성모독으로 인함이니 네가 사람이 되어 자칭 하나님이라 함이로라
34. 예수께서 이르시되 너희 율법에 기록된 바 내가 너희를 신이라 하였노라 하지 아니하였느냐
35. 성경은 폐하지 못하나니 하나님의 말씀을 받은 사람들을 신이라 하셨거든
36. 하물며 아버지께서 거룩하게 하사 세상에 보내신 자가 나는 하나님의 아들이라 하는 것으로 너희가 어찌 신성모독이라 하느냐
37. 만일 내가 내 아버지의 일을 행하지 아니하거든 나를 믿지 말려니와
38. 내가 행하거든 나를 믿지 아니할지라도 그 일은 믿으라 그러면 너희가 아버지께서 내 안에 계시고 내가 아버지 안에 있음을 깨달아 알리라 하시니
39. 그들이 다시 예수를 잡고자 하였으나 그 손에서 벗어나 나가시니라
40. 다시 요단 강 저편 요한이 처음으로 세례 베풀던 곳에 가사 거기 거하시니
41. 많은 사람이 왔다가 말하되 요한은 아무 표적도 행하지 아니하였으나 요한이 이 사람을 가리켜 말한 것은 다 참이라 하더라
42. 그리하여 거기서 많은 사람이 예수를 믿으니라

