4. 주제 만들기
주제: 핍박속에서도 복음을 증거하시는 예수
5.하나님 찾기 (관찰)
핍박하는 유대인들 에게 진리를 선포하시는 예수
핍박을 벗어나시는 예수
요단강 근처로 가신 예수
6.인간 찾기 (관찰)
예수를 돌을 들어 치려는 유대인들 
예수께 도리어 신성모독 하는 유대인들
예수를 잡고자하는 유대인들
믿지않는 유대인들 
예수를 믿는 많은 사람들

7.하나님 찾기(해석)
다시 예수님을 돌을 치려고 하는 위험속에서도 의연하게 진리를 선포하시는 예수님의 당당함의 기풍을 볼수있다. 핍박하는 그들에게도 복음의 씨가 심겨지기를 바라시는 마음이실 것이다. 한편 다시 예수님을 잡으려고 하는 유대인들을 피해 다시 다른 지역에서 사역을 하신다. 그곳에서는 많은사람들이 예수를 믿는다. 복음의 문이 한쪽이 막혀있더라도 다른 곳은 활짝 열려있음을 주님께서는 ''다시'' 를 통하여 우리에게 알려주신다. 영혼구원을 향하신 주님어 간절하고 끈질긴 사랑에 큰 감사와 찬양을 올린다.
8. 인간(해석)
똑같은 주님의 메시지를 받고도 완전 다른 결과를 볼수있다. 한그룹은 예수님의 신성에대하여 믿지못하고 예수님을 도리어 신성모독 한다. 그러면서 예수님을 향하여 신성모독 하지 말라고 경고한다. 그들에게 성경의 팩트를 제시하는 예수님을 도리어 잡으려한다
한편 다른 지역의 많은 사럄들도 처음에는 큰 의구심을 가졌지만 예수를 신뢰하는 쪽으로 마음을 연다 
9. 적용(나)
사역중에 막히는 일이 있더라도 포기하지않고 지혜를 구해 다양한 방법을 찾아 해야겠다. 오늘은 평상시하고 다른 지역에 노방던도를 해야겠다
10. 영적터치(단어/구절)
40절: "다시... 거하시니"
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-04-07', '요한복음', '11장 1절 ~ 10절', '제목 없음', '(요한복음 11장1절~10절)
1.  어떤 병자가 있으니 이는 마리아와 그 자매 마르다의 마을 베다니에 사는 나사로라
2. 이 마리아는 향유를 주께 붓고 머리털로 주의 발을 닦던 자요 병든 나사로는 그의 오라버니더라
3. 이에 그 누이들이 예수께 사람을 보내어 이르되 주여 보시옵소서 사랑하시는 자가 병들었나이다 하니
4. 예수께서 들으시고 이르시되 이 병은 죽을 병이 아니라 하나님의 영광을 위함이요 하나님의 아들이 이로 말미암아 영광을 받게 하려 함이라 하시더라
5. 예수께서 본래 마르다와 그 동생과 나사로를 사랑하시더니
6. 나사로가 병들었다 함을 들으시고 그 계시던 곳에 이틀을 더 유하시고
7. 그 후에 제자들에게 이르시되 유대로 다시 가자 하시니
8. 제자들이 말하되 랍비여 방금도 유대인들이 돌로 치려 하였는데 또 그리로 가시려 하나이까
9. 예수께서 대답하시되 낮이 열두 시간이 아니냐 사람이 낮에 다니면 이 세상의 빛을 보므로 실족하지 아니하고
10. 밤에 다니면 빛이 그 사람 안에 없는 고로 실족하느니라

