2023년 4월16일 요한복음11장 01절~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
예수:3절(2) 4절(2) 5절 9절
병든나사로: 1절 2절(2) 5절 6절
마르다와마리아:1절 3절 5절
다시가다: 7절 8절
병: 3절 4절(2) 6절
사랑:3절 5절
4. 주제 만들기
주제: 병든 나사로의 소식을 들은 예수
5.하나님 찾기 (관찰)
마르다 마리아의 오빠 나사로의 중병 고침 부탁을 받은 예수
소식을 듣고도 서두루지않고 이틀을을 더 유하시는 예수
유대로 다시 가고자 하시는 예수
6.인간 찾기 (관찰)
예수님께 사람을 보내어 오빠 나사로의 병을 치료받기를 원하는 마리아와 마르다
유대로 다시가는것에 두려워하는 제자들
7.하나님 찾기(해석)
큰병에 걸린 나사로를 향하여 죽을병이 아니라 하나님의 영광을 위함이라고 주님은 말씀하신다. 마치 9장에 등장하는 날때부터 맹인 이었던자에게 말씀하시는것 같으시다. 
그런데 이부분에서 한가지 궁금한점이 생긴다. 예수님을 진심으로 사랑했고 주님의 길을 미리 준비했던 침례요한은 억울하게  참수형을 당했다. 젊음을 더욱 펼처보지도  못하고 사역을 멈춘 침례요한은 실패한 사역자 인가? 결코 그렇지 않다.  그도 하나님의 영광을 위하여사용받은 사람이다. 반면에 설령 나사로가 살아나지 못하더라도  주님은 그분의 능력으로 충분히  하나님의 영광을 위하여 나사로를 그러한 재료로 쓰실수있는 분이시다. 그러한 주님은 서두르지 않으시고 의도적으로 그곳에서 이틀을 더 머무르셨다. 모든것이 내뜻이 아닌 주님의 뜻대로 이루어져서 참된 평강을 누린다. 그러한 평강을 누리는 사람이 비로써 하나님의 영광을 나타낼수있는 특권을 가진자이다.
8. 인간(해석)
위기때마다 예수님의 능력으로 보호받았던 예수님의 제자들임에도 유대가는것을 제자들은 두려워한다. 환경보다 크신 주님! 두려움을 쉽게 잠재우실수있는 주님을 더욱의지해야겠다.
9. 적용(나)
하나님의 영굉을 위해서 산다는것은 주님께 철저히 순복하고 의지하며 살때만이 가능하다. 세상의눈으로 흥하고나 쇄하더라도 또는 어떠한결과가 인생가운데 펼쳐지더라도 그분께 순종하는과정을 좋게보신다.  나에게 원하시는일이 무엇인지 정검하는 시간을 가져야겠다
10. 영적터치(단어/구절)
4절: 하나님의 영광을 위함이요
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

