5.하나님 찾기 (관찰)
 잠든 나사로를 깨우러 간다고 말씀하시는 예수님
 나사로가 죽었다고 밝히 말씀하시는 예수님
 제자들을 위해 기뻐하시는 예수님
 그에게로 가자고 말씀하시는 예수님
6.인간 찾기 (관찰)
 예수님께 잠들었으면 낫겠다고 말하는 제자들.
 우리도 주와 함께 죽으러 가자고 말하는 도마
 예수님을 맞이하러 나온 마르다
 집에 앉아 있는 마리아

7.하나님 찾기 (해석) 
 제자들의 믿음이 견고해질 것을 알고 기뻐하시는 예수님

8.인간(해석):
 나사로의 죽음을 걱정하는 제자들
 돌에 맞아 죽을 위험을 각오하고 주님과 함께 죽으러 가자고 외치는 도마 
 절망 가운데 예수님께 매달린 마르다와 절망 가운데 주저앉은 마리아. 성향의 차이에서 나온 행동인지 믿음의 차이에서 나온 행동인지 명확하지 않다.

9. 적용(나):
 하나님의 뜻을 잘 알지 못하고 추측하고 움직일 때가 많이 있다.
 “잠든 것이면 좋겠습니다.”라고 말하는 제자들의 모습과 같다.
 나의 성숙과 기쁨을 위하여 늘 가장 좋은 것을 준비해 주시는 예수님을 기대하며 잠잠히 지 켜보는 삶을 살아야 한다. 
 “네 입을 크게 열라 내가 채우리라.”
 
10. 영적터치(단어/구절)
15절 너희를 위하여 기뻐하노니
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-04-09', '요한복음', '11장 21절 ~ 30절', '제목 없음', '(요한복음 11장 21절~30절)
21. 마르다가 예수께 여짜오되 주께서 여기 계셨더라면 내 오라버니가 죽지 아니하였겠나이다
22. 그러나 나는 이제라도 주께서 무엇이든지 하나님께 구하시는 것을 하나님이 주실 줄을 아나이다
23. 예수께서 이르시되 네 오라비가 다시 살아나리라
24. 마르다가 이르되 마지막 날 부활 때에는 다시 살아날 줄을 내가 아나이다
25. 예수께서 이르시되 나는 부활이요 생명이니 나를 믿는 자는 죽어도 살겠고
26. 무릇 살아서 나를 믿는 자는 영원히 죽지 아니하리니 이것을 네가 믿느냐
27. 이르되 주여 그러하외다 주는 그리스도시요 세상에 오시는 하나님의 아들이신 줄 내가 믿나이다
28. 이 말을 하고 돌아가서 가만히 그 자매 마리아를 불러 말하되 선생님이 오셔서 너를 부르신다 하니
29. 마리아가 이 말을 듣고 급히 일어나 예수께 나아가매
30. 예수는 아직 마을로 들어오지 아니하시고 마르다가 맞이했던 곳에 그대로 계시더라
  
