2023년 4월17일 요한복음11장 21절~30절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
예수: 21절(2) 22절 23절 25절(3) 26절 27절 28절(2) 29절 30절
다시 살다: 23절 24절 25절(2) 
죽지 않음: 21절 26절
마르다: 21절 24절 30절
4. 주제 만들기
주제: 부활이요 생명이신 예수
5.하나님 찾기 (관찰)
오빠 나사로가 다시 살아나리라 말씀 하시는 예수
부활이요 생명이신 예수
마리아를 부르시는 예수
6.인간 찾기 (관찰)
예수님께 죽은오빠에 대하여 비통하는 마르다
주는 그리스도요 살아계신 하나님의 아들이라 고백하는 마르다
마리아를 부르는 마르다
7.하나님 찾기(해석)
이미 죽은 나사로의 동생 마르다가 주님께 큰 슬픔과 더불어 오빠를 일찍오셔서 고치지 못한것에 대한 섭섭함을 
표현할때 주님은 말씀하신다. 반드시 죽은 오빠 나사로가 살아난다고 선포하신다. 미래의 시점에서 나사로를 부활시킬뿐만 아니라 주님께서 원하시면 지금이라도 살릴수 있는 전능하신 주님이시다.
8. 인간(해석)
주님의 외침인 ''나는 부활이요 생명이다" 를 이해 못하는 마르다의 모습을 본다. 당신이 일찍 왔더라면... 내 사랑하는 오빠 나사로가 죽지 않았을텐데..  그러면서 마르다는 예수님이 그리스도요 하나님의 아들인것도 고백한다. 그런데 한가지 주님에 대하여 모르는 사실이 있다. 죽은자를 미래뿐만 아니라 지금이라도 살릴수있는 생명의 능력자이신것을 놓친것이다. 즉 마르다는 주님의 능력을 제한하고 있는모습을 볼수있다. 이 모습은 주님을 믿는다고 따르는 신도들도 고난의시간을 가질때 쉽게 발견할수있는 약한모습이다. 
9. 적용(나)
주님을 제한하지 말고 늘 간구와  기도로 주님을 의지하며 살아야겠다. 오늘 기도모임때 코로나로 고통당하고 있는 가정을 위하여 집중기도해야겠다. 바로 치료될것을 믿는다!
10. 영적터치(단어/구절)
23절: 네 오라비가 다시 살아나리라
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-04-10', '요한복음', '11장 31절 ~ 40절', '제목 없음', '(요한복음 11장31절~40절)
31. 마리아와 함께 집에 있어 위로하던 유대인들은 그가 급히 일어나 나가는 것을 보고 곡하러 무덤에 가는 줄로 생각하고 따라가더니
32. 마리아가 예수 계신 곳에 가서 뵈옵고 그 발 앞에 엎드리어 이르되 주께서 여기 계셨더라면 내 오라버니가 죽지 아니하였겠나이다 하더라
33. 예수께서 그가 우는 것과 또 함께 온 유대인들이 우는 것을 보시고 심령에 비통히 여기시고 불쌍히 여기사
34. 이르시되 그를 어디 두었느냐 이르되 주여 와서 보옵소서 하니
35. 예수께서 눈물을 흘리시더라
36. 이에 유대인들이 말하되 보라 그를 얼마나 사랑하셨는가 하며
37. 그 중 어떤 이는 말하되 맹인의 눈을 뜨게 한 이 사람이 그 사람은 죽지 않게 할 수 없었더냐 하더라
38. 이에 예수께서 다시 속으로 비통히 여기시며 무덤에 가시니 무덤이 굴이라 돌로 막았거늘
39. 예수께서 이르시되 돌을 옮겨 놓으라 하시니 그 죽은 자의 누이 
마르다가 이르되 주여 죽은 지가 나흘이 되었으매 벌써 냄새가 나나이다
40.예수께서 이르시되 내 말이 네가 믿으면 하나님의 영굉을 보리라 하지 아니하였느냐 하시니
  
