2023년 4월19일 요한복음11장 31절~40절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
예수: 32절(2) 33절 35절 39절 40절
마리아:31절 32절 33절
비통: 33절 38절
죽지 아니하였겠나이다:32절 37절
죽은나사로: 32절 34절 37절
울다: 33절(2) 35절
유대인: 31절 33절 36절 37절
4. 주제 만들기
주제: 눈물을 흘리시는 예수
5.하나님 찾기 (관찰)
우시는 예수
급하게 무덤으로 가시는 예수
믿기를 원하시는 예수 
하나님의 영광을 보여주고싶으신 예수
6.인간 찾기 (관찰)
눈물을 흘리는 마리아와 유대인들
예수님께 하소연하는 마리아
예수님께 불평하는 유대인
7.하나님 찾기(해석)
 35절에 보면 예수께서 눈물을 흘리심이 기록되어 있다 예수께서 단지 사랑하는 마리아와 유대인들의 우는모습을 보고 연민의 정때문에 우셨을까? 물론 작은 의미에서보면 그런면도 있을수 있지만 정말 우신 이유는 따로있음을 볼수있다. 본문에 보면 ''비통'' 이라는 말이 여러번 등장하는것을 볼수있다. 특별히 어떤이가 예수께  외친다. 맹인의눈을 뜨게한 사람이 나사로를 죽지못하게 할수없었더냐! 라고 불평어린 말로 말한다. 그때 예수님께서는 비통한 마음을 가지신다. 이유는 우주만물을 창조하시고 흙으로 인간을 창조하신 창조주의 능력을 제한하는 모습때문이다. 더 나아가 주님께서 십자가에서  죽으시고 부활하셨음에도 여전히 믿지않아 지옥가는 수많은 영혼들을 인지하지않으셨는지 생각해본다.
8. 인간(해석)
예수님은 아마도 죽은나사로와 관련하여 이 메시지를 듣기 원하셨을것이라 생각해본다. ''주님은 부활의 주님이실뿐만 아니라 지금 죽어있는 자도 살릴수있는 전능하신 그리스도입니다.'' 마르다와 유대인들의 주님께 불평 또는 원망하는 모습을 보면서 이 시대에 살고 있는 우리들의 모습을 본다. 어떤때는 응답받으면 주님을 찬양하다가도 기도했는데도 원하는 결과가 나오지 않으면 주님께 쉽게 불평하는 나약한 모습을 종종본다 . 
9. 적용(나)
예수님의 눈물의 의미와 비통함에 대하여 깊이 묵상해야겠다 
