4. 주제 만들기
주제: 믿게 하기 위해 죽은 자를 살리신 예수님
5.하나님 찾기 (관찰)
하나님께 감사하시는 예수님
큰 소리로 나사로를 부르 예수님
에브라임에 머무르시는 예수님

6.인간 찾기 (관찰)
예수께서 하신 일을 본 많은 유대인
바리새인들에게 가서 예수께서 하신 일을 알린 유대인
백성들이 모두 예수를 따를까봐 걱정하는 대제사장들과 바리새인들
예수께서 그 민족을 위하시고 또 그 민족만 위할 뿐 아니라 흩어진 하나님의 자녀를 모아 하나가 되게 하기 위하여 죽으실 것을 미리 말하는 가야바
명절에 예루살렘으로 올라오는 유대인들
명절에 예수님이 성전에 오실지 이야기하는 유대인들

7.하나님 찾기(해석)
나사로를 부시기 전에 하나님께 기도하는 모습을 보여주시며, 인간의 능력이 아니라 하나님의 능력으로 나사로를 살리심을, 자신이 하나님이 보내셔서 이 땅에 오셨음을 보여주시는 예수님. 자기 뜻대로 사는 것이 아니라 하나님의 뜻대로 살고 있음을 보여 주심.

8. 인간(해석)
죽은지 나흘된 자가 살아나는 놀라운 역사가 일어난 후 예수님을 믿는 많은 유대인들
죽은지 나흘된 자가 살아나는 놀라운 역사가 일어난 후 바리새인들에게 가서 보고하는 유대인들
죽은지 나흘된 자가 살아나는 놀라운 역사가 일어났음에도 예수님에게 백성을 빼앗길까봐 걱정하는 대제장들과 바리새인들.
대상이 하나님의 아들임에도 그들을 의심하고 시기하고 대적하는 자들이 있다. 대상이 사람이라면 의심하고 시기하고 대적하는 일이 더 많을 것이다. 

9. 적용(나)
나보다 인기가 많거나 높임 받는 사람을 보면 시기심이 일어날 때가 있다. 조심해야 한다. 나의 본성은 의심과 시기와 대적하는 일에 익숙하다.
나의 행동이 이웃을 그리고 예수님을 대적하는 일이 될 수 있음을 기억하고 행동해야 한다.

10. 영적터치(단어/구절)
42절 아버지께서 나를 보내신 것을 그들로 믿게 하려 함이니이다

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-04-12', '요한복음', '12장 1절 ~ 10절', '제목 없음', '(요한복음 12장1절~10절)
