8. 인간(해석)
값비싼 향유를 아낌없이 주님께 붓는 마리아의 모습을 통하여 그녀가 얼마나 예수님을 존경하고 사랑했는지 볼수있다. 마리아는 진심으로 주님의 종이라 볼수있다. 반면에 자칭 예수님의 제자라하는 가롯유다는 가난한자를 위하는척하지만 물질의 종으로 마귀한테 잡혀있는것을 볼수있다. 주님 곁에서 수많은 기적을 보고도 예수님을 배신하 고 파는 그의 모습을보면 욕심이크면 진리를 볼수없음을 깨우친다. 또 한명의 종이 등장한다. 명예의 종이다. 겉으로는 유대인들에게 최고의 종교지도자요 예배를 이끄는 대제사장이지만 자신의 기득권욕심에 가려져 예수를 죽이려고한다. 
