찾아온 헬라인들을 예수께 소개해주는 빌립과 안드레
7.하나님 찾기(해석)
예수를 찾는 이방민족인 헬라인 등장은 매우 고무적이다. 그들의 출현에 맞추어 예수님은 ''영광을 얻을 때'' 때라고 말씀하신다. 어쩌면 세계복음화를 준비하고자 하시는 하나님의 계획이 아닌가 본다. 28절에 보면 영광 이라는 단어가 반복적으로 나온다. 그 영광은 예수님께서 이미 받으신것이고 앞으로도 있을 것이다. 27절에 보면 예수님께서 그영광을 사람들에게 보여주시기 위해 오셨지만 하나님과의 일시적 헤어짐에 괴로움을 느끼고계신다. 그 고통을 알고도 오신 예수는 결국 우리를 구원 하시기위해 오신것이다. 결국 그분의 영광의 의미는 우리를 향한 숭고한 사랑이고 희생인 것이다 
8. 인간(해석)
없음
9. 적용(나)
나도 주님처럼  다른 영혼을 섬기는 사람이 되야겠다. 오늘중으로 소외돤 영혼 있나 정검하고 있다면 안부 문자를 보내야겠다
