INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-04-16', '요한복음', '12장 41절 ~ 50절', '빛으로 오셔서 어둠 가운에 소망이 되신 예수님', '[요12:41-50]
