5.하나님 찾기 (관찰)
 - 나를 믿는 자는 나를 믿는 것이 아니요 나를 보내신 이를 믿는 것이며
 - 빛으로 세상에 왔나니 무릇 나를 믿는 자로 어둠에 거하지 않게 하려 함이라 말씀하시는 예수님
 - 사람이 내 말을 듣고 지키지 아니할지라도 내가 그를 심판하지 아니하며 자신이 온 것은 심판하려 함이 아니라 세상을 구원하려 함이라 말씀하신 예수님
 - 나를 저버리고 내 말을 받지 아니하는 자를 심판할 이가 있으니 내가 한 그 말이 마지막 날에 그를 심판하리라 말씀하신 예쑤님
 - 내 자의로 말한 것이 아니라 나를 보내신 아버지께서 내가 말할 것과 이를 것을 명령하셨다고 말씀 하신 예수님
- 그의 명령이 영생인 것을 알고 내가 이르는 것은 아버지께서 말씀하신 그대로라 말씀하신 예수님
6.인간 찾기 (관찰)
 - 관리 중에도 이사야가 한 말을 믿는 자들이 많으나 바리새인들 때문에 드러나게 말하지 못하고 출교를 두려워 함. 그들은 사람의 영광을 하나님의 영광보다 더 사랑함.
7.하나님 찾기 (해석) 
- 자신이 하나님임을 말씀해주시는 예수님. 예수님께서 외쳐 말씀하셨다고 기록되어 있다. 빛으로 세상에 오셔서 어둠 가운데 거하는 우리를 구원하시고자 이 땅에 오신 것이다. 예수님께선 자신의 할 일을 정확히 수행해나가신다. 타락해 있는 인간을 당장 심판하실 수 있지만 심판은 자신의 일이 아니라고 말씀하신다. 오직 하나님의 영광만 드러나게 하시려 하나님의 말씀을 순종하신다. 
8.인간(해석):
- 깨우침이 있고 알고 있더라도 행동하는 것이 얼마나 중요한지 깨닫는다. 말씀을 통해 이사야가 어떤 말을 했고 그 의미까지 알고 있지만 바리새인이 두려워 사람의 영광을 사랑한 이들을 나 또한 어떻게 정죄할 수 있을까? 기독교를 욕하고 기독교를 배척하는 사람들의 이야기를 듣고 반박하거나 위로하지 못하는 내 모습이 그들의 모습 속에 보인다. 
9. 적용(나): 
- 지상 최대 명령이자 사명인. 예수님을 전하는 것. 쉬우면서도 어려운 이 사역을 감당케 하신 하나님께 감사하다. 이 땅에 태어나 아무런 소망 없이 살아가는 것이 얼마나 가슴 아픈 일일까? 감사하고 감사해야겠다. 빛으로 오신 예수님을 전해야하는데 고려해야 할 것들이 너무 많아 가슴이 아프다. 그래도 기회가 된다면 예수님을 담대히 전할 수 있도록 영성이 단단해져야겠다. 
