2023년 4월26일 요한복음13장 01절~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
예수:1절 2절 3절(3) 6절(2) 7절(2) 8절(2) 9절 10절
하나님: 1절 3절(3)
베드로: 6절(2) 7절 9절
씻음: 5절 6절 8절(2) 9절 10절
수건: 4절 5절
사랑: 1절(2)
4. 주제 만들기
주제: 제자들의 발을 씻겨주시는 예수
5.하나님 찾기 (관찰)
아버지께 돌아가실때를 아시는 예수
자기 사람을 끝까지 사랑하시는 예수
제자들의 발을 씻겨주시는 예수
제자들중 가롯유다 가 배신할것을
예견하시는 예수
6.인간 찾기 (관찰)
마귀에게 넘어가 예수를 팔려고 생각하는 가롯유다 
예수께 발을 씻는것을 막는 베드로
예수께 다른부분도 씻어달라고 하는 베드로
7.하나님 찾기(해석)
 예수님은 제자들을 사랑하시되 끝까지 사랑하셨다. 예수님은 아버지께로 가실것을 아시고 제자들의 발을 물로 씻겨주신다. 본래 아랫 사람이 주인의 발을 씻겨주는것이 당연한 일 이었는데 도리어 주님은 손수 섬김의 모습을 우리에게 보여주셨다. 예수님은 하나님의 아들이요 그리스도이신 최고의 권위자이신데 그 귄력을 내려놓고 마치 종의 자세로 제자들을 섬기는 모습을 볼수있다. 영혼을 얼마나 사랑하시는지 볼수있다. 진정한 섬김은 진실된 사랑의 표현일것이다.
8. 인간(해석)
예수님은 자기 사람을 사랑하시되 끝까지 사랑하시는 사랑의 주님이시다. 반면 가롯유다 는 자신을 사랑하시는 주님을 배반하고 자신의 생각을 마귀에게 넘겨준다. 언제부터 가롯유다 는 마귀와 친해졌고 타협하는 사람이 되었을까? 처음부터 갑자기 배신자가 되지 않았을것이다.  조금씩 조금씩 세상과 타협하다 돌이킬수없는 지경까지 왔을것이다.  마귀에게 틈을 보이지말고 자신을 끝까지 사랑하시는 주님을 붙잡고 사는것이 지혜로운 사람이다.
9. 적용(나)
 주님이 자신의 양들을 죽기까지 끝까지 사랑하셨듯이 나도 그러한 섬기는 사람이 되야겠다. 오늘도 그러한 마음으로 노방전도를 가야겠다.
10. 영적터치(단어/구절)
1절: 세상에 있는 자기 사람들을 사랑하시되 끝까지 사랑하시니라
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

