2023년 4월28일 요한복음 13장 21절~30절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
4.주제만들기 : 괴로운 심령으로 증언하시는 예수님
5.하나님 찾기 (관찰)
- 증언하시는 것을 괴로하시는 예수님
- 제자 중 한명이 자신을 팔거라 말씀하시는 예수님
- 떡 한 조각을 적셔주는 자가 자신을 팔거라 말씀하시는 예수님
- 떡 조각을 유다에게 주시는 예수님
6.인간 찾기 (관찰)
- 예수님의 품에 의지하여 눕는 제자 
- 질투하는 시몬 베드로
- 본질에 집중하지 못하는 제자들
- 떡 한 조각을 받은 유다, 사탄이 유다에게 들어감
- 예수님의 말씀을 이해하지 못하는 제자들
7.하나님 찾기 (해석) 
- 예수님께서는 제자들에게 자신을 팔자를 괴로운 심정으로 증언하셨다. 괴로운 심정은 여러 가지를 생각할 수 있는데 첫 번째는 제자 중에 예수님을 파는자가 있기 때문에 괴로웠을 것이고 두 번째는 예수님을 팔게 된 유다가 사탄이 들어갈 틈을 주게 된 것과 그 후에 유다가 감당해야하는 일들을 아시기 때문에 괴로우셨을 것이다. 예수님께서는 이미 아버지의 명령에 순종하셨기 때문에 십자가를 짊어질 것을 아셨다. 그렇기 때문에 예수님의 괴로운 심정이 두 번째 이유일 것 같다는 생각을 해본다. 우리를 죽기까지 사랑하셨기에 자신을 파는 제자까지 사랑하시는 주님의 심정을 생각하니 더 가슴이 저미어 온다.  
8.인간(해석):
- 사탄이 들어갈 틈을 준다는 것 참으로 위험하다는 것을 깨닫는다. 예수님을 판 유다 뿐만아니라 예수님과 함께한 모든 제자들에게 사탄이 들어가 있었다. 예수님의 괴로운 심정을 파악하지 못하고 예수님의 품을 의지해 눕는 제자. 이를 시기하고 질투하는 베드로, 유다에게 전달된 떡의 의미를 깨닫지 못하는 제자들. 모두 사탄에게 틈을 주었기 때문에 본질을 바라보지 못하는 어리석은 행동과 생각을 하게 됐다. 
- 반면 유다는 사회생활을 잘한 것 같다. 적셔진 떡을 받았음에도 제자들 중 어느 누구도 유다를 의심하지 않는다. 마치 신앙생활을 잘하고 선망받는 신도나 사역자 중에 이단에 빠져있는 사례를 보는 것처럼 섬뜩함이 느껴진다. 
9. 적용(나): 
- 매일 주님과 동행하며 살아야되는 이유에 대해 다시 깨닫는다. 우리는 언제든 넘어질 수 있는 연약한 존재이기에 하나님을 바라보며 살아야지만 의의 길에 겨우 들어갈 수 있다. 그런데 조금만 신앙생활을 열심히 하면 마치 의로운 사람인 마냥 행동하고 생각하는 교만함이 내 안에 가득 자리 잡고 있다. 오늘도 의지적으로 예수님을 바라보는 훈련을 해야겠다. 그리고 그 괴로운 심정을 조금이나마 느껴보고자 묵상하는 시간을 갖고자 한다.
10. 영적터치(단어/구절)
- 심령이 괴로워 증언하여
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

