목숨걸고 예수를 따를것을 고백하는 베드로, 하지만 부인할것을 들은 베드로.
7.하나님 찾기(해석)
 예수님은 자신의 죽으실 때가 다가왔음을 아시고 ''영광''을 받으셨다고 말씀 하신다. 일반 사람이 이성적인 눈으로 보면 이해할수없는 부분이다. 하지만 주님의 구속사적인 시각으로 보면 주님이 죽으심으로 인류를 구원할 가장큰 하나님이 인간구원에 대한 사랑의 증표이다. 이제는 제사장인 아닌 인간 각자가 마음껏 하나님께 나아가  영광을 올릴 통로가 생긴것이다. 그러면서 주님은 사람들에게 서로 사랑할것을 말씀하신다. 
8. 인간(해석)
베드로는 훗날에 예수님을 세번이나 부인할것이라는 예언을 주님께 미리 듣는다. 베드로는 예수님을 나름 사랑하고 따르고 싶어했지만 훗날에 그의 약한존재임이 들어난다. 그럼에도 주님께서는 그가 후에 제자로써  따라올것을 36절에  기록되어  있다. 인간의 신앙고백이나 열정보다는 우리를 품고 참아주시고 때에 맞추어 인도하시는 주님을 본다. 
9. 적용(나)
 주님의 제자로써 더욱 다른이들을 사랑하는 사람이 되야겠다. 오늘은 우리 NKFC 야외행사가 있는 날 이다. 주님의 사랑을 잘 실천해야겠다.
10. 영적터치(단어/구절)
35절: 너희가 내 제자인 줄 알리라
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-04-21', '요한복음', '14장 1절 ~ 11절', '제목 없음', '(요한복음 14장1절~10절)
1.  너희는 마음에 근심하지 말라 하나님을 믿으니 또 나를 믿으라
2. 내 아버지 집에 거할 곳이 많도다 그렇지 않으면 너희에게 일렀으리라 내가 너희를 위하여 거처를 예비하러 가노니
3. 가서 너희를 위하여 거처를 예비하면 내가 다시 와서 너희를 내게로 영접하여 나 있는 곳에 너희도 있게 하리라
4. 내가 어디로 가는지 그 길을 너희가 아느니라
5. 도마가 이르되 주여 주께서 어디로 가시는지 우리가 알지 못하거늘 그 길을 어찌 알겠사옵나이까
6. 예수께서 이르시되 내가 곧 길이요 진리요 생명이니 나로 말미암지 않고는 아버지께로 올 자가 없느니라
7. 너희가 나를 알았더라면 내 아버지도 알았으리로다 이제부터는 너희가 그를 알았고 또 보았느니라
8. 빌립이 이르되 주여 아버지를 우리에게 보여 주옵소서 그리하면 족하겠나이다
9. 예수께서 이르시되 빌립아 내가 이렇게 오래 너희와 함께 있으되 네가 나를 알지 못하느냐 나를 본 자는 아버지를 보았거늘 어찌하여 아버지를 보이라 하느냐
10. 내가 아버지 안에 거하고 아버지는 내 안에 계신 것을 네가 믿지 아니하느냐 내가 너희에게 이르는 말은 스스로 하는 것이 아니라 아버지께서 내 안에 계셔서 그의 일을 하시는 것이라
  
