보다: 7절 8절 9절
안에: 10절(2)
예비: 2절 3절
4. 주제 만들기
주제: 길이요 진리요 생명이신 예수
5.하나님 찾기 (관찰)
우리의 거처를 준비하시는 예수
근심하지 말라 하시는 예수
길이요 진리요 생명되신 예수
