6.인간 찾기 (관찰)
주의 길을 모른는 도마
하나님 아버지 보기를 구하는 빌립
근심하는 제자들
7.하나님 찾기(해석)
 도마의 순박한 질문에 예수님은 복음의 핵심적 진리를 아낌없이 선포하신다. "내가 곧 진리요 생명이니 나로 말미암지 않고는 아버지께로 올자가 없느니라: 우리의 작은 질문에도  크게 반응하시는 주님께 늘 감사 드립니다. 주님이 우리의 길이고 생명이시며 진리되심에 오늘도 안심하며 기쁨으로 살아갑니다. 우리가 살아가는 길이 때때로좁고 험난해 보일찌라도 주님이 나를 결국 복되게 하시려고 설계한 길 이라는 것을 알기에 주님만 의지하고 믿음으로 나아갑니다. 그 길의 종착지는 결국 생명이며 영광입니다.  그 진리의 영광을 준비하신 분은 바로 하나님 아버지 입니다. 그 하나님이 우리를 구원하신 구주 예수님이십니다.
8. 인간(해석)
2절에 보면 거할 곳이 많도다 고 기록되어 있다. 요즘 부동산 문제로 홍역을 치루는 많은사람들에게 크게 위로되는 내용이다. 많은 사람들이 마음 편하게 눕고 쉴수있는 자기집을 마련하기 위하여 얼마나 큰 노고를 하며 살아가는가? 자기집을 힘들게 마련하였다 하더라도 수십년 지나면 노후화  되기 십상일것이다.  즉 세상의 집은 아무리 잘 지었다고 하더라도 시간의 유한성을 갖는다. 다시 새집을 장만하려해도 치솟는 물가에 대출없이 사는것은 극소수 말고는 쉽지 않을것이다. 반면 주님은 우리에게 영혼히 무상으로 살수있는 최고의 집을 예비하셨다고 하니 얼마나 감사한 일인가? 때가 되면 모래성처렁  무너져 내리는 세상의 집을 위해서 살지말고 영원한천국에 쌓아둘 선한일을 하며 사는것이 지혜로운 사람이라 믿어진다
9. 적용(나)
 생명되시고 진리이신 예수님의 길을 잘 따라야겠다 최근 보여주신 예수님의 비전을 깊게 묵상하는 시간을 가져야겠다
10. 영적터치(단어/구절)
2절: 내 아버지 집에 거할 곳이 많도다
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

