예수님을 사랑하면 서로 사랑하라는 예수님의 계명을 지킬 수 있다고 말씀하시는 예수님. 
성령님을 통해 우리를 고아와 같이 버려두지 않으시고 우리와 영원히 함께 하실 것을, 그리고 성령님을 통해 예수님이 하나님 안에, 예수님이 우리 안에, 우리 안에 예수님이 계실 것을 말씀하시는 예수님. 예수님은 우리와 함께 영원히 거하는 것을 위해 일하신다.
 
