6.인간 찾기 (관찰)
주님안에 거하면 열매를 맺음
주님안에 거하지 않으면 버려지고 아무것도 할수 없는 인생이 됨
7.하나님 찾기(해석)
 주님은 우리에게 원하는것을 다 응답하여 주신다고 하신다.  단 조건이 있다.  주님 안에 거하실 떄라고  말씀하신다. 즉 주님은 하나님의 뜻을 우리를 통하여 이루시기를 원하신다. 주님안에  온전히 거할수록  응답의 열매는 풍성해질것이다.  주님께서는 우리가 더욱 실력있는 자녀로 성장하시는 것을 원하신다.  그리고 보다더 주님과 교제하며 살기를 바라신다.  그것을 깨우친 자녀들은 내가 무엇을 할까를 고민 하기보다는 어떻게 주님안에 거할것을 애쓰는 자들이다.
8. 인간(해석)
참포도 나무이신 예수님 안에 거하면 풍성한 삶을 살수있다. 가지된 우리는 열매를 맺기 위해서는 포도나무에 잘 접촉되어 있어야한다. 그 접촉점에 오염물질이 있으면 닦아내야한다. 항상 청결을 유지하여야한다. 가지 혼자 원한다고 열매가 저절로 만들어지지 않는다. 즉 가지는 주체가 될수없다는 것이다. 거룩하신 주님처럼 깨끗한 마음을 가질때 비로써 그분과 쉽게 동행 할수있고 기쁨의열매를 맺는삶을 살아갈수 있게된다. 그러므로 가지인 우리가 먼저 해야 할일은 주님안에 내가 거해 있는지를 수시로 정검해야한다.
9. 적용(나)
 주님안에 있을때만이 참다운 성령의 열매를 맺는것이다. 그러므로 내가 지금 온전히 주님의 몸통에 잘 붙어있는지 기도하며 오늘 점검해야겠다. 
10. 영적터치(단어/구절)
5절: 나를  떠나서는 너희가 아무 것도 할수 없음이라
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

