7.하나님 찾기(해석)
삼위일체 하나님께서 포기하지 않으시고 인간들에게 진리를 증언하시기를 원하신다. 보내시는 하나님, 보냄을 받으시고 죽기까지 순종하는 예수님, 그리고 오시는 보혜사 성령님, 그 성령님도  증언을 하신다. 뿐만아니라 주님은 자녀들에게도 증거할수 있는 특권을 주셨다.
8. 인간(해석)
증언자가 된다는 것은 주님의 큰 대업에 참여하는것을 의미한다. 삼위일체 하나님께서 총동원 하셔서 최초의 증언의 모본이 되셨는데, 이 일을  이제는 우리에게 주셨다. 주님의 자녀라면 누구나 마음중심에 성령님이 내제하고 계신다. 이제는 예수를 전하지 않고 사는 삶은 결코 바람직하지 않는 삶이라 확신한다.  늘 성령님과 동행하며 주님을 전하는 삶이야말로 주님의 자녀로서의 가장 기본적 모습일것이다.
9. 적용(나)
 주님의 사랑을 잘 전달하는 복음의  증언자 가 되야겠다.
노방전도를 해야겠다.
10. 영적터치(단어/구절)
