4. 주제 만들기
주제: 떠날것을 제자들에게 말씀하시는 예수
5.하나님 찾기 (관찰)
실족하지 않기를 원하시는 예수
기억나게 하시려는 예수
유익을 주시려는 예수
떠날 갈것을 예고 하고시는 예수
6.인간 찾기 (관찰)
제자들을 핍박하는 일이 하나님을 사랑하는 일이라 착각하는 사람들
하나님을 알지 못하는 사람들 
7.하나님 찾기(해석)
예수님은 죽음이 임박했다는 것을 아시고 제자들을 안심시키시고 계신다. 7절에 보면 ''내가 떠나가는 것이 너희에게 유익이라'' 말씀하신다. 자신이 떠나도 보혜사 성령이 온다는 것이다. 삼위일체 하나님이 그분의 자녀들을 끝까지 챙겨주시는 따뜻함을 볼수있다. 위로의 성령님이 모든 믿는자들과 함께하시며 가르쳐주신다고 하시니 큰 위로가 된다.
8. 인간(해석)
2절에 보면 예수님을 따르는 제자들을 죽이고 출교하는 사람들 이야기가 기록되어 있다. 주님은 그러한 사람들도 나름대로 그일이 "하나님을 섬기는 일"이라고 여긴다고 한다. 얼마나 잘못된 생각인가?
마치 사도바울이 예수님을 만나기전에 예수믿는 자들을 핍박했던 모습과 똑같다. 그때당시 사울청년은 나름대로 하나님을 사랑하는 마음으로 했다고 한다. 하나님 편에서 보면 얼마나 황당한 일이겠는가? 문제의 답은 간단하다. 영적무지 때문에 야기되는 것이다. 9절에 보면 ''죄에 대하여  함은 그들이  나를 믿지 아니함이요'' 이라 기록되어 있다. 예수님을 알지 못하니 믿을수도 없는것이다.
9. 적용(나)
 주님의 뜻대로 잘 살아야겠다. 그러기위해서는 먼저 음성을 잘 들어야겠다. 주님의 뜻을 모르면 엉뚱한 방향으로 헛된 열정을 쏟을수 있기 때문이다. 주님의 음성슬 더욱 듣는 시간을 저녁때 가져야겠다.
10. 영적터치(단어/구절)
7절: 유익이라
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-04-28', '요한복음', '16장 11절 ~ 20절', '제목 없음', '(요한복음 16장11절~20절)
11. 심판에 대하여라 함은 이 세상 임금이 심판을 받았음이라
12. 내가 아직도 너희에게 이를 것이 많으나 지금은 너희가 감당하지 못하리라
13. 그러나 진리의 성령이 오시면 그가 너희를 모든 진리 가운데로 인도하시리니 그가 스스로 말하지 않고 오직 들은 것을 말하며 장래 일을 너희에게 알리시리라
14. 그가 내 영광을 나타내리니 내 것을 가지고 너희에게 알리시겠음이라
15. 무릇 아버지께 있는 것은 다 내 것이라 그러므로 내가 말하기를 그가 내 것을 가지고 너희에게 알리시리라 하였노라
16. 조금 있으면 너희가 나를 보지 못하겠고 또 조금 있으면 나를 보리라 하시니
17. 제자 중에서 서로 말하되 우리에게 말씀하신 바 조금 있으면 나를 보지 못하겠고 또 조금 있으면 나를 보리라 하시며 또 내가 아버지께로 감이라 하신 것이 무슨 말씀이냐 하고
18. 또 말하되 조금 있으면이라 하신 말씀이 무슨 말씀이냐 무엇을 말씀하시는지 알지 못하노라 하거늘
19. 예수께서 그 묻고자 함을 아시고 이르시되 내 말이 조금 있으면 나를 보지 못하겠고 또 조금 있으면 나를 보리라 하므로 서로 문의하느냐
20. 내가 진실로 진실로 너희에게 이르노니 너희는 곡하고 애통하겠으나 세상은 기뻐하리라 너희는 근심하겠으나 너희 근심이 도리어 기쁨이 되리라
  
