7.하나님 찾기(해석)
조금 있으면 주님을 볼수 없으나 조금 있으면 주님을 보리라 말씀하신다. 그안에 내포된 의미가 매우크다. 예수님 제자뿐만 아니라 이시대에 살고있는 모든 하나님의 자녀들에게 속한 내용이다. 우리가 사는 동안 믿음을 지키고 산다는 것은 결코쉬운 일이 아닌것을 예수님도 미리 아시고 계신다. 복음적인 삶을 산다는 것은 많은 저항을 각오한다는 것이다. 주님의 비전 즉 영혼구원을 가장싫어하는 사탄의 세력이 있다. 그들은 늘 거짓과 유혹 그리고 이간질등으로 하나님의 자녀들이 제대로 주의 일을 못하도록 방해를 한다. 그런까닭에 이 세상에서 사는동안 고난과  근심적인 일들이 있을수 밖에 없다. 그렇다고 늘 고통 속에만 있도록 주님께서는 우리를 방치하지는 않으셨다. 너무 힘들때는 피할수  있도록 또 그러한 방법과 지혜를 주시는 보혜사 성령님 을 우리 각자에게 주셨다. 우리가 묻기만  하면 위로의 성령님 은 우리의 길을 인도하신다. 그럼에도 우리에게 있을 고난이 완전히 없어지지는 않음을 주님은 말씀 하신다. 그럼 우리에게 그 고난을 이길 힘은 무엇인가? 당연히 주님을 의지하고 믿는 것이다. 더 구체적으로 보면 하나님 아버지 께서 이미 우리를 위해 완벽한 또 다른 세상 즉 천국을 예비하셨다. 그곳은 억울함도 없고 이별도 없는, 사탄이 공존할수 없는 너무 멋진 곳이다. 그러한 천국에서 영원히 살수 있다고 믿는다면 잠시동안 머물 이곳에서의 고통은 충분히 참고 견딜만한 것이다. 오늘 본문 내용중에 "조금 있으면" 이 모든것을 말해준다. 이 세상일이 힘들어 봤자 조금 있이면 만날 주님을 기대하며 감사하며 또한  기뻐하며 사는것이 하나님 자녀된 자들의 특권이요 본분이다.
8. 인간(해석)
7번과 내용 동일
9. 적용(나)
 조금 있으면 만날 사랑하는 예수님 그리고 사랑했던 믿음의 동역자를 묵상하는 시간을 가져야겠다.
