부활하신 예수님을 만난 제자들의 마음이 기쁠 것임을 말씀하시는 예수님
예수님을 사랑하는 자는 하나님의 뜻을 구하게 될 것이고 그렇게 구하는 자는 받을 것이라고 말씀하시는 예수님
