우리의 가장 큰 기쁨은 부와 명예와 권력에서 오는 것이 아니라, 하나님의 아들이신 예수 그리스도와 사랑을 나누는 데에 있다. 
하나님께서 보내셔서 왔고, 다시 하나님께로 간다고 정확히 말씀하시는 예수님. 
이것들을 말씀하시는 것은 일을 당하기 전과 후에 제자들의 마음에 평안을 주기 위함.
하나님의 말씀에 순종함으로 세상을 이기신 예수님 
 
