성령님과 깊이 교제하는 것에 힘을 내야 한다. 그래서 제자들만큼이나 예수님을 사랑하고 느끼며 그 기쁨을 누리고 싶다. 내게 믿음으로 인한 평안을 주신 예수님께 감사하며, 세상을 이기신 예수님을 의지하여 세상과의 싸움에서 승리해야겠다.
요즘 피로감을 많이 느낀다. 그러나 주의 은혜로 불평보다는 감사가 크다. 
비록 피곤한 나날이지만, 주님을 의지하여 주어진 시간과 장소에서 내게 맡기신 일에 충성을 다해야겠다.
 
