7.하나님 찾기 (해석) 
- 예수님께선 하나님께 기도하시는데 특별히 제자들을 위해 더욱 힘써, 빌기까지 하시며 기도하신다. 또한 그들로 말미암아 영광을 받았다고 하나님께 말씀하신다. 이 기도 후에 예수님께선 십자가에 매달릴 예정인데 어째서 영광을 받았다고 말씀하시는 것일까? 
- 예수님이 떠나신 후에 성령을 통해 깨달음을 받은 제자들이 변화되어 살아갈 삶을 통해 예수님께서 받으실 영광을 미리 표현하신 것 같기도 하다.
8.인간(해석):
