7.하나님 찾기(해석)
자녀들을 사랑하시되 끝까지 사랑하시는 주님의 일관성 있는 성품을 봅니다. 머무는 사랑이  아닌 큰 폭포수처럼 모든사람에게 구원의 물줄기가 전달 되기를 누구보다 원하심을 느낍니다. 주님 혼자 일을 다하시는 것이 아니라 일함의 기쁨을 자녀들에도 나누어 주심으로 주님의 비전에 참여함을  통하여 함께함의 복을 주십니다. 
8. 인간(해석)
주님은 자녀들이 하나님의 사랑안에서 하나가 되기를 바라신다. 이미 창세 전부터 하나였던 하나님과 예수님 관계 처럼, 믿음 안에서 살기를 원하신다. 믿음안에서 사는 자녀들은 이미 하나님 안에  속한자들이고  이들은 하나님의 창조물인  세상의 존속물이  아닌 세상을 이끄는 귀한존재가 된것이다. 하나님의 성품을 닮은 자녀들은 모본을  보여주신 예수님의 발자취를 따라가며 하나님의 말씀대로 살때에 영적 기쁨이 자연스럽게 그들에게 임한다. 또한 그 진리의 말씀을 새로운 예비 하나님의 자녀들 에게 전함으로 비로써 자녀로서의 하나님의 대한 본분을 행하는 것이다
9. 적용(나)
 모든 사람들이 진리의 말씀으로 구원받기를 원하시는 예수님을 발견합니다. 나도 주님의 심정을 품고  전도하기 위해  마포대교를 다녀와야겠다.
