4.주제만들기 : 예수님을 판 유다
5.하나님 찾기 (관찰)
- 제자들과 기도론 시내 건너편 동산으로 가심
- 당할 일을 아시고 누구를 찾는지 물어보심
- 찾는자가 자신이라고 말하시며 제자들이 가는 것을 허락하라고 말씀하심
- 아버지께서 내게 주신 자 중 하나도 잃지 아니하였다는 말씀을 이루심
6.인간 찾기 (관찰)
- 예수님을 판 유다는 대제사장들과 바리새인들로부터 얻은 아랫사람들을 데리고 예수를 잡으러 감
- 베드로는 칼을 빼어 대제사장의 종을 쳐 오른쪽 귀를 베어버림
7.하나님 찾기 (해석) 
- 십자가를 짊어지실 것을 아시면서도 먼저 유다에게 나아가시는 예수님
- 끝까지 제자들을 지키시는 예수님
8.인간(해석):
- 죄 없는 예수님을 잡아가기 위해 무기를 소지하고 나타난 인간들
- 예수님께서 이루실 일들을 인식하지 못하고 행동이 앞서 죄를 짓는 베드로
9. 적용(나): 
- 예수님께선 마지막을 준비하시고자 겟세마네 동산을 올라가신다. 마지막으로 하나님께 기도를 드리고 유다를 맞이할 준비를 마치셨다. 유다와 종들이 등불과 횃불을 준비한 것으로 보아 날이 어두웠을 때 예수님을 잡으러 간 것 같다. 예수님께선 어둠으로 자신을 식별하는데 어려움이 있을걸 아시고 먼저 나서서 자신이 예수임을 밝히셨다. 예수님께선 제자들을 위해 먼저 나서서 자신의 신분을 드러내셨다. 
- 대제사장들과 바리새인들은 조용한 어둠이 있을 때 예수님을 잡으러 갔다. 어둠이 있어야 자신들의 행적들이 대중들에게 노출되지 않고, 아랫사람들을 시켜 일을 진행해야 문제가 발생해도 자신들이 관여하지 않았다고 발뺌할 수 있기 때문이다.
- 똑같은 밤을 보내도 예수님은 의로운 길을 지키셨고 대제사장과 바리새인, 유다는 악의 길을 선택했다. 사탄은 같은 상황과 환경에서도 악한 길로 이끌 수 있는 힘이 있다는 것을 느낀다. 사탄의 계략에 넘어가지 않도록 예수님만 붙잡아야겠다.
- 베드로는 예수님을 위한 행동처럼 보이지만 예수님께선 하나님의 말씀을 이루게 하시려 제자들 중 한명도 잃지 않기 위해 먼저 나섰던 것들을 인식하지 못했다. 사탄은 의로운 길로 가는 중 생각지도 못한 문제를 공동체 안에 줄 수 있다는 것을 깨닫는다. 그럴 때 기도로 말씀으로 구성원이 의의 길로 바로 서도록 도와주어야겠다. 예수님께서 베드로에게 찾아가신 것처럼...
10. 영적터치(단어/구절) : 다 아시고 나아가
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

