20. 예수께서 대답하시되 내가 드러내 놓고 세상에 말하였노라 모든 유대인들이 모이는 회당과 성전에서 항상 가르쳤고 은밀하게는 아무 것도 말하지 아니하였거늘
  
3331 생명의 큐티
