1:감동받는 단어나 구절 찾기(영적터치)
2023년 5월13일 요한복음18장 11절~20절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
예수: 11절 12절 15절(2) 19절 20절
베드로: 11절 15절 16절(2) 17절 18절
대제사장 장인 안나스: 13절 15절 16절 19절
여종:16절 17절
잡힘: 12절(2) 13절 
4. 주제 만들기
주제: 잡히신 예수
5.하나님 찾기 (관찰)
잡히신 예수
끌려가시는 예수
대제사장이었던 안나스에게 끌려가 심문받으시는 예수
안나스에게 대답하시는 예수
6.인간 찾기 (관찰)
예수를 잡고 끌고 가는 군인들
여종의 묻는말에 예수를 모른다고 배신하는 베드로
예수를 심문하는 안나스
예수가 죽는것이 유익하다고 말하는 대제사장 가야바

7.하나님 찾기(해석)
11절에 보면 예수님은 말씀하셨다.
"아버지께서 주신 잔을 내가 마시지 아니하겠느냐" 14절의 내용과 완전히 배치되는 내용이다. 예수님은 아버지가 주신 잔 곧 십자가의죽음 도 피하지 않으셨다. 자신이 죽음으로서 많은 백성이 구원을 받는다면 기꺼히 그 십자가의 잔을 붙잡으셨다.
예수님의 희생정신 뿐만아니라 겸손 하신 성품을 볼수있다.
군인들이 예수가 누구인지 모를정도로 예수님의 행세는 제자들과 똑같이 평범했음을 알수있다. 권위주의자로써 군림하고자 했던 당시 종교지도자들과 달리 섬기는 분이셨다.
8. 인간(해석)
실패한 두사람을 볼수있다. 첫번째는  대제사장인 가야바이다. 14절에 보면, "가야바는 유대인들에게 한 사람이 백성을 위하여 죽는 것이 유익하다고 권고하던 자러라."
기록되어 있듯이 그때당시 놀라운 말과 능력을 행하며 백성들에게 인기를 끌었던 경쟁자로 여기었던 예수의 죽음이 백성에게 유익하다는 것을 말하고 있다. 얼핏보면 좋은 의미같지만 사실의미는 예수를 제거하므로 백성들이 다른마음  갖지못하고 기득권 종교지도자가 원래방식으로 이끌수있다는것을 의미한다. 즉 잘못된 기득권 욕심에 진리의  예수님을 희생시킨다는 것이다.
또다른 실패자는 베드로다. 예수님을 위하여 목숨을 바치겠다고 호언장담 하였던 모습은 온데간데 없고 여종의 묻는말의 답변 으로 나는 예수의 제자가 아니라 말했다. 그리고 나서 추위를 피하기위하여 그 여종과 함께 불을 함께 쬐었다. 그때 베드로가 느꼈을 창피함과 비굴함  이 얼마나 컸을까?  쬐고있던 불이 몸을 잠시 녹였을지는 모르지만 그의 영혼은 꽁꽁 얼어붙어 있었을 것이다.
9. 적용(나)
 예수님을 중심에 두지않으면 실패한 인생이 될수밖에 없다. 잘될때는 군림자가 되고 안될때는 비겁자가 또는 주를 배신하는 사람이 된다. 그러므로 늘 주님을 중심에두고 겸손하고 헌식적이며 섬기는 사람이 되야겠다. 주님의 십자가 헌신을 더욱 묵상하는 시간을 가져야겠다.
10. 영적터치(단어/구절)
11절: 아버지께서 주신 잔을 내가 마시지 사니하겠느냐
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-05-05', '요한복음', '18장 21절 ~ 30절', '제목 없음', '(요한복음 18장 21절~30절)
21. 어찌하여 내게 묻느냐 내가 무슨 말을 하였는지 들은 자들에게 물어 보라 그들이 내가 하던 말을 아느니라
22. 이 말씀을 하시매 곁에 섰던 아랫사람 하나가 손으로 예수를 쳐 이르되 네가 대제사장에게 이같이 대답하느냐 하니
23. 예수께서 대답하시되 내가 말을 잘못하였으면 그 잘못한 것을 증언하라 바른 말을 하였으면 네가 어찌하여 나를 치느냐 하시더라
24. 안나스가 예수를 결박한 그대로 대제사장 가야바에게 보내니라
25.  시몬 베드로가 서서 불을 쬐더니 사람들이 묻되 너도 그 제자 중 하나가 아니냐 베드로가 부인하여 이르되 나는 아니라 하니
26. 대제사장의 종 하나는 베드로에게 귀를 잘린 사람의 친척이라 이르되 네가 그 사람과 함께 동산에 있는 것을 내가 보지 아니하였느냐
27. 이에 베드로가 또 부인하니 곧 닭이 울더라
28.  그들이 예수를 가야바에게서 관정으로 끌고 가니 새벽이라 그들은 더럽힘을 받지 아니하고 유월절 잔치를 먹고자 하여 관정에 들어가지 아니하더라
29. 그러므로 빌라도가 밖으로 나가서 그들에게 말하되 너희가 무슨 일로 이 사람을 고발하느냐
30. 대답하여 이르되 이 사람이 행악자가 아니었더라면 우리가 당신에게 넘기지 아니하였겠나이다
  
