7.하나님 찾기(해석)
구원자 이신 예수께서 십자가의 죽음을 앞두시고 많은 핍박을 받으셨다. 기득권을 지키려는 세력에게 무시당하고 심지어는 맞으시고 결박당하고 이리저리 끌려가시는 모습을 본다. 우주만물을 창조하신 주님께서 피조물인 사람들을 사랑하사 참으시며 끌려가셨다. 더 가슴아픈 일은 수년동안 동고동락 하며 지도받았던 수제자 베드로의 배신이었을 것이다. 
8. 인간(해석)
사탄으로 부터 묶여있는 결박을 풀어주기 위하여 참으사 스스로 육적으로 결박당하시고 묵묵히 끌려가시는 예수님, 대비하여 본성이 약하고 사악한 인간들을 본다. 기득권 을 유지하기위하여 몸부림 치는 사람들, 그밑에서 인정받기 위하여 악한행동하는 사람들... 한때는 목숨까지 걸고 따르겠다는 제자 조차  큰 위기 가운데 배신하는 모습이 있다.
그래도 짙은 어두운 배경가운데에서도 한가닥  소망의 빛이 있는것은 베드로가 배신할것을 미리알려주신 예수님 말씀으로 인하여 실낙같은 용서의기회가 있다는것이다.
