2023년 5월16 요한복음 19장 1절~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
-가시관(2,5절), 십자가(6,10절), 죄(4,6절), 십자게 못 박으소서(6절), 자색 옷(2,5절)
4.주제만들기 : 예수님을 내어주는 빌라도
5.하나님 찾기 (관찰)
- 조롱 받으시는 예수님
6.인간 찾기 (관찰)
-예수님을 채찍질하는 빌라도
-가시나무로 관을 엮어 머리에 씌우고 자색 옷을 입히고 조롱하며 때리는 군인들 
-유대인들에게 예수님의 죄를 찾지 못하였다고 말하는 빌라도
-가장 초라한 모습으로 대중에게 예수님을 소개하는 빌라도 
-십자가에 못 박으라 소리치는 대제사장과 아랫 사람들
-자신은 죄를 찾지 못했으므로 대중들에게 직접 십자가에 못박으라고 말하는 빌라도 
-유대인으로 법으로 당연히 십자가에 못박힌다는 유대인들
-유대인을 두려워하며 마지막으로 예수님께 묻는 빌라도
7.하나님 찾기 (해석)
-하나님께 순종하시고자 조롱과 핍박, 고난을 묵묵히 감당하시는 예수님
8.인간(해석):
-인간의 죄성에 대한 두가지 모습을 볼 수 있는데 첫번째는 알지 못하며 짓는 죄(군인, 대제사장, 바리새인), 두번째는 알면서도 짓는 죄(빌라도)이다. 그 중 빌라도의 행동은 간사하기도 하지만 높은 자리에 있으면서 대중을 사로잡지 못한 능력에 안타까움이 들기도 하다. 예수님을 내어주면 예수를 믿지 않는 많은 유대인에게 신임을 얻을거란 어리석은 생각을 했던것 같다. 그 결과는 사도신경에 이름을 올려 평생 예수를 핍박한 자로 이름이 오르락 내리락 하고 있다. 
-인간의 죄성이 주는 무서움도 느낄 수 있는데 빌라도는 예수님을 신문하며, 질문하며 죄가 없는 것을 확인했지만 자신을 위해 정치적으로 사용하고자 하는 욕망이 사실보다 앞서게 되는 죄성에 대해 생각해본다. 
9. 적용(나): 
- 내가 바라는 기도 제목을 보면 당장 필요한 요구사항들이 대부분이다. 예수님을 뜻을 바라는 기도 제목은 없다. 예수님이 바라지 않는 일들을 추진하다보면 나도 모르게 죄의 유혹에 넘어가버리는 자신을 발견한다. 
- 나의 기도 제목엔 알면서 멈추지 못하는 죄를 지을지 모르는 것들이 참으로 많다. 당장 앞만 보며 현재 마주한 현실만 회피하고자 하는 바람들은 오히려 죄를 더 짓게 만드는 일이 될 수 있음을 깨닫는다. 
- 예수님께서 십자가를 지시지 않고 악한 세상을 당장 심판했다면 한달은 백성들이 기뻐했을 것이다.(한달이 안걸렸을 수도 있고) 그러나 한달이 지나면 분명 불평불만들이 여기저기서 나오기 시작했을 것이다. 그것은 인간이 또 죄를 짓는 길이다. 예수님께선 십자가를 통해 죄에서 완전히 돌이킬 수 있는 방법과 기회를 제공해주셨다. 그렇기에 하나님 뜻에 따른 예수님의 순종은 더욱 대단하게 느껴진다. 
- 예수님께 전적으로 맡기는 기도와 삶을 살아가고 싶다. 그것이  알면서 짓는 죄에서 벗어나고 알지 못하며 짓는 죄도 피할 유일한 길이다. 
10. 영적터치(단어/구절)
11. 믿음과 회개 및 감사기도로 마무리
대답하여 주지 아니하시는지라
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-05-08', '요한복음', '19장 11절 ~ 20절', '제목 없음', '(요한복음 19장11절~20절)
11. 예수께서 대답하시되 위에서 주지 아니하셨더라면 나를 해할 권한이 없었으리니 그러므로 나를 네게 넘겨 준 자의 죄는 더 크다 하시니라
12. 이러하므로 빌라도가 예수를 놓으려고 힘썼으나 유대인들이 소리 질러 이르되 이 사람을 놓으면 가이사의 충신이 아니니이다 무릇 자기를 왕이라 하는 자는 가이사를 반역하는 것이니이다
13. 빌라도가 이 말을 듣고 예수를 끌고 나가서 돌을 깐 뜰(히브리 말로 가바다)에 있는 재판석에 앉아 있더라
14. 이 날은 유월절의 준비일이요 때는 제육시라 빌라도가 유대인들에게 이르되 보라 너희 왕이로다
15. 그들이 소리 지르되 없이 하소서 없이 하소서 그를 십자가에 못 박게 하소서 빌라도가 이르되 내가 너희 왕을 십자가에 못 박으랴 대제사장들이 대답하되 가이사 외에는 우리에게 왕이 없나이다 하니
16. 이에 예수를 십자가에 못 박도록 그들에게 넘겨 주니라
17.  그들이 예수를 맡으매 예수께서 자기의 십자가를 지시고 해골(히브리 말로 골고다)이라 하는 곳에 나가시니
18. 그들이 거기서 예수를 십자가에 못 박을새 다른 두 사람도 그와 함께 좌우편에 못 박으니 예수는 가운데 있더라
19. 빌라도가 패를 써서 십자가 위에 붙이니 나사렛 예수 유대인의 왕이라 기록되었더라
20. 예수께서 못 박히신 곳이 성에서 가까운 고로 많은 유대인이 이 패를 읽는데 히브리와 로마와 헬라 말로 기록되었더라
  
