2023년 5월17일 요한복음19장 11절~20절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
예수: 11절(3번) 12절(3번) 15절 16절 17절(2번) 18절(2번) 19절 20절
십자가 못 박음: 15절(2) 16절 1절 19절 20절
왕: 12절 14절 15절(2) 19절
빌라도: 11절 12절 13절 14절 15절 19절
가이사: 12절(2) 15절
유대인들: 14절 15절 20절
4. 주제 만들기
주제: 십자가에 못박히신 예수
5.하나님 찾기 (관찰)
빌라도에게 변호하시는 예수
끌려가시는 예수 
십자가에 못 박히신 예수 
6.인간 찾기 (관찰)
예수를 풀어주려 애쓰는 빌라도
예수를 십자가에 못받기를 간청하는 유대인들 
유대인들의 외침에 수긍하여 예수를 죽이는 빌라도 
7.하나님 찾기(해석)
14절에 보면 이시기는 공교롭게도 유월절의 준비일 로 기록되어 있다. 유월절 에 대한 구약의 의미는 문설주와 인방에 양의 피를 바르면 죽음이 피해 돌아가므로 실제로 이스라엘 백성들의 장자는 목숨을 지킬수 있었다. 신약에서의 유월절 의 피는 곧 십자가의죽음 을 의미한다. 그분은 사실 힘이 없으셔서 죽으신것이 아니라 사람들을 구원하시기위해 스스로 잡히시고 십자가형을 받으셨다. 구약의 유월절은 각 가정의 장자를 구원한 사건이면 십자가의 죽음 은 하나님께서 우리를 위하여 독생자아들 예수를 내어주신 위대한 사건이다.  그분의 숭고한사랑과 겸손함을 깨우친다.
8. 인간(해석)
빌라도는 예수님이 보통분이 아니라는 사실을 느끼고 있는 까닭에 풀어주려고 노력을 하였다. 하지만  군중들은 흔들리는 그에게 로마황제 가이사를 끌어당긴다. 능력자 예수보다 세상의 왕에 대하여 두려움을 느낀 빌라도는 군중들이 원하는데로 예수를 십자가형을 치르도록 허락한다. 영적으로 온전히 깨어있지 않으면 결정적인 순간에 세상과 더불어 타협하게된다. 한편 사탄은 무지한 사람들을 이용하여 상대의 제일 약한부분을 교묘하게 파고드는 특징이 있다. 
9. 적용(나)
 오늘도 나의죄를 위하여 대신 십자가에서 죽으신 예수님 사랑을 깊이 묵상해야겠다
10. 영적터치(단어/구절)
14절: 이 날은 유월절의 준비일이요
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-05-09', '요한복음', '19장 21절 ~ 30절', '제목 없음', '(요한복음 19장21절~30절)
21. 유대인의 대제사장들이 빌라도에게 이르되 유대인의 왕이라 쓰지 말고 자칭 유대인의 왕이라 쓰라 하니
22. 빌라도가 대답하되 내가 쓸 것을 썼다 하니라
23. 군인들이 예수를 십자가에 못 박고 그의 옷을 취하여 네 깃에 나눠 각각 한 깃씩 얻고 속옷도 취하니 이 속옷은 호지 아니하고 위에서부터 통으로 짠 것이라
24. 군인들이 서로 말하되 이것을 찢지 말고 누가 얻나 제비 뽑자 하니 이는 성경에 그들이 내 옷을 나누고 내 옷을 제비 뽑나이다 한 것을 응하게 하려 함이러라 군인들은 이런 일을 하고
25. 예수의 십자가 곁에는 그 어머니와 이모와 글로바의 아내 마리아와 막달라 마리아가 섰는지라
26. 예수께서 자기의 어머니와 사랑하시는 제자가 곁에 서 있는 것을 보시고 자기 어머니께 말씀하시되 여자여 보소서 아들이니이다 하시고
27. 또 그 제자에게 이르시되 보라 네 어머니라 하신대 그 때부터 그 제자가 자기 집에 모시니라
28.  그 후에 예수께서 모든 일이 이미 이루어진 줄 아시고 성경을 응하게 하려 하사 이르시되 내가 목마르다 하시니
29. 거기 신 포도주가 가득히 담긴 그릇이 있는지라 사람들이 신 포도주를 적신 해면을 우슬초에 매어 예수의 입에 대니
30. 예수께서 신 포도주를 받으신 후에 이르시되 다 이루었다 하시고 머리를 숙이니 영혼이 떠나가시니라
  
