2023년 5월18일 요한복음19장 21절~30절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
예수: 23절 26절 28절(2) 29절 30절
유대인의 왕: 21절(2)
옷: 23절(3) 24절(2)
십자가: 23절 25절 
응하게: 24절 28절
군인들: 23절 24절
4. 주제 만들기
주제: 십자가에서 다 이루신 예수
5.하나님 찾기 (관찰)
끝까지 어머니인 마리아를 챙기는 예수
십자가에서 다 이루었다 선포하신 예수
십자가에서 죽으신 예수
6.인간 찾기 (관찰)
빈정거리는 대제사장 
조롱하는 병사들(예수님의 옷 나눔)
십자가 주변에 서있는 사람들
7.하나님 찾기(해석)
많은 핍박과 조롱속에서도 십자가의 죽음을 참으시사 모든 것을 예수님은 이루셨다. 즉 세상의 구원의 역사가 시작됨을 알리는 위대한 사건이다. 영적 구원의 포문을 여신 주님께서는 육적인 그의 어머니 마리아를 끝까지 챙기시는 인간적인 사랑도 보여주신다.
8. 인간 찾기(해석)
끝까지 사랑을 베푸시는 예수님의 모습과 상반되게 마지막까지 예수님을 핍박하며 빈정거리는 사람들을 발견한다. 대제사장은  유대인의 왕 이라는 푯말에 ''자칭'' 이라는 말을 끼워놓으려고 시도한것처럼 끝까지 예수님을 모독하는데 힘썼다. 병사들도 마찬가지로 예수님의 겉옷을 나누기도 하며 속옷조차도 제비뽑기로 나누면서 빈정거리는 모습을 볼수있다. 병사들이 예수님의 옷을 취하는 것이나  십자가에서 목마르다 하신 내용은 이미 구약성경에 기록되어 있다고 되어있는것을 알수있다. 24절에 성경에 응하게 하려 함이러라  28절에 성경을 응하게 하려하사 로 증명할수있다. 그러면 당시에 하나님말씀에 해박한 대제사장은 말씀대로 경험했음에도 회개했다는 기록이 없다.  교만이 높으면 말씀의 지식이 많거나 경험이 있어도 헛된 종교인이 될수있음을 깨우치게 한다.
9. 적용(나)
 귀한 십자가 복음을 오늘도 노방전도를 통하여 잘 전달해야겠다
10. 영적터치(단어/구절)
30절: 다이루었다
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-05-10', '요한복음', '19장 31절 ~ 42절', '뼈가 꺾이지 않으신 예수', '[요19:31-42]
31 이 날은 준비일이라 유대인들은 그 안식일이 큰 날이므로 그 안식일에 시체들을 십자가에 두지 아니하려 하여 빌라도에게 그들의 다리를 꺾어 시체를 치워 달라 하니
32 군인들이 가서 예수와 함께 못 박힌 첫째 사람과 또 그 다른 사람의 다리를 꺾고
33 예수께 이르러서는 이미 죽으신 것을 보고 다리를 꺾지 아니하고
34 그 중 한 군인이 창으로 옆구리를 찌르니 곧 피와 물이 나오더라
35 이를 본 자가 증언하였으니 그 증언이 참이라 그가 자기의 말하는 것이 참인 줄 알고 너희로 믿게 하려 함이니라
36 이 일이 일어난 것은 그 뼈가 하나도 꺾이지 아니하리라 한 성경을 응하게 하려 함이라
37 또 다른 성경에 그들이 그 찌른 자를 보리라 하였느니라
38 아리마대 사람 요셉은 예수의 제자이나 유대인이 두려워 그것을 숨기더니 이 일 후에 빌라도에게 예수의 시체를 가져가기를 구하매 빌라도가 허락하는지라 이에 가서 예수의 시체를 가져가니라
39 일찍이 예수께 밤에 찾아왔던 니고데모도 몰약과 침향 섞은 것을 백 리트라쯤 가지고 온지라
40 이에 예수의 시체를 가져다가 유대인의 장례 법대로 그 향품과 함께 세마포로 쌌더라
41 예수께서 십자가에 못 박히신 곳에 동산이 있고 동산 안에 아직 사람을 장사한 일이 없는 새 무덤이 있는지라
42 이 날은 유대인의 준비일이요 또 무덤이 가까운 고로 예수를 거기 두니라

