2023년 5월19일 요한복음 19장 31절~42절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
-준비일(31,42절), 안식일(31절) 다리를 꺾다(31,32,33,36절), 찌르다(34,37절), 시체(31,38,40절), 십자가(31,41절), 증언(35절), 참(35절), 성경(36,37절) 빌라도(31,38절), 동산(41절), 무덤(41,42절)
4.주제만들기 : 뼈가 꺾이지 않으신 예수
5.하나님 찾기 (관찰)
6.인간 찾기 (관찰)
-십자가에 못박힌 자들의 다리를 꺾는 군인들
-예수님이 돌아가신 것을 보고 창으로 옆구리를 찌른 군인들
-다리를 꺾지 않고 창으로 찌른 것을 본 증인들
-예수의 시체를 가져가길 구하는 요셉, 허락하는 빌라도
-니고데모 몰약과 침향을 섞은 것을 가져와 세마포로 쌈
-새 무덤에 예수님을 둠
7.하나님 찾기 (해석) 
8.인간(해석):
-안식일에 시체 두는 것을 원치 않았던 유대인들은 아직 죽지 않은 자들의 뼈를 꺾어서라도 십자가에서 시체를 치우길 원했다. 안식일이기도 했지만 예수님께서 십자가에 매달라 죽으신 것에 대한 두려움도 있었기 때문에 빨리 그 상황을 정리하고 싶었을 것 같다는 생각을 해본다.
-군인들은 예수님이 죽으신 것을 알고 창으로 옆구리를 찔렀는데 뼈가 꺾이지 않는 것과 찌른 자를 보리라는 성경의 말씀이 이루어지도록 사용되었다. 
-요셉과 니고데모는 대중에게 자신들이 예수님을 믿는 것이 노출될 수 있음에도 불구하고 목숨을 걸고 예수님의 시체를 가져와 향품과 세마포에 싸서 새 무덤에 예수님을 모셨다. 
9. 적용(나): 
-때로는 하나님의 응답이 없이 정체되어 있는 순간에 나의 반응도 함께 멈춰있는 것이 아니라 먼저 하나님께 다가가야겠다는 생각을 해본다. 예수님께서 돌아가시고 난 후 제자들은 예수님과의 소통이 단절되어 절망과 두려움에 빠졌을 수도 있지만 요셉과 니고데모는 목숨 걸고 예수님의 시신을 무덤에 두고 오는 담대한 행동을 선택했다. 
-예수님께서 즉시 반응하지 않더라도 예수님께 먼저 나아가는 훈련을 해야겠다.  
10. 영적터치(단어/구절) 예수님의 제자이나 유대인이 두려워 숨겼더니 
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-05-11', '요한복음', '20장 1절 ~ 10절', '제목 없음', '(요한복음 20장 1절~10절)
1.  안식 후 첫날 일찍이 아직 어두울 때에 막달라 마리아가 무덤에 와서 돌이 무덤에서 옮겨진 것을 보고
2. 시몬 베드로와 예수께서 사랑하시던 그 다른 제자에게 달려가서 말하되 사람들이 주님을 무덤에서 가져다가 어디 두었는지 우리가 알지 못하겠다 하니
3. 베드로와 그 다른 제자가 나가서 무덤으로 갈새
4. 둘이 같이 달음질하더니 그 다른 제자가 베드로보다 더 빨리 달려가서 먼저 무덤에 이르러
5. 구부려 세마포 놓인 것을 보았으나 들어가지는 아니하였더니
6. 시몬 베드로는 따라와서 무덤에 들어가 보니 세마포가 놓였고
7. 또 머리를 쌌던 수건은 세마포와 함께 놓이지 않고 딴 곳에 쌌던 대로 놓여 있더라
8. 그 때에야 무덤에 먼저 갔던 그 다른 제자도 들어가 보고 믿더라
9. (그들은 성경에 그가 죽은 자 가운데서 다시 살아나야 하리라 하신 말씀을 아직 알지 못하더라)
10. 이에 두 제자가 자기들의 집으로 돌아가니라
  
