예수님 시신에 대하여 소식을듣고 달려가서 빈무덤을 보는 베드로와 사도요한
7.하나님 찾기(해석)

8. 인간 찾기(해석)
예수님께서 공생애 동안 제자들에게 부활에 관하여 수차례 말씀하셨다. 부활에 관하여 간접적으로, 비유로도 설명하셨고 특별히 요한복음11장25에 보면 "나는 부활이요 생명이니 나를 믿는 자는 죽어도 살겠고" 라고 예수님께서 본인을 향하여 직접 언급도 하셨다. 미리 말씀하신 일이 현실로 이루어졌음에도 제자들 중 리더그룹격인 베드로와 사도요한은 예수님의 부활을 아직 알지못하였다. 성경 중심적 입장에서 보면 얼마나 답답하게 보였을까 생각이 든다. 주님이 이땅에 오신이유가 단지 표적과 구제를 행하기 위해서 오신것이 아니라 죽으시고 부활하심으로 하나님의 아들이요 구원자이신것을 가르쳐 주셔서 사람들로 하여금 믿게함이 근본적 목적이셨다. 그럼에도 막달라 마이아와 제자들(베드로와요한)은 단지 누군가가 주님의 시신을 옮겼다라고 생각하는것 같다. 평상시의 믿음의 훈련이 얼마나 중요한지를 일깨워진다.      
9. 적용(나)
 믿음에 대하여  더욱 성찰하는 시간을 가져야겠다 
