1:감동받는 단어나 구절 찾기(영적터치)

2023년 5월23일 요한복음 21장 1절~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천) 
- 제자(1,2,8절), 베드로(2,3,7절), 물고기(3,5,6,8절), 잡다(3,6절), 배(3,6,8절), 생선(9,10절)
4.주제만들기 : 제자들을 찾아오신 예수님
5.하나님 찾기 (관찰)
-제자들을 찾아가신 예수님
-제자들에게 고기가 있냐고 물으시는 예수님
-그물을 오른편에 던지라고 말씀하시는 예수님
-생선과 떡을 준비하신 예수님 
6.인간 찾기 (관찰)
-물고기를 잡으러 가는 제자들
-물고기를 잡지 못한 제자들
-예수님의 말씀을 따라 그물을 오른편에 내리는 제자들
-예수님을 알아보는 제자들
-옷을 입고 바다로 내려가는 베드로
7.하나님 찾기 (해석)
-영적으로 무너져 있는 제자들을 찾아가 처음 제자들을 만날 때의 기억을 떠오르게 해주시는 예수님 그런데 한가지 다른 점은 육지에 생선과 떡이 숯불 위에 올려져 있다. 베드로를 위로하기 위함도 있지만 제자들을 위로하고자하는 예수님의 사랑이 느껴진다.
8.인간(해석):
-예수님의 십자가 사건으로 모든 것이 끝났다 생각한 제자들은 다시 고기를 잡으러 갔다. 하지만 하루 종일 고기를 잡아려해도 잡히지 않았다. 그 때 예수님이 오셔서 말씀하신다. 그 말씀이 예수님과 처음 만났던 상황과 동일함에도 예수님을 알아보지 못한다. 아마 영과 정신적으로 많이 힘들었을 것이다. 그물을 오른쪽으로 내리고 들어올릴 수 없을 정도로 고기가 잡힌 것을 경험하고야 예수님임을 깨닫는다. 그리고 예수님께 달려간다.  
9. 적용(나): 
-제자들에게 있어 예수님은 생명과 같다는 생각을 한다. 무기력한 삶에 나타나신 예수님은 삶의 활력소가 되어 주셨다. 
-예수님께선 제자들을 처음 부르실 때 사람을 낚는 어부가 되겠다고 하셨다. 그런데 예수님의 뜻이 아닌 나의 의지로 일, 사역 등을 할 때 아무것도 잡지 못하는 제자들이 될 수 있다는 생각이 들었다. 예수님이 원하시고 예수님과 동행해야 선한 길로 갈 수 있음을 느낀다. NKFC의 사역 또한 마찬가지이다. 예수님께서 원하시는 곳에 그물을 던지고 있는지 다시 점검해보아야겠다. 그리고 그걸 깨달을 수 있는 영안도 생기길 원한다.
-오늘 말씀에서 베드로는 옷을 고쳐 입고 바다로 내려가 예수님께 간다. 그런데 거리가 짧기 때문에 배타고 가는 것이 유리하다. 다소 황당한 베드로의 행동은 베드로가 예수님을 부인한 후 심적인 아픔을 얼마나 크게 가지고 있었는지 가늠케 한다. 베드로에게 예수님의 존재는 생명수와 같다는 것이 그의 행동에서 느껴진다. 세례를 받을 때처럼 예수님을 정결한 모습으로 맞이하고 싶어서였을까? 아니면 자신의 눈물을 가리기 위해 바다에 들어간 것일까? 알 수는 없지만 베드로의 간절함은 진실되게 느껴진다. 
10. 영적터치(단어/구절) : 제자들에게 자기를 나타내셨으니
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-05-15', '요한복음', '21장 11절 ~ 25절', '제목 없음', '(요한복음 21장11절~25절)
11. 시몬 베드로가 올라가서 그물을 육지에 끌어 올리니 가득히 찬 큰 물고기가 백쉰세 마리라 이같이 많으나 그물이 찢어지지 아니하였더라
12. 예수께서 이르시되 와서 조반을 먹으라 하시니 제자들이 주님이신 줄 아는 고로 당신이 누구냐 감히 묻는 자가 없더라
13. 예수께서 가셔서 떡을 가져다가 그들에게 주시고 생선도 그와 같이 하시니라
14. 이것은 예수께서 죽은 자 가운데서 살아나신 후에 세 번째로 제자들에게 나타나신 것이라
15.  그들이 조반 먹은 후에 예수께서 시몬 베드로에게 이르시되 요한의 아들 시몬아 네가 이 사람들보다 나를 더 사랑하느냐 하시니 이르되 주님 그러하나이다 내가 주님을 사랑하는 줄 주님께서 아시나이다 이르시되 내 어린 양을 먹이라 하시고
16. 또 두 번째 이르시되 요한의 아들 시몬아 네가 나를 사랑하느냐 하시니 이르되 주님 그러하나이다 내가 주님을 사랑하는 줄 주님께서 아시나이다 이르시되 내 양을 치라 하시고
17. 세 번째 이르시되 요한의 아들 시몬아 네가 나를 사랑하느냐 하시니 주께서 세 번째 네가 나를 사랑하느냐 하시므로 베드로가 근심하여 이르되 주님 모든 것을 아시오매 내가 주님을 사랑하는 줄을 주님께서 아시나이다 예수께서 이르시되 내 양을 먹이라
18. 내가 진실로 진실로 네게 이르노니 네가 젊어서는 스스로 띠 띠고 원하는 곳으로 다녔거니와 늙어서는 네 팔을 벌리리니 남이 네게 띠 띠우고 원하지 아니하는 곳으로 데려가리라
19. 이 말씀을 하심은 베드로가 어떠한 죽음으로 하나님께 영광을 돌릴 것을 가리키심이러라 이 말씀을 하시고 베드로에게 이르시되 나를 따르라 하시니
20. 베드로가 돌이켜 예수께서 사랑하시는 그 제자가 따르는 것을 보니 그는 만찬석에서 예수의 품에 의지하여 주님 주님을 파는 자가 누구오니이까 묻던 자더라
21. 이에 베드로가 그를 보고 예수께 여짜오되 주님 이 사람은 어떻게 되겠사옵나이까
22. 예수께서 이르시되 내가 올 때까지 그를 머물게 하고자 할지라도 네게 무슨 상관이냐 너는 나를 따르라 하시더라
23. 이 말씀이 형제들에게 나가서 그 제자는 죽지 아니하겠다 하였으나 예수의 말씀은 그가 죽지 않겠다 하신 것이 아니라 내가 올 때까지 그를 머물게 하고자 할지라도 네게 무슨 상관이냐 하신 것이러라
24. 이 일들을 증언하고 이 일들을 기록한 제자가 이 사람이라 우리는 그의 증언이 참된 줄 아노라
25. 예수께서 행하신 일이 이 외에도 많으니 만일 낱낱이 기록된다면 이 세상이라도 이 기록된 책을 두기에 부족할 줄 아노라

