2023년 5월24일 요한복음21장 11절~25절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
예수: 12절(2) 13절 14절 15절(3) 16절(3) 17절(6) 18절 20절(3) 21절(2) 22절(2) 23절 25절
