사도요한: 20절(2) 21절 24절
4. 주제 만들기
주제: 베드로를 용서하시고 다시 이끄시는 예수
5.하나님 찾기 (관찰)
제자들에게 떡과 생선을 주시는 예수
베드로에게 자신을 사랑하는지 묻는 예수
베드로에게 양(영혼)을 먹이라고 말씀하시는 예수
6.인간 찾기 (관찰)
조반을 먹는 제자들
예수님을 사랑한다고 고백하는 베드로
동료 사도요한의 일어날 일을 예수께 묻는 베드로
요한복음을 기록한 사도요한
7.하나님 찾기(해석)
예수님을 세번 부인하였던 베드로를 용서하시고  다시일으켜 사명자로 이끄시는 크신 예수님을 발견한다. 자신을 세번 부인했던 베드로에게 3번 같은 질문 을 물으신다. 네가 나를 더욱 사랑하느냐? 3번의 똑같은 질문에는 많은 의미가 함축되어 있다.  베드로야! 너가 나를 사랑하는것 알아! 또한 너가 나를 미워서 아니면 싫어서 배신한것이 아님도 알아!  다만너의 약함을 내가 알고  너가 큰 위기때 나를 세번 부인할것도 알고 너에게 미리 말해주지 않았니! 지금 내가  너에게 3번 묻는것은 너의 과거의 상처를 스스로 이기고 일어나기를 바란단다! 예수님은 베드로 스스로가  잘못을 깨우치고 예전보다 더 강한 일꾼으로 세우시는 진정한 능력의 리더이시다. 그분이 바로우리의 
선한목자 예수님 이시다.

8. 인간 찾기(해석)
예수님에 대한 사랑함을 정검받고 사명까지 부여받은 베드로, 그러한 베드로 임에도 아직 그의 연약함을 발견한다. 그중에도 동료인 사도요한이 어떻게 될지 궁금하여 예수께 묻는 마음은 걱정하는 마음이 아니라 라이벌 의식에서 나온 궁금증이었음을 알수있다. 23절에 베드로의 질문에 대한 예수님의 소견이 드러나 있다. 23절에 "내가 올  때까지 그를 머물게 하고자 할지라도 네게 무슨상관이냐" 기록되어 있다. 반면에 사도요한은 자신이 요한복음을 기록했음에도 자신의 이름을 직접드러내지 않는 화법으로 쓴것을 보면 그가 요한복음을 기록했음 쯤에는 그가 얼마나 성숙된 영성가로 성숙되어 있음을 가늠해볼수있다. 어떠한 인간도 예수님의깊은 사랑을 체험한다면 베드로와 사도요한 뿐만  누구나 멋지고 겸손한 진정한 신앙인으로 발전할수있다!  아멘!!!!

9. 적용(나)
 약한 나를 일으켜 사명자로 사용하시는 예수님의 큰 사랑을 본받아나도 나누는 삶을 살아내야겠다. 주변에 격려가 필요한 지체가 있는지 살펴보아야겠다.
10. 영적터치(단어/구절)
18절: 네가 젊어서는 스스로 띠 띠고 원하는 곳으로 다녔거니와
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

