2023년 5월15일 요한복음 18장 31절~40절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
예수: 1절, 6절
성령: 2절, 5절, 6절, 8절
아버지: 4절, 7절
세례: 5절(2)
제자들: 2절, 6절, 9절, 10절
기록: 1절, 2절
예루살렘: 4절, 8절
때: 6절, 7절

4.주제 만들기: 우리의 성령 충만함을 원하시는 예수님
5.하나님 찾기 (관찰)
부활 후 제자들에게 살아계심을 나타내시고 사십 일 동안 하나님 나라의 일을 말씀하심
사도들에게 예루살렘을 떠나지 말고 성령을 기다리라고 말씀하심
몇 날이 못되어 성령으로 세례를 받으리라 말씀하심
이스라엘의 회복의 때는 하나님의 권한이니 알고자 하지 말라 말씀하심
성령이 임하시면 권능을 받을 것이고 내 증인 되리라 말씀하심
올려져 가심

6.인간 찾기 (관찰)
부활하신 예수님께 하나님 나라와 성령에 대해 들음
이스라엘의 회복의 때를 물음
예수님의 승천을 바라봄
희 옷 입은 두 사람을 봄
 
7.하나님 찾기 (해석) 
부활에 대해 하나님 나라에 대해 깨닫지 못하는 제자들을 위해 그리고 시공간을 초월하여 믿을 자 들을 위해 확실한 증거로 부활한 자신을 나타내시고 하나님 나라에 대해 가르쳐 주신다. 예수님은 우리를 너무나 사랑하셔서 이 땅에 오셨고, 부활 후에도 동일한 사랑의 마음으로 우리의 믿음과 구원을 위해 말씀하신다.
승천 후 오실 성령님에 대해 말씀하시며 성령을 받을 때까지 예루살렘 머무르라고 말씀하심. 성령으로 오셔서 우리와 함께 영원히 동행하시고 우리에게 능력을 주시기 위함임. 성령을 받아야 우리가 권능을 받고 전도할 수 있는 힘과 능력을 받을 수 있음을 말씀하심.
예수님의 기쁨인 성령의 임재에 대해 말씀하시는데 제자들은 육신의 것인 이스라엘의 회복에 대해 물음. 예수님은 화내지 않으시고 회복의 때는 아버지께 있다고 말씀하시고 다시 한 번 성령에 대해 말씀하심. 우리가 성령을 받으면 권능을 받을 것이고 그 권능으로 예수님의 증인된 삶을 살 수 있음. 성령을 받지 않으면 예수님의 증인된 삶을 살 수가 없는 것임.

8.인간(해석):
제자들에게 있어 부활하신 예수님은 이제 그전에 알던 예수님이 아니라, 진정 100% 하나님으로 다가왔을 것이다. 부활 전에 하시던 말씀이 소중하지만 자기 것으로 50% 정도 소화했다면, 이제는 한 말씀도 놓칠 수 없는 하나님의 말씀으로 100% 믿어졌을 것이며, 실천하지 않을 수 없었을 것이다.
제자들에게 예수님이 하나님이라는 것은 직관적 믿음이 아니라 이제 사실이 되어 버렸다.
그럼에도 육신의 것인 자기 나라의 회복에 제일 관심이 있었던 것으로 보인다. 예수님은 증인된 삶을 원하시는데, 제자들은 민족의 독립에 더 관심이 있는 것이다.
성령을 받고 권능을 받으면 예수님의 증인이 될 것이라는 말씀을 듣고 말씀대로 성령을 받아야겠다고 결심했을 것이다.

9. 적용(나):
예수님은 증인된 삶을 원하시는데 나는 인간의 것을, 내가 세상에 인정받는 것을 더 원하고 있지는 않은 것인지 생각해 본다. 내가 깨닫지 못하는 이스라엘의 회복은 무엇인지 기도하며 점검받아야겠다.
 
10. 영적터치(단어/구절)
1장 8절 땅 끝까지 이르러 내 증인이 되리라

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-05-18', '사도행전', '1장 11절 ~ 20절', '변화 된 제자들', '[행1:11-20]
11 이르되 갈릴리 사람들아 어찌하여 서서 하늘을 쳐다보느냐 너희 가운데서 하늘로 올려지신 이 예수는 하늘로 가심을 본 그대로 오시리라 하였느니라
12 제자들이 감람원이라 하는 산으로부터 예루살렘에 돌아오니 이 산은 예루살렘에서 가까워 안식일에 가기 알맞은 길이라
13 들어가 그들이 유하는 다락방으로 올라가니 베드로, 요한, 야고보, 안드레와 빌립, 도마와 바돌로매, 마태와 및 알패오의 아들 야고보, 셀롯인 시몬, 야고보의 아들 유다가 다 거기 있어
14 여자들과 예수의 어머니 마리아와 예수의 아우들과 더불어 마음을 같이하여 오로지 기도에 힘쓰더라
15 모인 무리의 수가 약 백이십 명이나 되더라 그 때에 베드로가 그 형제들 가운데 일어서서 이르되
16 형제들아 성령이 다윗의 입을 통하여 예수 잡는 자들의 길잡이가 된 유다를 가리켜 미리 말씀하신 성경이 응하였으니 마땅하도다
17 이 사람은 본래 우리 수 가운데 참여하여 이 직무의 한 부분을 맡았던 자라
18 (이 사람이 불의의 삯으로 밭을 사고 후에 몸이 곤두박질하여 배가 터져 창자가 다 흘러 나온지라
19 이 일이 예루살렘에 사는 모든 사람에게 알리어져 그들의 말로는 그 밭을 아겔다마라 하니 이는 피밭이라는 뜻이라)
20 시편에 기록하였으되 그의 거처를 황폐하게 하시며 거기 거하는 자가 없게 하소서 하였고 또 일렀으되 그의 직분을 타인이 취하게 하소서 하였도다

