8.인간(해석):
- 예수님께서 십자가를 지시고 장사된지 사흘만에 다시 제자들에게 나타나신 후 하늘로 올라가셨고 그것을 본 제자들은 예수님께서 십자가를 지신 후 무너졌던 영성이 회복되기 시작했다. 심지어 예수님을 믿지 않았던 아우들은 마음을 같이하여 오로지 기도에 힘쓴다고 표현할 정도로 변화되었다. 예수님을 세 번 부인하며 울었던 베드로는 대중 앞에서서 성경에 기록된 말씀을 전할 정도로 영성이 회복된 것은 물론 강력한 리더십을 뽐내고 있다. 예수님의 완전하신 사랑은 사람을 변화시킨다.
9. 적용(나): 
- 예수님의 사랑은 나를 변화시켰다. 영적으로 무너졌던 제자들을 일으켜 세우고 믿지 않았던 자들을 믿게 만든 것처럼 예수님의 사랑은 위대하다. 저 사람은 절 때 변하지 않을거야라고 생각했던 점을 회개한다. 예수님은 포기하지 않으셨는데 나 스스로 포기한 것을 회개한다. 예수님의 사랑이 위대한 것처럼 예수님의 사랑을 경험하도록 예수님을 믿지 않는 영혼들을 위해 기도해야겠다.
