가롯유다 의 공석을 채우기 위하며 새로운 일꾼을 채우는 일을 도모한다. 새로운 사도를 세우는 방법으로는 제비뽑기로 행한다. 제비뽑기로 한다는 의미는 새로운 맴버가 후에 혹시 문제를 일으켰을때  책임회피용이 아닌, 전적으로 주님을 의지하며 뜻에 맡기겠다는 믿음의결의찬 모습으로 보여진다. 두사람중 결국 맛디아가 선정되었다. 큰 시련과 좌절을 맛본후에 더욱 그들자신을 부인하고 최고의 길을 결정하실 주님을 의지하는 성화되어가는 모습을 보여준다.
