주제: 성령님의 역사를 선포하는 베드로

5.하나님 찾기 (관찰)
요엘을 통해 성령님을 보낼 것을 말씀하신 하나님

6.인간 찾기 (관찰)
제자들이 각 지방의 언어로 말하는 것을 듣고 놀라며 당황하는 경건한 디아스포라 유대인들
제자들이 새 술에 취하였다 조롱하는 어떤 이들
