7.하나님 찾기(해석)
베드로에게 감동을 주어 설교하게 하시는 성령님
명절에 모인 디아스포라들에게 성령의 역사를 체험케 하시는 하나님

8. 인간(해석)
제자들이 지중해 연안 각 지방의 언어로 말하는 것을 들으며 놀라고 당황하는 유대인들,
같은 것을 보고 그들이 새 술에 취하였다 말하는 어떤 이들.
이 모든 사람들에게 설교하는 베드로.
성령님의 역사를 직접적으로 체험한 제자들과 성령님의 역사를 간접적으로 체험하는 이들으 반응은 다르다는 것을 볼 수 있다.
간접적으로 체험한 이들은 그것이 성령의 역사인지 술에 취한, 다시 말해 제정신이 아닌 사람의 행동인지 분간하기 어렵다.
오늘날 세상 가치관을 가진 사람들이 성령 충만한 사람들의 결단과 행동을 보면 이해하지 못하는 것과 비슷한 모습이 아닌가 생각해 본다.
그러나 베드로는 모든 사람이 알게 하려고 설교를 하기 시작한다.

9. 적용(나)
인간의 힘으로는 예수님을 세 번 부인했던 베드로가 성령님의 충만함을 받자 자신을 비난하는 자들 앞에서도 담대하게 설교를 한다. 인간의 힘이 아닌 성령님의 충만함으로 살아야 그리스도의 증인된 삶을 살 수 있다. 행 1:8. 오로지 힘써 기도하여 성령 충만함을 받은 베드로와 제자들처럼 나도 기도에 힘써 성령님을 받고 성령님의 능력으로 증인된 삶을 살아가야 한다.
 
