8.인간(해석):
- 예수님께서 십자가를 지시기 전과 후의 모습이 너무 달라 같은 사람이 맞나 생각할 정도로 제자들은 담대해졌고 변화되었다. 
9. 적용(나): 
- 우리가 소망을 가질 수 있는건 예수님의 십자가 사랑이 우리에게 임할 수 있기 때문이다. 십자가로 인해 우리는 생명의 길을 걸어갈 수 있고 기쁨이 충만할 수 있다. 십자가로 인해 우리는 변할 수 있다. 너무 감사한 일이다. 예수님의 십자가는 우리에게 새 소망을 갖게 한다. 
- 예수님의 십자가를 바라보면 내가 변할 수 있음을 확신한다. 베드로와 제자들이 담대히 말씀을 전한 것처럼 예수님을 깊이 사랑하게 되고 나 자신을 사랑하게 되어 이웃을 사랑하게 된다. 예수님의 사랑을 깨달으면 그 사랑을 이웃에게 전해야 함을 깨닫는다. 그렇기 때문에 우리는 전하는 삶을 살아야 한다. 
- 마포대교 노방전도를 준비하는데 꿈으로 두려움을 준다. 담대히 나아가길 소망한다. 예수님의 사랑이 누군가에게 전해지는 귀한 시간이 되길 기도한다.
