- 본인의 죄를 깨닫고 회개하여 예수 그리스도의 이름으로 세례를 받고 죄사함을 받으니 구원을 받음
9. 적용(나): 
- 하루를 살아도 수없이 많은 죄를 짓고 살며 그 죄를 깨닫지 못하고 살아갈때 또한 너무나 많다. 하나님을 믿는다고 살아가지만, 하나님을 생각하는 마음이 없었던 것이라 생각이 든다. 언제든지 하나님을 찾으면 찾아와주시는 하나님이신데 말이다. 성경을 읽으며 “얼마든지” 라는 단어에 감동을 받았다. 정말로 사랑할때 나올 수 있는 단어라 생각한다. 하나님으로부터 멀어지는 내가 되지 않도록 늘 깨닫고 죄에 대해 회개하는 삶이 되길 소망한다. 
