8. 인간 찾기(해석)
최초의 초대교회가 생겨날때 일어나는 현상들이 기록되어있다. 주님의 명령에 순종했던 약120명의 사람들은 성령과 더불어 충만함을 받았다. 특별히 사도 베드로가 십자가 복음을 선포할때 많은 사람들이 찔림을 받고 회개와 침례를 받고 하루 삼천명의 구원받은 사람들이 생겨났다. 구원받은 사람들은 성전에 모이기를 힘쓰고 가난한 자를 돌보고 재산을 분배하고 떡을떼며 교제한다. 그들은 하나님을 찬미하며 온 백성에게 칭송을 받으니 믿는 수가 날마다 폭발적으로 증가하는 모습을 기록했다.  진정한 교회의 자화상을 보여주고있다.
9. 적용(나)
우리 NKFC M 도 초대교회 모습처럼 주님의 복음과 사랑이 넘치는 공동체가  되기를 꿈꾸며 기도한다. 이를 위하여 오늘 간절히 기도하는 시간을 가져야겠다 
