7.하나님 찾기(해석)
반드시 해야할 일과 바라는 일이 있음을 보여준다. 제자들은  자신들이 사랑하는 조국 이스라엘의 회복을 바라며 회복의 때를 부활하신 예수께 여쭈었다. 그러나 돌아온 대답은 때와 시기는 하나님의 권한에 있으니 너희는 예루살렘과 온유대와 사마리아와 땅 끝까지 이르러 증인이 되라고 말씀하셨다. 이 부분을 곰곰히 생각해보면 주님은  우리가 바라는 일 보다는 당장 행할 일 을 정해주신것 같다. 즉 일의 우서순위를 일깨워주신다. 가령 우리가 원하는 대학의 입학, 회사 승진의 때, 또는 잃은 건강을 회복할때 등을 주님께 묻게된다면 아마도 주님께서는 아마도 이렇게 말씀 하실듯 하다. 때가 되면 내가 너희가 구하는것을 이루어 주겠지만 지금은 너희가 주어진 일에 먼저할수 있는 일에 충실하기를 바란단다. 그일은 당장 누구나 할수 있는 복음전도 이다. 예루살렘, 온유대. 그리고 사마리아와 땅끝까지 증인이 되는 방법은 순서적으로 하는것이 아니라 동시다발적 으로 하는것을 미루어 짐작하면 우리는 어떠한 환경 그중에서도 답답한 환경 또는 슬프거나 억울한 상황속에서도  복음을 전하는 삶을 살기를 주님은 원하신다. 복음을 전하는 삶을 산다면 먼저 마음에 충만함과  천국의 기쁨을 누리게될것이다. 그들에게는 적어도 주님께서 고통의 십자가에서도 마지막 까지도 강도에게 복음을 전하시고 "다이루었다" 를 고백하신 주님의 마음을 아는 축복이 임할것이다. 그리고 바라는 일들 또한 때가 되면 응답하시는 주님을 더욱 의지하는 믿음의복을 주님께서는 우리에게 주시기를 원하신다.

