5.하나님 찾기 (관찰)
6.인간 찾기 (관찰)
-담대히 말씀을 선포하는 베드로와 요한
-표적에 대해 의논하는 대제사장
7.하나님 찾기 (해석) 
-성령의 존재는 인간을 변화시킨다. 
8.인간(해석): 
-예수님을 믿고 성령님의 인도를 받는 제자들은 과거에는 하지 못했던 담대한 말들을 이어간다. 제자들은 너희의 말을 듣는 것이 아니라 하나님의 말씀을 듣는다고 말한다. 제자들이 선포한 말씀이 진리이고 정직했기 때문에 대제사장은 반박할 수 없다. 
-대제사장 무리는 나타난 표적을 보고 의논을 한다. 사탄의 개입을 분명히 느낄 수 있는 부분인데. 예수님을 알고 있지만 믿지 못하게 하는 사탄의 계략이 이 세상에 역사가 하고 있음을 알 수 있다. 
-대제사장 무리가 의논하여 내린 결론은 사도들은 위협하고 예수님의 이름으로 선포하지 말도록 하는 것이었다. 그들이 원하는건 현재 그들이 누리고 있는 삶, 지위, 명예, 돈, 권력 등이었다. 진리를 바라보지 못하고 가려진 눈은 어리석은 선택을 하게 만든다.  
9. 적용(나): 
-예수님을 안다는 것, 예수님을 믿는 것, 예수님의 사랑을 느끼는 것을 경험한 후 우리가 해야할 일은 전도이다. 예수님께 받은 사랑을 다른이에게 전하고 우리가 누리는 기쁨을 경험케 하는 것이 우리가 해야 할 사명이다. 
-머릿돌이 되시는 예수님과 동행하면 튼튼한 집을 지을 수 있다. 어떠한 자연재해가 와도 지킬 수 있는 튼튼한 집을 우리는 완성해 가야 한다. 그렇기 때문에 3331 QT를 매일하고 기도의 자리를 만들어 의지적으로 예수님의 집안에 들어가야 한다.
-세상엔 가려진 눈으로 살아가는 사람이 많다. 그들이 예수님으로 인해 눈뜨도록 노방전도 준비를 잘해야겠다.
10. 영적터치(단어/구절) 우리는 보고 들은 것을 말하지 아니할 수 없다
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

