- 성령이 충만하여 담대히 하나님의 말씀을 전하는 제자들
- 모든 물건을 서로 통용하고 자기 재물을 조금이라도 자기 것이라 하지 않는 믿는 무리
큰 권능으로 주 예수의 부활을 증언하는 사도들
- 사도들의 증언을 듣고 은혜 받는 무리
- 밭과 집 있는 자는 팔아 그 판 것의 값을 헌금과 연보로 드리는 무리
- 헌금과 연보를 각 사람의 필요를 따라 나누어주는 사도들
- 밭을 판 값을 사도들에게 내놓은 바나바

7.하나님 찾기 (해석) 
- 모인 곳이 진동할 정도로 강력하게 임하신 성령님. 예수님을 체험한 자가 예수님의 이름을 위해 강하고 담대하게 예수님을 선포하면 반드시 성령님이 함께 하신다. 그것은 듣는 이의 마음을 열게 하며 성령님의 역사로 말미암아 은혜를 받게 하고 그 받은 은혜는 다른 것이 아니라 자신의 소유를 팔아 함께 하는 사람들과 함께 사용하고 싶은 마음을 주었다. 이로 말미암아 그 공동체에는 가난하여 굶는 자 없이 모두 함께 예수님을 경배하며 살 수 있었다.
예수님을 믿으면 출교를 당하는 상황에서 이러한 헌물들은 이 공동체를 유지하게 하는 강력한 힘이 되었을 것이다.

8.인간(해석): 
- 부활하신 예수님을 목격하고 명령하신 대로 성령님을 받기 까지 모여 기도에 힘쓴 제자들에게 성령님이 임하셨다. 그리고 제자들은 이전과 다르게 강력하게 말씀을 선포하는데 그것은 제자들의 능력이 아니라 성령님의 권능으로 강하고 담대하게 말씀을 선포하는 것이다. 
- 성령님이 함께 하시는 듣는 이들도 성령의 감동으로 말미암아 은혜를 받고 이것이 복음이구나. 이것이 구원받은 자의 삶이구나 체험하게 된 것이다.
- 세상에서 느낄 수 없던 기쁨을, 하나님과 사랑에 빠지는 기쁨을 누리기에 이제는 소유가 중요하지 않고 서로 사랑하며 섬기며 살 수 있는 것이라면 그 무엇도 두렵지 않게 된 것이다.

9. 적용(나): 
- 먼저 성령 충만해야 한다. 한국 교회에 성령님이 소멸한 듯한 이 시대에, 내 삶도 성령님이 소멸되고 있진 않은가 생각해 본다. 조지 뮬러 목사님이 신학 공부하실 때에 기도가 줄어들어서 너무나 힘들었다고 쓴 일기가 생각난다. 그분과 비교할 수 없지만 지금 나도 일과 공부에 치여 주님과 교제하는 시간이 많이 줄어들어 힘이 든다. 하지만 이럴 때 포기하지 않고 성령님의 능력과 보호하심을 바라며 인내의 시간을 보내야 된다는 생각을 해본다. 성령님 없이는 그리스도의 향기도 전도도 없기 때문이다. 힘을 내어 성령님을 의지하고 말씀을 묵상하고 기도하고 전하고 전도하는 삶을 살아가야겠다.

10. 영적터치(단어/구절) 
31절 무리가 다 성령이 충만하여 담대히 하나님의 말씀을 전하니라

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-06-01', '사도행전', '5장 1절 ~ 10절', '성령을 속이는 결과', '[행5:1-10]
1 아나니아라 하는 사람이 그의 아내 삽비라와 더불어 소유를 팔아
2 그 값에서 얼마를 감추매 그 아내도 알더라 얼마만 가져다가 사도들의 발 앞에 두니
3 베드로가 이르되 아나니아야 어찌하여 사탄이 네 마음에 가득하여 네가 성령을 속이고 땅 값 얼마를 감추었느냐
4 땅이 그대로 있을 때에는 네 땅이 아니며 판 후에도 네 마음대로 할 수가 없더냐 어찌하여 이 일을 네 마음에 두었느냐 사람에게 거짓말한 것이 아니요 하나님께로다
5 아나니아가 이 말을 듣고 엎드러져 혼이 떠나니 이 일을 듣는 사람이 다 크게 두려워하더라
6 젊은 사람들이 일어나 시신을 싸서 메고 나가 장사하니라
7 세 시간쯤 지나 그의 아내가 그 일어난 일을 알지 못하고 들어오니
8 베드로가 이르되 그 땅 판 값이 이것뿐이냐 내게 말하라 하니 이르되 예 이것뿐이라 하더라
9 베드로가 이르되 너희가 어찌 함께 꾀하여 주의 영을 시험하려 하느냐 보라 네 남편을 장사하고 오는 사람들의 발이 문 앞에 이르렀으니 또 너를 메어 내가리라 하니
10 곧 그가 베드로의 발 앞에 엎드러져 혼이 떠나는지라 젊은 사람들이 들어와 죽은 것을 보고 메어다가 그의 남편 곁에 장사하니

