- 얼마(2,3절), 마음(3,4절), 혼이 떠나다(5,10절), 메다(6,9,10절), 이것뿐(8절), 장사(6,9,10절), 발 앞에(2,10절)
4.주제만들기 : 성령을 속이는 결과
5.하나님 찾기 (관찰)
6.인간 찾기 (관찰)
-아나니아와 삽비라가 자신의 소유인 땅을 팔아 제자들에게 얼마를 감추고 내어줌
-베드로는 아나니아와 삽비라를 훈계함
-아나니아와 삽비라의 혼이 떠남
7.하나님 찾기 (해석) 
8.인간(해석):
-아나니아와 삽비라를 선한 의도로(선한 의도인지는 모르겠으나) 자신의 소유인 땅을 팔아 제자들에게 가져온다. 하지만 이 때 사탄은 아나니아와 삽비라를 유혹한다. 그리고 안타까운 선택을 하게 된다. 
-성령 충만한 제자들과 베드로는 아나니아와 삽비라가 한 선택을 알고 훈계한다. 
9. 적용(나): 
-하루의 삶을 살아갈 때 성령을 속이며 자신의 유익을 위해 합리화하며 선택하는 일들이 있다. 매번 넘어지지만 성령님의 인도하심을 간구하며 올바른 선택과 행동을 할 수 있도록 기도해야겠다. 
-물질의 유혹은 참으로 잔인하다. 물질로 섬기는건 쉬운 일이 아니다. 하나님은 우리의 사정을 아시고 물질의 양으로 우리를 판단하지 않으시기 때문에 자유할 수 있다. 다만, 물질로 섬길 것은 결단했을 땐 결단이 흔들려선 안 된다. 우리는 이러한 시험에 넘어지지 않도록 노력해야한다. 
-베드로는 아나니아에게 사탄이 네 마음에 가득하고, 이 일을 네 마음에 두었냐고 말을 한다. 사탄은 우리의 결단이 흔들리도록 유혹한다. ‘이 정도면 충분해’, ‘이 정도는 남겨야지’, ‘내가 왜 이래야하지?’ 등 내가 손해보는 것 같은 기분을 우리에게 준다. 하나님은 우리를 위해 십자가를 지셨는데 사탄은 우리에게 하나님을 위해 손해보는 것 같은 기분을 느끼게 한다. 이런 생각이 들 때 마다 기도해야겠다. 
-물질의 주인이 하나님임을 절 때 잊지 않아야겠다. 
10. 영적터치(단어/구절) : 마음에 두다
