감옥에 다시 갖혀질수 있는 상황에서 굴하지 않고 하나님께 순종하며 풀려나자마자 생명의 복음을 선포하는 사도들의 모습을 볼수있다.
이제는 어떠한 강한 기득권 세력의 위협보다 하나님께 순종함으로 복음을 전하여 ''영혼구원''함이 최고의 가치인것을 깨우친다.
한편 28절에 보면 ''이 사람의 피를 우리에게 돌리고자 함이로다''를 대제사장 이 말하는 것으로 보아 십자가의 보혈이 누구에게는 찔림과 심판으로 받아들이는 자에게는 생명의 복음으로 나누어 지는 것을 알수있다. 
 
9. 적용(나)
생명의 십자가를 날마다 묵상하며 감사함으로 살아야겠다
10. 영적터치(단어/구절)
29절: 사람보다 하나님께 순종하는 것이 마땅하니라

11. 믿음과 회개 및 감사기도로 마무리
